    fn arithmetic_mean(&self, numbers: &[i32]) -> f64 {
        let sum = numbers.iter().sum();
        sum as f64 / numbers.len() as f64
    }

    fn geometric_mean(&self, numbers: &[i32]) -> f64 {
        let product = numbers.iter().product::<i32>();
        product as f64 / numbers.len() as f64
