        // Handle nested braces
        let (nested_end, inner) = parse_brace(input, end);
        end = nested_end + 1;
        output.push(inner);
    }
    if input[end..].starts_with(',') {
        // Handle alternation
        let mut alternatives = vec![];
        while input[end..].starts_with('{') {
            let (nested_end, inner) = parse_brace(input, end);
            end = nested_end + 1;
            alternatives.push(inner);
        }
        output.extend(alternatives.into_iter().map(|alt| format!("{{{}}}", alt)).collect::<Vec<String>>());
    } else {
        // Handle literal characters
        let mut literal = String::new();
        while !input[end..].starts_with('}') && !input[end..].starts_with(',') {
            literal.push(input[end]);
            end += 1;
        }
        output.push(literal);
    }
    (end, output.join(""))
}

