fn main() {
    let mut cusip = String::new();

    println!("Enter a CUSIP code: ");

    io::stdin().read_line(&mut cusip)
        .expect("Failed to read line");

    let cusip = cusip.trim();

    if cusip.len() != 9 {
        println!("Invalid CUSIP code: incorrect length");
        return;
    }

    let mut sum = 0;

    for (i, c) in cusip.chars().enumerate() {
        let v = match c {
            '0'..='9' => c as i32 - '0' as i32,
            'A'..='Z' => c as i32 - 'A' as i32 + 10,
            '*' => 36,
            '@' => 37,
            '#' => 38,
            _ => {
                println!("Invalid CUSIP code: invalid character");
                return;
            }
        };

        if i % 2 == 0 {
            v *= 2;
        }

        sum += (v / 10) + (v % 10);
    }

    let check_digit = ((10 - (sum % 10)) % 10) as char; // <-- change `u8` to `char`

    if cusip.chars().last() != Some(check_digit) {
        println!("Invalid CUSIP code: incorrect check digit");
        return;
    }

    println!("Valid CUSIP code");
}

