    file_names: HashMap<String, HashSet<u64>>,
    term_frequencies: HashMap<String, u32>,
}

impl SearchIndex {
    fn new() -> Self {
        Self {
            file_names: HashMap::new(),
            term_frequencies: HashMap::new(),
        }
    }

    fn add_file(&mut self, file_name: String) {
        let mut terms = HashSet::new();

        for line in BufReader::new(File::open(file_name).unwrap()).lines() {
            let term = &line.unwrap().to_lowercase();
            if !self.term_frequencies.contains_key(term) {
                self.term_frequencies.insert(term, 0);
            }

            terms.insert(term);
        }

        for term in terms {
            let freq = self.term_frequencies[&term] + 1;
            self.term_frequencies.insert(term, freq);
        }

        self.file_names.insert(file_name, terms);
    }

    fn search(&self, query: String) -> Vec<String> {
        let terms = &query.to_lowercase().split(' ').collect::<HashSet<&str>>();
        let mut results = HashSet::new();

        for term in terms {
