    // Read the starting square from input
    let mut input = String::new();
    std::io::stdin().read_line(&mut input).unwrap();
    let start: (i32, i32) = (input.trim().chars().nth(0).unwrap() as i32 - 'a' as i32, input.trim().chars().nth(1).unwrap() as i32 - '1' as i32);

    // Initialize the board and the sequence of moves
    let mut board = vec![vec![(0, 0); 8]; 8];
    let mut path = Vec::new();
    let mut x = start.0;
    let mut y = start.1;

    // Perform the knight's tour using Warnsdorff's heuristic
    for _ in 0..64 {
        board[x as usize][y as usize] = (x, y);
        path.push((x + 'a' as i32) as u8 as char);

        // Find the next move with the minimum number of onward moves
        let mut min_moves = 8;
        let mut next_move = (0, 0);
        for &(dx, dy) in &moves {
            let nx = x + dx;
            let ny = y + dy;
            if nx >= 0 && nx < 8 && ny >= 0 && ny < 8 && board[nx as usize][ny as usize] == (0, 0) {
                let mut count = 0;
                for &(ndx, ndy) in &moves {
                    if nx + ndx >= 0 && nx + ndx < 8 && ny + ndy >= 0 && ny + ndy < 8 && board[(nx + ndx) as usize][(ny + ndy) as usize] == (0, 0) {
                        count += 1;
                    }
                }
                if count < min_moves {
                    min_moves = count;
                    next_move = (nx, ny);
                }
            }
        }

        x = next_move.0;
        y = next_move.1;
    }

    // Print the path of the knight's tour
    for move in path {
        println!("{}", move);
    }
}

