    if numbers.is_empty() {
        return numbers;
    }

    let mut piles = vec![VecDeque::new(); numbers.len()];

    for &num in &numbers {
        let mut added = false;
        for pile in &mut piles {
            if pile.is_empty() || pile[0] >= num {
                pile.push_front(num);
                added = true;
                break;
            }
        }
        if !added {
            let least_full_pile = piles.iter().min_by_key(|pile| pile.len()).unwrap();
            least_full_pile.push_back(num);
        }
    }

    let mut min_heap: Vec<i32> = piles[0].clone().into();
    for i in 1..piles.len() {
        if !piles[i].is_empty() {
            min_heap.push(piles[i][0]);
        }
    }

