        min_heap.remove(0);
        sorted_numbers.push(min);

        for pile in &mut piles {
            if !pile.is_empty() && pile[0] == min {
                pile.pop_front();
                if !pile.is_empty() {
                    min_heap.push(pile[0]);
                }
            }
        }
    }

    sorted_numbers
}
