extern crate chrono;
use chrono::prelude::*;
use reqwest;
use std::fs;
use std::collections::HashMap;

fn main() {
    // Download and save the log file to a local file, e.g., "mlijobs.txt"
    let url = "http://rosettacode.org/resources/mlijobs.txt";
    let response = reqwest::blocking::get(url).unwrap().text().unwrap();
    fs::write("mlijobs.txt", response).unwrap();

    // Read the log file
    let content = fs::read_to_string("mlijobs.txt").unwrap();
    let lines: Vec<&str> = content.lines().collect();

    // Parse the log entries
    let mut max_licenses = 0;
    let mut times_with_max_licenses = Vec::new();
    let mut licenses_count: HashMap<String, i32> = HashMap::new();

    for line in lines {
        if line.contains("License OUT") {
            let parts: Vec<&str> = line.split(' ').collect();
            let datetime_str = &parts[2..6].join("_");
            let datetime: DateTime<Local> = DateTime::parse_from_str(datetime_str, "%Y/%m/%d_%H:%M:%S").unwrap().with_timezone(&Local);
            let job_id = parts[5];
            *licenses_count.entry(job_id.to_string()).or_insert(0) += 1;
        } else if line.contains("License IN") {
            let parts: Vec<&str> = line.split(' ').collect();
            let datetime_str = &parts[2..6].join("_");
            let datetime: DateTime<Local> = DateTime::parse_from_str(datetime_str, "%Y/%m/%d_%H:%M:%S").unwrap().with_timezone(&Local);
            let job_id = parts[5];
            *licenses_count.entry(job_id.to_string()).or_insert(0) -= 1;
        }
    }

    // Determine the maximum licenses that were out at any time
    for (_, count) in &licenses_count {
        if *count > max_licenses {
            max_licenses = *count;
            times_with_max_licenses.clear();
            times_with_max_licenses.push(Local::now()); // Assuming the last time is taken as a reference for now
        } else if *count == max_licenses {
            times_with_max_licenses.push(Local::now());
        }
    }

    println!("Maximum licenses out: {}", max_licenses);
    println!("Times at which maximum licenses were out: {:?}", times_with_max_licenses);
}

