    let mut graph = HashMap::new();

    // Initialize in-degree and graph
    for (&lib, deps) in dependencies.iter() {
        if !graph.contains_key(lib) {
            graph.insert(lib, Vec::new());
            in_degree.insert(lib, 0);
        }
        for &dep in deps {
            graph.entry(lib).or_default().push(dep);
            *in_degree.entry(dep).or_insert(0) += 1;
        }
