    let mut num = n;

    if num == 1 {
        return factors;
    }

    while num % 2 == 0 {
        factors.push(2);
        num /= 2;
    }

    let mut i = 3;
    while i * i <= num {
        while num % i == 0 {
            factors.push(i);
            num /= i;
        }
        i += 2;
    }

    if num > 1 {
        factors.push(num);
    }

    factors
}

fn get_k_almost_primes(k: usize) -> Vec<i64> {
    let mut almost_primes = Vec::new();
    let mut num = 2;

    while almost_primes.len() < 10 {
        let factors = prime_factors(num);
        if factors.len() == k {
            almost_primes.push(num);
        }
        num += 1;
    }

    almost_primes
}

fn main() {
    for k in 1..=5 {
        let primes = get_k_almost_primes(k);
        let s: Vec<String> = primes.iter()
            .map(|n| n.to_string())
            .collect();
        let s = s.join(" ");
        println!("k={} {}", k, s);
    }
}

