use std::str::FromStr;
use num::BigInt;

#[derive(Debug)]
enum Digit {
    Plus,
    Minus,
    Zero,
}

impl From<char> for Digit {
    fn from(c: char) -> Self {
        match c {
            '+' => Digit::Plus,
            '-' => Digit::Minus,
            '0' => Digit::Zero,
            _ => panic!("Invalid character"),
        }
    }
}

#[derive(Debug)]
struct BalancedTernary {
    digits: Vec<Digit>,
}

impl FromStr for BalancedTernary {
    type Err = String;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let mut digits = Vec::new();
        for c in s.chars() {
            if c == '+' || c == '-' || c == '0' {
                digits.push(Digit::from(c));
            } else {
                return Err(format!("Invalid character: {}", c));
            }
        }
        Ok(BalancedTernary { digits })
    }
}

impl BalancedTernary {
    fn to_bigint(&self) -> BigInt {
        let mut result = BigInt::from(0);
        let power = self.digits.len() as u32 - 1;
        for (i, digit) in self.digits.iter().enumerate() {
            let exponent = power - i as u32;
            match *digit {
                Digit::Plus => result += BigInt::from(3).pow(exponent),
                Digit::Minus => result -= BigInt::from(3).pow(exponent),
                Digit::Zero => (),
            }
        }
        result
    }

    fn from_bigint(value: BigInt) -> Self {
        if value == 0 {
            return BalancedTernary { digits: vec![Digit::Zero] };
        }

        let mut n = value;
        let mut digits = Vec::new();

        while n != 0 {
            let rem = n % 3;

            match rem {
                1 => {
                    digits.push(Digit::Plus);
                    n = (n - 1) / 3;
                }
                2 | -1 => {
                    digits.push(Digit::Minus);
                    n = (n + 1) / 3;
                }
                _ => {
                    digits.push(Digit::Zero);
                    n /= 3;
                }
            }
        }

        // Reverse to get the correct order
        digits.reverse();
        BalancedTernary { digits }
    }
}

fn convert_to_balanced_ternary(input: &str) -> String {
    let bigint = BigInt::from_str(input).expect("Failed to parse input string");
    let bt = BalancedTernary::from_bigint(bigint);

    // Convert the balanced ternary digits back to a string
    let mut result = String::new();
    for digit in &bt.digits {
        match digit {
            Digit::Plus => result.push('+'),
            Digit::Minus => result.push('-'),
            Digit::Zero => result.push('0'),
        }
    }
    result
}

fn main() {
    let input_str = "5";
    let bt_str = convert_to_balanced_ternary(input_str);
    println!("Balanced ternary representation of {} is: {}", input_str, bt_str);
}

