use std::collections::BTreeMap;
use std::fs;
use std::io;

fn read_files(directory: &str) -> BTreeMap<String, String> {
    let mut files = BTreeMap::new();
    for entry in fs::read_dir(directory).unwrap() {
        let entry = entry.unwrap();
        let path = entry.path();
        if path.is_file() {
            let content = fs::read_to_string(path).unwrap();
            files.insert(entry.file_name().to_str().unwrap().to_string(), content);
        }
    }
    files
}

fn build_inverted_index(files: &BTreeMap<String, String>) -> BTreeMap<String, Vec<String>> {
    let mut index = BTreeMap::new();
    for (filename, content) in files {
        let words: Vec<String> = content
            .split_whitespace()
            .map(|word| word.to_lowercase())
            .collect();

        let unique_words: Vec<String> = words.into_iter().filter(|word| {
            !word.is_empty() && word.chars().all(char::is_alphanumeric)
        }).collect();

        for word in unique_words {
            index
                .entry(word)
                .and_modify(|files: &mut Vec<String>| { 
                    if !files.contains(filename) { 
                        files.push(filename.clone()); 
                    } 
                })
                .or_insert(vec![filename.clone()]);
        }
    }
    index
}

fn search(index: &BTreeMap<String, Vec<String>>, query: &str) -> Vec<String> {
    let terms: Vec<String> = query.split_whitespace().map(|t| t.to_lowercase()).collect();
    if terms.is_empty() {
        return vec![];
    }

    let mut results = Vec::new();
    for term in terms {
        if let Some(files) = index.get(&term) {
            results.extend_from_slice(files);
        }
    }

    results.sort();
    results.dedup();

    results
}

