use std::env;

fn josephus(n: usize, k: usize) -> usize {
    let mut res = 0;
    for i in 2..=n {
        res = (res + k) % i;
    }
    res
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() != 4 {
        eprintln!("Usage: {} <n> <k> <m>", args[0]);
        return;
    }

    let n: usize = args[1].parse().unwrap();
    let k: usize = args[2].parse().unwrap();
    // For this solution, m is ignored as it's not part of the standard Josephus problem
    let _m = &args[3];  // Borrow instead of moving

    let survivor = josephus(n, k);
    println!("{}", survivor);
}
