use std::env;

fn levenshtein(word1: &str, word2: &str) -> i32 {
    let len1 = word1.len();
    let len2 = word2.len();

    if len1 == 0 {
        return len2 as i32;
    }
    if len2 == 0 {
        return len1 as i32;
    }

    // Initialize a matrix with (len1+1) rows and (len2+1) columns
    let mut matrix = vec![vec![0; len2 + 1]; len1 + 1];

    // Fill the first row and column
    for i in 0..=len1 {
        matrix[i][0] = i as i32;
    }
    for j in 0..=len2 {
        matrix[0][j] = j as i32;
    }

    // Fill the rest of the matrix
    for i in 1..=len1 {
        for j in 1..=len2 {
            let cost = if word1.chars().nth(i - 1) == word2.chars().nth(j - 1) {
                0
            } else {
                1
            };

            matrix[i][j] = (matrix[i - 1][j] + 1)
                .min(matrix[i][j - 1] + 1)
                .min(matrix[i - 1][j - 1] + cost);
        }
    }

    matrix[len1][len2]
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() != 3 {
        eprintln!("Usage: {} <word1> <word2>", args[0]);
        std::process::exit(1);
    }

    let word1 = &args[1];
    let word2 = &args[2];

    println!("{}", levenshtein(word1, word2));
}

