fn build_expressions(current: String, index: usize, digits: &str) -> Vec<(String, i64)> {
    if index == digits.len() {
        let terms = parse_terms(&current);
        let sum = terms.iter().sum::<i64>();
        return vec![(current.clone(), sum)];
    }

    let mut results = Vec::new();

    // Option 1: Append the next character without operator
    let next_char = &digits[index..index + 1];
    let new_current_append = if current.is_empty() {
        next_char.to_string()
    } else {
        format!("{}{}", current, next_char)
    };

    let append_results = build_expressions(new_current_append.clone(), index + 1, digits);
    results.extend(append_results);

    // Option 2: Insert '+'
    if !current.is_empty() {
        let new_current_plus = format!("{}+{}", current, next_char);
        let plus_results = build_expressions(new_current_plus, index + 1, digits);
        results.extend(plus_results);
    }

    // Option 3: Insert '-'
    if !current.is_empty() {
        let new_current_minus = format!("{}-{}", current, next_char);
        let minus_results = build_expressions(new_current_minus, index + 1, digits);
        results.extend(minus_results);
    }

    results
}

fn parse_terms(s: &str) -> Vec<i64> {
    let re = Regex::new(r"([+-]?\d+)").unwrap();
    let mut terms = Vec::new();
