fn split_string(s: &str) -> Vec<String> {
    let mut result = Vec::new();
    let mut current = String::new();
    let mut escape_next = false;

    for c in s.chars() {
        if escape_next {
            current.push(c);
            escape_next = false;
        } else {
            match c {
                '^' => escape_next = true,
                '|' => {
                    result.push(current.clone());
                    current.clear();
                }
                _ => current.push(c),
            }
        }
    }

    if !current.is_empty() {
        result.push(current);
    }

    result
}

fn main() {
    let test_string = "hello^|world|rust";
    let result = split_string(test_string);
    println!("{:?}", result);
}

