pub fn topo_sort(dependencies: HashMap<String, Vec<String>>) -> Vec<String> {
    // Collect all unique libraries
    let mut all_libs: HashMap<String, Vec<String>> = HashMap::new();

    for (lib, deps) in &dependencies {
        all_libs.insert(lib.clone(), vec![]);
        for dep in deps {
            if !all_libs.contains_key(dep) {
                all_libs.insert(dep.clone(), vec![]);
            }
        }
    }

    // Build adjacency list and calculate in-degrees
    let mut adj: HashMap<String, Vec<String>> = HashMap::new();
    let mut in_degree: HashMap<String, i32> = HashMap::new();

    for (lib, deps) in &dependencies {
        for dep in deps {
            if dep != lib {
                adj.entry(dep.clone())
                    .and_modify(|libs| libs.push(lib.clone()))
                    .or_insert(vec![lib.clone()]);

                *in_degree.entry(lib.clone()).or_insert(0i32) += 1;
            }
        }
    }

    // Initialize queue with nodes having zero in-degree
    let mut queue: Vec<String> = Vec::new();
    let mut result: Vec<String> = Vec::new();

    for lib in all_libs.keys() {
        if !in_degree.contains_key(lib) || *in_degree.get(lib).unwrap() == 0 {
            queue.push(lib.clone());
        }
    }

    while !queue.is_empty() {
        let current = queue.first().cloned();
        queue.pop();

        if let Some(current) = current {
            result.push(current.clone());

            // If current has dependents, decrease their in-degree
            if let Some(neighbors) = adj.get(&current) {
                for neighbor in neighbors {
                    *in_degree.entry(neighbor.clone()).or_insert(0i32) -= 1;

                    if *in_degree.get(neighbor).unwrap() == 0 {
                        queue.push(neighbor.clone());
                    }
                }
            }
        }
    }

    // Check if all nodes are processed (no cycles)
    if result.len() != all_libs.keys().count() {
        panic!("Cycle detected; topological sort not possible");
    }

    result
}

