use std::collections::HashMap;

fn van_eck(n: u32) -> u32 {
    if n == 0 {
        return 0;
    }

    let mut current = 0; // a(0) = 0
    let mut last_seen = HashMap::new();
    last_seen.insert(current, 0); // record that 0 was seen at index 0

    for i in 1..=n {
        let prev = current;

        match last_seen.get(&prev) {
            Some(last_index) => {
                current = (i - 1) - *last_index;
            }
            None => {
                current = 0;
            }
        }

        // Update the hashmap for 'prev' to have the latest index
        let last_i = i - 1;
        last_seen.insert(prev, last_i);
    }

    current
}

