pub fn crt(mods: Vec<i32>, remainders: Vec<i32>) -> Result<i32, String> {
    let mut product = 1;
    let mut sum = 0;

    // Check if all moduli are pairwise coprime
    for i in 0..mods.len() {
        if i > 0 && !coprime(product, mods[i]) {
            return Err("Moduli must be pairwise coprime.".to_string());
        }

        product *= mods[i];
    }

    // Solve for each term
    for (m, a) in zip(mods, remainders) {
        let m_inv = mod_inverse(std::gcd(augment_modulus(product / m), m));
        sum += a * ((product / m) * m_inv);
    }

    Ok(sum % product)
}

pub fn mod_inverse(x: i32, y: i32) -> Result<i32, String> {
    let old_y = 1;
    let y = y;

    if x == 0 {
        return Err("Modular inverse doesn't exist.".to_string());
    }

    // Perform extended Euclidean algorithm
    while y != 0 {
        let quotient = x / y;

        let temp = y;
        y = x % y;
        x = temp;

        let temp2 = old_y;
        old_y = y;
        y = temp2 - quotient * y;
    }

    Ok(old_y)
}

