    sorted_points.sort_by(compare_angle);

    if sorted_points.len() <= 1 {
        return sorted_points;
    }

    let mut lower = Vec::new();
    for p in sorted_points {
        while lower.len() >= 2 && cross_prod(&lower[lower.len() - 1], &lower[lower.len() - 2], &p) < 0 {
            lower.pop_back();
        }
        lower.push(p);
    }

    let mut upper = Vec::new();
    for p in sorted_points.reverse() {
        while upper.len() >= 2 && cross_prod(&upper[upper.len() - 1], &upper[upper.len() - 2], &p) < 0 {
            upper.pop_back();
        }
        upper.push(p);
    }

    let hull = lower.into_iter().chain(upper.into_iter()).collect();
    if hull.len() > 1 && cross_prod(&hull[hull.len() - 1], &hull[hull.len() - 2], &pivot) == 0 {
        hull.pop_back();
    }

