use std::path::PathBuf;

fn has_extension(filename: &str) -> bool {
    let extensions_lower = extensions.iter()
        .map(|ext| PathBuf::new(ext).to_string().to_lowercase())
        .collect::<std::collections::HashSet<PathBuf>>();

    for part in filename.split(".").skip(1) {
        if part.is_empty() {
            return false;
        }

        let lower_part = &part.to_string().to_lowercase();
        if extensions_lower.contains(lower_part) {
            return true;
        }
    }

    false
}

fn contains_extension(filename: &str) -> bool {
    for comp in filename.split(".") {
        let stripped_comp = comp.strip()
            .map(|s| s.as_str().unwrap_or(""))
            .next();

        if !stripped_comp.is_empty() {
            for substr_length in 1..=stripped_comp.len() {
                let substr = &stripped_comp[0(substr_length as usize)];
                if extensions.iter()
                    .any(|ext|
                        PathBuf::new(ext).to_string().to_lowercase().starts_with(substr)
                    ) {
                        return true;
                    }
            }
        }
    }

    false
}

fn main() -> std::io.ResultSet {
    let result1 = has_extension("file.txt");
    println!("Does 'file.txt' have an extension? {}", result1);

    let result2 = contains_extension("image.jpg");
    println!("Does 'image.jpg' contain any extension pattern? {}", result2);
}

