fn ffr(n: usize) -> usize {
    if n == 1 {
        return 1;
    }

    let mut R = vec![1];
    let mut S = vec![2];
    let mut used = vec![false; 3]; // Using a vector of booleans for faster lookups

    used[0] = true; // Mark 1 as used
    used[1] = true; // Mark 2 as used

    for _ in 2..=n {
        let next_r = R[R.len() - 1] + S[S.len() - 1];
        R.push(next_r);

        // Mark the new value as used
        used[next_r as usize] = true;

        // Find next available s_candidate
        let mut s_candidate = S[S.len() - 1] + 1;
        while used[s_candidate as usize] {
            s_candidate += 1;
        }
        S.push(s_candidate);
    }

    R.last().unwrap()
}

fn ffs(n: usize) -> (usize, usize) {
    if n == 1 {
        return (2, 1);
    }

    let mut R = vec![1];
    let mut S = vec![2];
    let mut used = vec![false; 3]; // Using a vector of booleans for faster lookups

    used[0] = true; // Mark 1 as used
    used[1] = true; // Mark 2 as used

    for _ in 2..=n {
        // Find next available s_candidate
        let mut s_candidate = S[S.len() - 1] + 1;
        while used[s_candidate as usize] {
            s_candidate += 1;
        }
        S.push(s_candidate);

        // Mark the new value as used
        used[s_candidate as usize] = true;

        R.push(R[R.len() - 1] + s_candidate);
    }

    (*S.last().unwrap(), *R.last().unwrap())
}

