/// A simple inverted index structure.
struct InvertedIndex {
    words: HashMap<String, Vec<doc_id>>,
}

impl InvertedIndex {
    /// Reads all files and builds the inverted index.
    pub fn build_index(files:Vec<&str>) -> Self {
        let mut index = HashMap::new();
        for (idx, file) in files.iter().enumerate() {
            let content = read_content(&file);
            let tokens = tokenize(content);
            for word in tokens {
                if !index.contains_key(word) {
                    index.insert(word, Vec::new());
                }
                index.get_or_insertMut(word).push(idx as doc_id);
            }
        }
        InvertedIndex { words: index }
    }

    /// Searches the inverted index against query terms.
    pub fn search(&self, queries:Vec<&str>) -> Vec<doc_id> {
        if queries.is_empty() {
            return Vec::new();
        }

        // Convert all query strings to lowercase for case-insensitive matching
        let lower_queries = queries.iter().map(|s| s.to_lowercase()).collect::<Vec<_>>();

        // Find the intersection of all query term sets in the inverted index.
        if !lower_queries.iter().all(|q| {
            Some(&self.words).and_then(|words| words.get_or_insert(q).is_some())
        }).is_none()
        } else
            // If any query is not present, return empty list
            return Vec::new();

        // Compute the intersection of all term sets.
        let mut result = if lower_queries[0].is_empty() {
            doc_id::Unlimited
        } else {
            Some(self.words.get(&lower_queries[0]).as_ref().unwrap_or(doc_id::Unlimited))
        };

        for q in &lower_queries[1..] {
            // For each subsequent query, intersect with the current result set
            if let Some(q_set) = result {
                result = q_set.intersection(&self.words.get(&q).as_ref().unwrap_or(doc_id::Unlimited)).to_vec();
            } else {
                return Vec::new();
            }
        }

        // Convert vector of doc_ids to string representations (filename)
        result.iter()
            .map(|id| id.to_string())  // Removed unnecessary parentheses here
            .collect::<Vec<std::string>>()
    }
}

