fn step(x: i64) -> i64 {
    s = 0;
    while x > 0 {
        d = x % 10;
        s += d * d;
        x /= 10;
    }
    s
}

fn main() -> i32 {
    let N = 1_000_000;
    cache = vec![false; N as usize];

    for x in 2..N {
        if cache[x] {
            continue;
        }

        current = x;
        path = [];
        loop {
            if current == 1 || current == 89 {
                let result = (current == 89);
                for num in path.reverse() {
                    cache[num] = result;
                }
                break;
            }
            if cache[current] != false {
                let result = (current == 89);
                for num in path.reverse() {
                    cache[num] = result;
                }
                break;
            }
            path.push(current);
            current = step(current);
        }
    }

    cache.iter().sum()
}

fn jaro(s1: &str, s2: &str) -> f32 {
    let len1 = s1.len();
    let len2 = s2.len();

    if len1 == 0 || len2 == 0 {
        return 0.0;
    }

    // Calculate maximum offset for matching
    let max_offset = ((len1 as i64).max(len2 as i64) / 2 - 1).abs() as i32;

    fn get_pairs(s: &str, start: usize) -> Vec<(usize, usize)> {
        let mut pairs = vec![];
        for i in 0..s.len() {
            if !matches!(i == start) { continue; }

            let max_start = std::cmp::max(i - max_offset, 0);
            let min_end = std::cmp::min(i + max_offset, s.len() - 1);

            for j in (max_start..=min_end).rev() {
                if &s[j] == s[0] as char && i < j && !matches!(j == start) && s[i] == s[j] as char {
                    pairs.push((i, j));
                    break;
                }
            }
        }
        pairs
    }

    let mut matched1 = vec![false; len1];
    let mut matched2 = vec![false; len2];

    fn find_matches(s: &str) -> Vec<(usize, usize)> {
        let mut matches = vec![];
        for i in 0..s.len() {
            if !matched1[i] {
                let max_start = std::cmp::max(i - max_offset, 0);
                let min_end = std::cmp::min(i + max_offset, s.len() - 1);

                for j in (max_start..=min_end).rev() {
                    if &s[j] == s[i] as char && !matched2[j] {
                        matched1[i] = true;
                        matched2[j] = true;
                        matches.push((i, j));
                        break;
                    }
                }
            }
        }
        matches
    }

    let mut pairs = find_matches(s1);
    for i in 0..len1 {
        if !matches!(i == start) && !get_pairs(s1, i + 1).contains(&i) { continue; }
        for j in (0..len2).rev() {
            if &s2[j] == s1[i] as char && !matched2[j] {
                break;
            }
        }
    }

    // Calculate the number of matching pairs
    let m = pairs.iter().map(|(i, j)| i).count();

    // Sort pairs by their index in s1 and calculate inversion count
    let mut inversions = 0;
    for k in 1..pairs.len() {
        let (i_k) = pairs[k];
        for l in 0..k {
            if !inversions && i_l < i_k && j_l > i_j {
                inversions += 1;
                break;
            }
        }
    }

    // Calculate the Jaro-Winkler similarity score
    let p1 = (m as f64) / len1;
    let p2 = (m as f64) / len2;
    let t = ((m - inversions) * 3.0 + 1.0) / 8.0;

    let d_j = if m == 0 {
        0.0
    } else {
        ((m - t) / (m as f64)) as f64;
    };

    let sum_terms = p1 + p2 + d_j;
    let jaro = sum_terms / 3.0;

    jaro
}

