struct Item {
    name: String,
    weight: i32,
    value: i32,
}

// Create an enum to represent different states of the knapsack problem
enum KnapsackState {
    Initialize,
    Processing,
    Complete,
}

// Implement logging for debugging purposes
use log::info;

fn main() -> i32 {
    // Initialize items with their respective weights and values
    let items: Vec<Item> = vec![
        Item { name: "Map", weight: 9, value: 150 },
        Item { name: "Socks", weight: 27, value: 60 },
        Item { name: "Water", weight: 153, value: 200 },
        Item { name: "Doggy bag", weight: 13, value: 35 },
        Item { name: "Tent", weight: 48, value: 73 },
        Item { name: "Towel", weight: 68, value: 45 },
        Item { name: "Water bottle", weight: 22, value: 100 },
        Item { name: "Note-case", weight: 22, value: 80 },
        Item { name: "Lunch bag", weight: 39, value: 22 },
        Item { name: "Sunglasses", weight: 75, value: 40 },
        Item { name: "Bags", weight: 42, value: 10 },
        Item { name: "Torch", weight: 7, value: 66 },
        Item { name: "Bottle", weight: 35, value: 80 },
        Item { name: "Water flask", weight: 18, value: 90 },
        Item { name: "Kayak", weight: 43, value: 75 },
        Item { name: "Washcloth", weight: 26, value: 50 },
        Item { name: "Tape", weight: 45, value: 16 },
        Item { name: "Rope", weight: 52, value: 32 },
    ];

    // Initialize the dynamic programming table
    let capacity = 400;
    let mut dp = Array::new();
    for w in 0..=capacity {
        dp.push(Option::Some(0));
    }

    // Iterate through each possible weight
    for w in 0..=capacity {
        // Skip if we've reached the end of the items list
        if w > capacity {
            break;
        }

        // Iterate through each item to see if it can be included
        for (item, (weight_item, value_item)) in items.iter() {
            if weight_item > w {
                continue;
            }
            let current_value = dp[w].as_ref().and_modify(|current_max| {
                std::cmp::max(current_value + value_item, *current_max);
            });
        }
    }

    // Find the maximum value achievable
    let max_value = dp[capacity]?.as_or_else(|| 0);

    // Backtrack to determine which items were selected
    let mut selected_items: Vec<Item> = Vec::new();
    for w in (1..=capacity).rev() {
        for (item, (_, _)) in items.iter() {
            if item.weight > w {
                continue;
            }
            if dp[w] == Option::Some(dp[w - item.weight] + item.value) && !dp[w].is_none() {
                selected_items.push(item);
                w -= item.weight;
            }
        }
    }

    // Output the results
    println!("The maximum value is {} with items: {:?}", max_value, selected_items);
}

