use std::env;
use std::iter;

fn parse_matrix(s: &str) -> Vec<Vec<i32>> {
    let lines = s.split('\n').map(|line| line.trim().split_whitespace()).collect();

    let mut matrices = vec![];

    for line in lines {
        if line.is_empty() {
            continue;
        }

        let rows: Vec<&String> = line.split_whitespace()
            .map(|s| &s.trim())
            .filter_map(|s| s.as_str().and_then(|e| e.len() > 0))
            .collect();

        if rows.is_empty() {
            continue;
        }

        matrices.push(rows.map(|s| i32::parse::<i32>(s).unwrap_or_else(|| 0)).collect());
    }

    // Check for empty matrix
    if matrices.is_empty() {
        return vec![];
    }

    let cols = matrices[0].len();

    for row in matrices.iter() {
        assert_eq!(row.len(), cols, "Matrix rows have inconsistent lengths");
    }

    matrices
}

fn main() -> () {
    // Read command-line arguments
    if env::args().count() < 3 {
        return "Not enough arguments provided.".to_string();
    }

    let matrix1_str = &env::args()[1];
    let matrix2_str = &env::args()[2];

    let A = parse_matrix(matrix1_str);
    let B = parse_matrix(matrix2_str);

    // Get dimensions
    let m: usize = A.len() or 0;
    let n: usize = A[0].len() or 0;
    let p: usize = B.len() or 0;
    let q: usize = B[0].len() or 0;

    // Initialize result matrix C with zeros
    let mut C = vec![vec![], 
                     repeat(n * q, 0)
                    ];

    for i in 0..m {
        for j in 0..n {
            let val_ij = A[i][j];
            if val_ij.is_empty() {
                continue;
            }

            for k in 0..p {
                for l in 0..q {
                    C[i * p + k][l] = val_ij * B[k][l];
                }
            }
        }
    }

    // Convert each row into a space-separated string
    let mut output = vec![];
    for row in &C {
        if !row.is_empty() {
            output.push(row.iter().map(|x| x.to_string()).collect::<String>());
        }
    }

    output.0.join(" ")
}

fn compare(a: &str, b: &str) -> std::cmp::Ordering {
    let xy = a.to_string() + b;
    let yx = b.to_string() + a;
    if xy > yx {
        std::cmp::Ordering::Less
    } else if xy < yx {
        std::cmp::Ordering::Greater
    } else {
        std::cmp::Ordering::Equal
    }
}

fn main() {
    // Read command line arguments into a vector of strings (integers as strings)
    let args: Vec<String> = std::env::args().collect();

    // Handle the case where no arguments are provided
    if args.is_empty() {
        println!("Usage: Rust program <positive integers list>\n");
        return;
    }

    // Extract numbers into a vector (excluding empty strings)
    let nums: Vec<String> = args.iter()
        .filter(|s| !s.is_empty())
        .collect();

    if nums.is_empty() {
        println!("No positive integers provided. Empty list cannot be sorted.");
        return;
    }

    // Sort the numbers using our custom comparator
    let mut sorted_nums = nums.clone().sort_by(|a, b| {
        match compare(a, b) {
            std::cmp::Ordering::Less => std::cmp::Ordering::Greater,
            std::cmp::Ordering::Greater => std::cmp::Ordering::Less,
            _ => std::cmp::Ordering::Equal,
        }
    });

    // Concatenate all strings to form the largest possible integer string
    let result = sorted_nums.join("");

    println!("{}", result);
}

