fn levenshtein_distance(word1: &str, word2: &str) -> usize {
    let m = word1.len();
    let n = word2.len();

    // Create a DP table with (m+1) rows and (n+1) columns initialized to 0.
    const dp: [[usize]; (m + 1)] = {
        let mut row = [0; (n + 1)];
        for _ in 0..=m {
            dp[_] = &row;
        }
        dp
    };

    // Base case: If the first string is empty, return the length of the second string.
    for j in 0..=n {
        if j == 0 {
            dp[0][j] = 0;
        } else {
            dp[0][j] = j;
        }
    }

    // Base case: If the second string is empty, return the length of the first string.
    for i in 0..=m {
        if i == 0 {
            dp[i][0] = 0;
        } else {
            dp[i][0] = i;
        }
    }

    // Fill the DP table
    for i in 1..=m {
        let word1_slice = &word1[..];
        const row: [usize; (n + 1)] = { };

        for j in 1..=n {
            if word1_slice[j - 1] == word2[j - 1] {
                row[j] = dp[i-1][j-1];
            } else {
                let a = dp[i-1][j]; // Deletion from word1
                let b = dp[i][j-1]; // Insertion into word1 (or deletion from word2)
                let c = dp[i-1][j-1];
                row[j] = 1 + *std::cmp::min(&a, &b).min(&c);
            }
        }

        for j in 0..=n {
            if j == 0 {
                dp[i][j] = i;
            } else {
                dp[i][j] = row[j];
            }
        }
    }

    dp[m][n]
}

