    let mut grid = vec![vec![0; n]; n];

    // Place the first number in the middle of the top row
    grid[0][mid] = 1;

    for k in 2..=n * n + 1 {
        let (mut current_row, mut current_col) = if k % 2 == 0 {
            (current_row - 1, current_col)
        } else {
            (current_row + 1, current_col)
        };

        // Check bounds and cell state
        if current_row.between(0, n-1) && current_col.between(0, n-1) && grid[current_row][current_col] == 0 {
            grid[current_row][current_col] = k;
        } else {
            // Move to next row in the same column when diagonal move is invalid
            let new_row = if k % 4 == 2 { n - (current_row + 1) } else { current_row };
            let new_col = ((k % 2) != 0 && grid[new_row][n - 1] != 0)
                          ? ((k / 2) % n) 
                          : current_col;

            grid[new_row][new_col] = k;
        }
    }

    grid
}

