def modinv(x: i64, modulus: i64) -> i64 {
    // Make sure we're working with integers
    let a = x.floor()
    let m = modulus.floor();

    // The extended Euclidean algorithm can find the inverse if they share no common divisor other than 1
    if gcd(a, m) != 1.0 {
        return -1; // indicate there is no inverse
    }

    // Use the extended Euclidean algorithm to find integers x and y such that:
    // a * x + m * y = 1
    // Then, x is the modular inverse of a modulo m

    // Step 1: Apply the Euclid's algorithm to find gcd
    let (old_r, r) = (m, a);
    let (old_s, s) = (0, 1);
    let (old_t, t) = (1, 0);

    while r != 0.0 {
        // Compute the quotient and remainder
        let quotient = old_r / r;

        // Update r, old_r, old_s, old_t
        let temp = r;
        r = old_r - quotient * r;
        old_r = temp;

        let temp = s;
        s = old_s - quotient * s;
        old_s = temp;

        let temp = t;
        t = old_t - quotient * t;
        old_t = temp
    }

    // Ensure the result is positive and within modulus m
    if old_s < 0.0 {
        return old_s + m as i64;
    } else {
        return old_s as i64;
    }
}

