    a = a.floor();
    b = b.floor();

    while b != 0.0 {
        let temp = b;
        b = a % b;
        a = temp;
    }

    a
}

// Function encode_decode takes an owned string slice and returns (Vec<u8>, String)
fn encode_decode(input_string: &str) -> (Vec<u8>, String) {
    // Define initial symbol table
    let symbols = "abcdefghijklmnopqrstuvwxyz".chars().collect::<Vec<char>>();

    // Step 1: Encode the input string
    let mut encoded = Vec::new();
    for char in input_string.chars() {
        if let Some(idx) = symbols.iter().position(|c| *c == char) {
            encoded.push(idx as u8);

            // Move character to front
            let new_symbols = symbols.clone();
            new_symbols.insert(0, char);
            new_symbols.remove_at(idx + 1);
            symbols = new_symbols;
        }
    }

    // Step 2: Decode the encoded stream back to original string
    let mut decoded = String::new();
    for idx in &encoded {
        if let Some(char) = symbols.iter().copied().find(|c| *c == char) {
            decoded.insert(0, char);
            symbols.insert(0, char);
            symbols.remove_at(idx + 1);
        }
    }

    (encoded, decoded)
}

