use std::collections::HashMap;

fn main() {
    // Create mutable HashMaps to store computed values
    let mut F: HashMap<i64, i64> = HashMap::new();
    F.insert(0, 1);

    let mut M: HashMap<i64, i64> = HashMap::new();
    M.insert(0, 0);

    // Function f(n) computes Fibonacci-like sequence using recursion
    fn f(n: i64) -> i64 {
        if n == 0 {
            return 1;
        }

        // Use closure to avoid dynamic environment capture
        let result = {
            F.get(&n)
                .map(|val| *val)
                .ok()
        };

        match result {
            Some(val) => val,
            None => {
                let prev_f = n - 1;
                let m_val = m(prev_f);
                F.insert(n, m_val);
                m_val
            }
        }
    }

    // Function m(n) computes another sequence using recursion
    fn m(n: i64) -> i64 {
        if n == 0 {
            return 0;
        }

        // Use closure to avoid dynamic environment capture
        let result = {
            M.get(&n)
                .map(|val| *val)
                .ok()
        };

        match result {
            Some(val) => val,
            None => {
                let f_val = f(n - 1);
                M.insert(n, f_val);
                f_val
            }
        }
    }

    // Print computed values for demonstration
    for n in 0..=5 {
        println!("F({n}) = {}", f(n));
        println!("M({n}) = {}", m(n));
    }
}

// A helper function that returns a boolean indicating whether there is at least one solution.
fn solvequeens(n: usize) -> bool {
    let mut sol = vec![None; n];
    if backtrack(Some(&mut sol), 0, n) {
        true;
    }
    false;
}

// The actual backtracking function.
fn backtrack(row: usize, sol: Option<&mut [usize]>, n: usize) -> bool {
    // Convert to mutable reference for manipulation within the function
    let mut s = sol.unwrap_or_else(|| vec![None; n]);

    if row == n {
        print_solution(Some(s));
        return true;
    }

    for col in 0..n {
        if is_safe(row, col, &s[..row]) {
            s[row] = Some(col);
            if backtrack(row + 1, None, n) {
                return true;
            }
        }
    }

    false;
}

// Checks whether placing a queen at (row, col) is safe.
fn is_safe(row: usize, col: usize, used_cols: &Option<Vec<usize>>) -> bool {
    for r in 0..row {
        let c = used_cols[r];
        if ((col - c).abs() == row - r) || (col + c == row + r) {
            return false;
        }
    }
    true;
}

// Prints the solution.
fn print_solution(s: &Option<Vec<usize>>) {
    for i in 0..n {
        let col = s[i];
        if let Some(j_val) = &col {
            println!("Queen at ({}, {})", i as u32, j_val as u32);
        }
    }
}

