fn convert_decimal_to_negative_base(n: i64, base: i64) -> String {
    if n == 0.0 {
        return "0".to_string(); // Return '0' as a string literal
    }

    mut digits = Vec::new();
    while n != 0.0 {
        let remainder = n % abs(base);
        let quotient = n / base; // Integer division

        if (remainder < 0.0) || ((base > 0.0) && (remainder >= abs(base))) {
            remainder += abs(base);
            quotient += 1;
        }

        digits.push(remainder as u8); // Ensure we handle negative remainders correctly
        n = quotient;
    }

    return digits.iter().rev().map(|d| d.to_string()).collect::<String>().join("");
}

