    let last_two = n % 100;
    if (last_two >= 11 && last_two <= 13) {
        return format!("{}.{}", n, "th");
    }
    let last_digit = last_two % 10;
    match last_digit {
        1 => format!("{}.st{}", n),
        2 => format!("{}.nd{}", n),
        3 => format!("{}.rd{}", n),
        _ => format!("{}.th{}", n),
