use std::random;

fn main() {
    let treat = [85, 88, 75, 66, 25, 29, 83, 39, 97];
    let contr = [68, 41, 10, 49, 16, 65, 32, 92, 28, 98];

    let n = treat.len();
    let m = contr.len();

    // Calculate observed effect difference
    let sum_treat = treat.iter().sum::<f64>();
    let sum_contr = contr.iter().sum::<f64>();
    let obs_diff = (sum_treat / n) - (sum_contr / m);

    // Set random seed for reproducibility
    random.seed(42);

    const num_permutations: usize = 10**5;
    let mut count_less_or_equal = 0;
    let mut count_greater = 0;

    // Perform Monte Carlo permutations
    for _ in 0..num_permutations {
        // Randomly select 'n' indices from the combined pool of treated and control subjects
        let selected = random.sample((0..(n + m)).collect(), n);

        // Calculate sum for treatment group based on selected samples
        let mut sum_t = 0.0;
        for i in selected {
            sum_t += treat[i] as f64;
        }

        // Find remaining indices and calculate control group sum
        let mut remaining = Vec::with_indices((0..(n + m)).complement());

        let mut sum_c = 0.0;
        for j in remaining.iter() {
            sum_c += contr[j as usize] as f64;
        }

        // Calculate simulated effect difference
        let simulated_diff = (sum_t / n) - (sum_c / m);

        if obs_diff + 1e-9 >= simulated_diff {
            count_less_or_equal += 1;
        } else {
            count_greater += 1;
        }
    }

    // Calculate and print percentages
    let p_le = ((count_less_or_equal as f64) / num_permutations * 100.0).round();
    let p_gt = ((count_greater as f64) / num_permutations * 100.0).round();

    println!("Expected percentage <={:.1f}%: {:3}%;\n", obs_diff, p_le);
    println!("Expected percentage >{:.1f}%: {:3}\%", obs_diff, p_gt);
}

use std::env;
use std::vec::Vec;

fn generate_permutations(n: usize) -> Vec<Vec<i32>> {
    if n == 0 {
        return vec![vec![]];
    }

    let mut arr = (0..n).to_vec();
    let mut result = Vec::new();

    fn permute(start: usize) {
        if start == n - 1 {
            result.push(arr.clone());
            return;
        }

        for i in (start..n).rev() {
            arr.swap(start, i);
            permute(start + 1);
            arr.swap(start, i);
        }
    }

    permute(0);
    result
}

