/// Function to calculate inversion count for a permutation
fn calculate_inversion_count(mut perm: Vec<char>) -> i32 {
    let mut count = 0;
    for (i, &a) in perm.iter() {
        for (j, b) in perm[i + 1..].iter() {
            if a > b {
                count += 1;
            }
        }
    }
    // Determine the sign based on inversion count
    if count % 2 == 0 {
        return 1;
    } else {
        return -1;
    }
}

/// Generates all permutations of three items and calculates their signs (even/-1 odd)
fn generate_permutations_and_signs() -> Vec<(Vec<char>, i32)> {
    // Generate base permutation
    let perms = vec![vec!['A', 'B', 'C']];

    // Calculate sign for each possible next state
    let signs = [
        calculate_inversion_count(vec!['A', 'B', 'C']),
        calculate_inversion_count(vec!['A', 'C', 'B']),
        calculate_inversion_count(vec!['B', 'A', 'C']),
        calculate_inversion_count(vec!['B', 'C', 'A']),
        calculate_inversion_count(vec!['C', 'A', 'B']),
        calculate_inversion_count(vec!['C', 'B', 'A'])
    ];

    // Pair each permutation with its corresponding sign
    let mut result = Vec::with_capacity(perms.len());
    for (p, s) in zip(perms, signs) {
        result.push((vec![p[0], p[1], p[2]], s));
    }

    result
}

