fn proper_divisors(n: u32) -> Vec<u32> {
    if n == 1 {
        return vec![];
    }
    let mut divisors = vec![];
    for i in 1..=((n as f64).sqrt() as u32) {
        if n % i == 0 {
            if i != n { 
                divisors.push(i);
            }
            let other = n / i;
            if other != n && other != i {
                divisors.push(other);
            }
        }
    }
