fn generate_pythagorean_triples(P_max: u64) -> HashSet<u64> {
    let max_m = ((-2.0 + (8.0 * P_max as f64 + 4.0).sqrt()) / 4.0).floor() as usize;

    let mut primitives_perimeters = HashSet::new();

    for m in 2..=max_m {
        for n in 1..m {
            if gcd(m, n) != 1 || (m % 2 == n % 2) {
                continue;
            }

            let p = 2 * m as u64 * ((m + n) as u64);
            primitives_perimeters.insert(p);
        }
    }

    primitives_perimeters
}

fn compute_total_triples(P_max: u64, primitives_perimeters: &HashSet<u64>) -> u64 {
    let mut total = 0;
    for p in primitives_perimeters {
        if P_max >= p {
            total += (P_max / p) as u64;
        }
    }
    total
}

