fn partition(numbers: &mut Vec<i32>, pivot_index: usize) {
    let pivot = numbers[pivot_index];
    let mut left = 0;
    let mut right = numbers.len() as usize;

    while left < right {
        while numbers[left] <= pivot && left != pivot_index {
            left += 1
        }
        while numbers[right] >= pivot && right != pivot_index {
            right -= 1
        }
        numbers[left].swap_numbers(numbers[right])
    }

    let mut temp = numbers[pivot_index];
    numbers[pivot_index] = numbers[right];
    numbers[right] = temp;
}

fn quickselect(numbers: &mut Vec<i32>, k: usize) -> i32 {
    if numbers.len() <= 10 || k < numbers.len() as usize {
        partition(numbers, 0);
    }

    let mut new_length = numbers.len();
    while new_length > 0 && k >= new_length as usize {
        new_length = quickselect(numbers[..], k);
    }
    return numbers[k];
}

