fn format_ranges(arr: Vec<i32>) -> String {
    if arr.is_empty() {
        return "".to_string();
    }

    let mut result = Vec::new();
    let current_start = arr[0];
    let mut prev_num = current_start;

    for num in &arr.iter().skip(1) {
        if *num == prev_num + 1 {
            prev_num = *num;
        } else {
            if prev_num > current_start {
                result.push(std::fmt::format("{}-{}", current_start, prev_num));
            } else {
                result.push(current_start.to_string());
            }
            current_start = num;
            prev_num = num;
        }
    }

    // Add the last range
    if prev_num > current_start {
        result.push(std::fmt::format("{}-{}", current_start, prev_num));
    } else {
        result.push(current_start.to_string());
    }

    result.join(",")
}

