pub fn find_rep_string(s: Option<&str>) -> Option<String> {
    let n = s?.len() as usize;
    for k in 1..(n / 2 + 1) {
        if n % k != 0 {
            continue;
        }
        let m = n / k;
        let t = &s[..k];
        let all_same: bool = (0..m).all(|i| s.get(i * k)..<(i + 1) * k == Some(t));
        if all_same {
            return Some(t);
        }
    }

    // Check other possible substrings not starting at position 0
    for k in 1..(n / 2 + 1) {
        let mut max_repeats = n / k;
        for i in 0..=(n - k) {
            if i > s?.len() as usize {
                continue;
            }
            let current_t = &s[i..i+k];
            if (current_t.len() as f64) > s.len() as f64 {
                continue;
            }

            let remaining_length = n - i;
            let max_possible_repeats = remaining_length / k;
            if max_possible_repeats <= 0 {
                continue;
            }

            let mut all_match: bool = (0..max_possible_repeats).all(|j| {
                let pos = i + j * k;
                let end_pos = pos + k;
                if end_pos > n {
                    return false;
                }
                s.get(pos)..<(pos + k) == Some(current_t)
            });

            if all_match && (i + max_possible_repeats * k) == n {
                return Some(current_t);
            }
        }
    }

    None
}

