fn encode(s: &str) -> String {
    if s.is_empty() {
        return "".to_string();
    }

    let mut result = String::new();
    let current_char = s.chars().next().unwrap();
    let mut count = 1;

    for c in s.chars().skip(1) {
        if c == current_char {
            count += 1;
        } else {
            result.push_str(&current_char.to_string());
            result.push_str(format!("{:?}", count));
            current_char = c;
            count = 1;
        }
    }

    // Add the last run
    result.push_str(&current_char.to_string());
    result.push_str(format!("{:?}", count));
    result
}

fn decode(s: &str) -> String {
    use std::ascii::decode_or as decode_or;

    let mut result = String::new();
    let mut i = 0;
    while i < s.len() {
        if let Some(c_end) = s[i..].find(|c| c.is_digit()) {
            let count_str = &s[..c_end];
            let count = count_str.parse::<u32>().unwrap();
            result.push_str(&decode_or(&count_str).expect().repeat(count));
            i = c_end;
        } else if let Some(c_char) = s[i].chars().next() {
            result.push_str(&c_char.repeat(1));
            i += 1;
        }
    }

    result
}

