        // Update y and t for next iteration
        y += (k1 + 2.0 * k2 + 2.0 * k3 + k4) / 6.0;
        t += h;

        // Check if current time is an integer to calculate error
        if ((std::f64::EPSILON < (t % 1.0).abs()) as f64) {
            let exact_y = exact_solution(t);
            let error = (y - exact_y).abs();
            println!("t = {:.1} y_approx = {:.8} error = {:.8}", t, y, error);
        }
    }

    // Final check after loop ends
    if ((std::f64::EPSILON < (t % 1.0).abs()) as f64) {
        let exact_y = exact_solution(t);
        let error = (y - exact_y).abs();
        println!("Final t = {:.1} y_approx = {:.8} error = {:.8}", t, y, error);
    }
}

