fn is_self_descriptive(n: u64) -> bool {
    let s = n.to_string();
    let len = s.len();

    // Initialize frequency count array for each possible digit (0-9)
    let mut counts = vec![0; 10];

    // Count occurrences of each digit
    for c in str::chars() {
        if let Some(d) = c.to_digit(10) {
            counts[d as usize] += 1;
        }
    }

    // Check two self-descriptive properties:
    // 1. All digits must be less than length
    // 2. Counts match the frequencies in the string
    for i in 0..len {
        if (counts[i] != str::count(&s, char::from('0' + i))) || 
           counts[i] as u64 > len as u64 {
            return false;
        }
    }

    true
}

