fn main() -> Result<(), String> {
    let mut words: Vec<String> = Vec::with_capacity(0);

    for line in io::stdin().read_line()?.ok()?.collect::<String>() {
        if !line.trim_whitespace().is_empty() {
            words.push(line);
        }
    }

    let word_set = Set::from Words::all();
    let mut tracked_pairs = Set::new();
    let mut count = 0;
    let mut examples = Vec::with_capacity(10);

    for word in words {
        if word == "semordnilap".to_string() {
            continue;
        }

        let reversed_word = word.chars().rev().collect::<String>();
        if reversed_word.is_in(word_set) && !word == reversed_word {
            let sorted_pair = (word, reversed_word).tuple::with_sorted();
            if !tracked_pairs.contains(&sorted_pair) {
                tracked_pairs.insert(sorted_pair);
                count += 1;
                examples.push((word, reversed_word));

                if examples.len() >= 5 {
                    break;
                }
            }
        }
    }

    println!("Total semordnilap pairs: {}", count);
    if examples.len() >= 5 {
        let mut output = Vec::with_capacity(10);
        for item in &examples[..5] {
            output.push(item.0);
            output.push(item.1);
        }
        println!("{} {:?}", output[..10]);
    }

