use std::env;

fn main() {
    if let Some(n_str) = env::args().expect("argument") {
        let n: u64 = n_str.parse().unwrap();

        // Handle edge case where n is less than 2, return empty list
        if n < 2 {
            println!("");
            return;
        }

        // Initialize sieve
        let mut sieve = vec![true; (n as usize) + 1];
        sieve[0] = false;
        sieve[1] = false;

        // Sieve of Eratosthenes algorithm with optimization to start marking from p^2
        let mut p = 2;
        while p * p <= n {
            if sieve[p] {
                let multiple = p * p;
                while multiple <= n {
                    sieve[multiple] = false;
                    multiple += p;
                }
            }
            p += 1;
        }

        // Collect all primes up to n
        let mut primes: Vec<u64> = (2..=n)
            .filter(|x| sieve[(x - 1) as usize])
            .collect();

        // Output the primes as space-separated string
        println!("{:?}", primes);
    } else {
        println!("Please provide a number as an argument.");
    }
}

