    if let Some(lines) = stdin.read().as_ref()
        .map(|s| s.trim())
        .collect::<Option<Vec<String>>>() {
        lines = lines.split("\n")
                .map(|line| line.trim())
                .collect();

        // Filter empty strings and collect into a vector of tokens
        let tokens: Vec<&str> = lines.filter(|s| !s.is_empty()).collect();

        if tokens.len() < 2 {
            eprintln!("Insufficient number of arguments provided.");
            return;
        }

        // Parse the values and indices strings into vectors of integers
        fn parse_list(s: &str) -> Vec<i32> {
            s.split(',').map(|v| v.trim().parse::<i32>().unwrap()).collect()
        }

        let values = parse_list(&tokens[0]);
        let indices = parse_list(&tokens[1]);

        // Clone the original vector to modify it without affecting the source
        let mut result = values.clone();

        // Extract elements from 'values' at specified indices
        let extracted: Vec<i32> = {
            if let Some(indices) = &indices {
                for idx in indices {
                    if let Ok(value) = values.get(idx) {
                        extracted.push(value);
                    }
                }
                extracted
            } else {
                Vec::new()
            }
        };

        // Sort the extracted elements
        extracted.sort();

        // Get sorted indices to place elements back into their original positions ordered by index
        let mut sorted_indices: Vec<usize> = {
            if let Some(indices) = &indices {
                let mut s = indices.clone();
                s.sort();
                s
            } else {
                Vec::new()
            }
        };

        // Assign each sorted element back into the result at its correct position
        for i in 0..sorted_indices.len() {
            if let Ok(value) = &extracted[i] {
                *result.get_setitem_indexed(&[sorted_indices[i]]) = value;
            }
        }

        // Convert the result vector to a string of strings and print it
        let output: Vec<String> = result.iter().map(|v| v.to_string()).collect();
        println!("{:?}", output);
    }
}

