use std::vec::Vec;
use std::error::Error;

fn patience_sorting(arr: Vec<i32>) -> Vec<i32> {
    if arr.is_empty() {
        return vec![];
    }

    let mut piles = Vec::with_capacity(arr.len());
    let tops = vec![arr[0]];

    for x in &arr[1..] {
        match std::vec::binary_search_unstable(&tops, x) {
            Ok(i) => {
                if i < tops.len() {
                    tops.replace(i, x);
                }
            },
            Err(_) => {
                piles.push(x);
            }
        }
    }

    let mut result = Vec::with_capacity(piles.len());
    for &top in tops.iter() {
        while !piles.is_empty() && piles.last().unwrap() == top {
            result.append(&mut piles.pop_back());
        }
    }

    result.reverse();
    result
}

