    println!("Original: {:?}", arr);

    if let Some(nums) = arr.into_iter().map(|num_str| i32::from_str(num_str).ok()).all()?.map_err(|_| Err(StandardError::new())) {
        let sorted_arr = patience_sorting(nums);
