let animation_frames = vec![
    ":*   |", 
    ":*   /",
    ":*   -",
    ":*   \"
];

// Animation parameters
const loop: bool = true;  // Loop infinitely or not?
const ping_pong: bool = false;  // Reverse direction when complete

// Index tracking variables
var current_index: usize;
var next_index: usize;

// Animation timing
const DELAY: f64 = 0.25; // Delay between frames in seconds

// Animation function with recursion for smooth looping or ping/pong animation.
fn animate(time: f64) -> Option<String> {
    if current_index < animation_frames.len() {
        next_index = (current_index + 1) % animation_frames.len();
    } else if !loop && ping_pong {
        current_index = next_index;
        next_index += 1;
    }

    match current_index {
        0 => yield Option::Some(":*   |"),
        1 => yield Option::Some(":*   /"),
        2 => yield Option::Some(":*   -"),
        3 => yield Option::Some(":*   \"")
    }

    time += DELAY;

    if current_index == animation_frames.len() - 1 {
        if loop {
            current_index = 0
        } else {
            break
        }
    }

    animate(time)
}

