fn main() {
    // Read input line and parse to get n as integer
    let n_str = std::io::stdin().read_line().unwrap();

    if n_str == "" {
        return;
    }

    // Convert string to i32, handling potential errors gracefully
    match n_str.parse::<i32>() {
        Ok(n) => {
            let n: usize = n as usize;

            if n == 0 {
                return;
            }
        },
        Err(e) => {
            println!("Error parsing input: {}", e);
            return;
        }
    }

    // Initialize the matrix filled with zeros
    let mut matrix = vec![vec![0; n]; n];
    var current_num: i32 = 0;

    // Variables to track the current boundaries of the layer being processed
    let (start_row, end_row) = (0, n - 1);
    let (start_col, end_col) = (0, n - 1);

    while start_row <= end_row && start_col <= end_col {
        // Fill top row from left to right
        for col in start_col..=end_col {
            matrix[start_row][col] = current_num as i32;
        }
        current_num += 1;
        start_row += 1;

        if start_row > end_row {
            break;
        }

        // Fill right column from top to bottom
        for row in start_row..=end_row {
            matrix[row][end_col] = current_num as i32;
        }
        current_num += 1;
        end_col -= 1;

        if start_col > end_col {
            break;
        }

        // Fill bottom row from right to left
        for col in (end_col..=start_col).rev() {
            matrix[end_row][col] = current_num as i32;
        }
        current_num += 1;
        end_row -= 1;

        if start_row > end_row {
            break;
        }

        // Fill left column from bottom to top
        for row in (end_row..=start_row).rev() {
            matrix[row][start_col] = current_num as i32;
        }
        current_num += 1;
        start_col += 1;
    }

    // Print the resulting matrix with proper formatting
    for row in matrix.iter() {
        print!("[");
        for elem in row {
            print!("{}", elem, " ");
        }
        print!]');
    }
}

