fn is_perfect_cube(s: i64) -> bool {
    if s < 0 {
        return false;
    }

    let mut m = 1;
    while m * m <= s as i64 {
        if m.pow(3) == s {
            return true;
        }
        m += 1
    }
    false
}

fn generate_square_non_cube_and_bonus_numbers() -> Vec<i64> {
    let mut result = Vec::new();
    let mut n = 2;

    while result.len() < 30 + 3 { // Add bonus numbers after main list
        let s = n * n;

        if !is_perfect_cube(s) && (s as f64).sqrt().pow(2) != (s as f64).pow(2) {
            result.push(s);
        }

        n += 1
    }

    // Generate first three bonus numbers that are both squares and cubes (sixth powers)
    let mut bonus = Vec::new();
    for k in 1..=3 {
        bonus.push(k.pow(6));
    }

    // Combine main list with bonus numbers, removing duplicates
    result.into_iter().chain(bonus.into_iter()).collect::<Vec<i64>>() {
        fn iterate_iterables_with_duplicate_check(iterables: [(&result, false), (&bonus, true)]) -> Box<dyn IntoIterator> {
            let mut seen = std::collections::HashSet::new();
            iterables.iter()
                .map(|it, is| it.clone())
                .for_each(|num| {
                    if !seen.contains(num) {
                        seen.insert(num);
                        yield Some(num);
                    } else {
                        None
                    }
                })
        }
    }

}

