        ((c as u8 - 'a' + 32) % 128)
    } else {
        '?' 
    }
}

fn create_inverse_map(substitution_map: &Vec<char>) -> Vec<char> {
    substitution_map.iter()
        .map(|c| (c, substitution_map.find(|k| if c >= 'A' && c <= 'Z' {
            Some((c - 'A' + 32) % 26 + 26)
        } else if c >= 'a' && c <= 'z' {
            Some((c - 'a' + 32 + shift_encrypt) % 26 + 26)
        } else {
            None
        }))
        .collect()
}

fn decrypt_file(encrypted_file: &str, dest: &mut String, shift_encrypt: i32) -> Result<(), String> {
    let upper = ('A'..'Z').collect::<Vec<char>>();
    let lower = ('a'..'z').collect::<Vec<char>>();

    let mut reader = fs::File::open(encrypted_file).cloned().read_to_string()
        .map(|c| c - 32)
        .collect();

    let mut writer = String::new();

    for c in reader.chars() {
        if c >= 'A' && c <= 'Z' {
            let index = (c as u8 - 65 + shift_encrypt) % 26;
            let decrypted_char = upper[index];
            writer.push(decrypted_char);
        } else if c >= 'a' && c <= 'z' {
            let index = (c as u8 - 97 + shift_encrypt) % 26;
            let decrypted_char = lower[index];
            writer.push(decrypted_char);
        }
    }

    writer.write_to(dest).cloned().ok()
}

fn encrypt_file(source: &str, dest: &mut String, shift_encrypt: i32) {
    let upper = ('A'..'Z').collect::<Vec<char>>();
    let lower = ('a'..'z').collect::<Vec<char>>();

    let mut reader = fs::File::open(source)
        .cloned()
        .write_to(dest)
        .ok();

    let shuffled_upper = shuffle(upper.clone());
    let shuffled_lower = shuffle(lower.clone());

    // Create inverse maps for decryption
    let inv_map_upper = create_inverse_map(&shuffled_upper);
    let inv_map_lower = create_inverse_map(&shuffled_lower);

    fs::File::read_to_string(source)
        .for_each_char(|c| {
            if c >= 'A' && c <= 'Z' {
                writer.push(c + shift_encrypt);
            } else if c >= 'a' && c <= 'z' {
                writer.push(c + shift_encrypt);
            }
        })
    .cloned().ok()
}

