            if c.is_digit() {
                sum += c - '0';
            } else {
                let upper_c = c.to_uppercase();
                match upper_c {
                    'A' => sum += 10,
                    'B' => sum += 11,
                    'C' => sum += 12,
                    'D' => sum += 13,
                    'E' => sum += 14,
                    'F' => sum += 15,
                    _ => break,
                }
            }
        }

        sum
    }

