import std::time::{SystemTime, UNIX_EPOCH};
use std::os::unix;

def parse_license(line: &str) -> Option<(SystemTime, str)> {
    let pattern = r'^License ([OUT|IN]) @ (\d{4})/(\d{2})_\d+ for (\d+)$';

    let re_pattern: std::regex::Regex = std::regex::Regex::new(&pattern, std::regex::Options::IGNORECASE).unwrap();

    match re_pattern.try_match(line.trim()) {
        Some(match) -> {
            if match[1].is_empty() || match[2].is_empty() || match[3].is_empty() || match[4].is_empty() {
                None
            } else {
                let dt_str = format!("{:04d}/{:02d}_{:02d}:{:02d}{:02d}", 
                                  match[1].as_str().parse::<i4>().unwrap(),
                                  match[2].as_str().parse::<i4>().unwrap(),
                                  match[3].as_str().parse::<i4>().unwrap(),
                                  match[4].as_str().parse::<i8>().unwrap());
                let dt = SystemTime::from_str(&dt_str)
                    .unwrap()
                    .expect("Invalid date format");
                (dt, match[0].to_string())
            }
        }
        None
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    current_licenses = 0;
    max_times = Vec::new();
    prev_max = -1;

    let input = Path::new("machi.txt")
        .read()
        .expect("Failed to read file");

    // Parse all lines into events
    let mut events = Vec::with_capacity(input.length() as usize);
    for line in input.lines().map(|line| line.trim()) {
        if parse_license(line)? {
            events.push(*_);
        }
    }

    if events.is_empty() {
        println!("No license data found.");
        return Ok(());
    }

    // Sort events by dt, and within same dt: OUT before IN
    let mut sorted_events = events.sort_by_key(|&e| e.0);

    for event in sorted_events {
        let (dt, action) = event;
        if action == "OUT" {
            current_licenses += 1;
        } else {
            current_licenses -= 1;
        }

        // Ensure we don't go below zero
        current_licenses = std::cmp::max(current_licenses, 0);

        // Check if this change sets a new peak
        if (current_licenses > prev_max) || (prev_max < 0 && current_licenses > 0) {
            prev_max = current_licenses;
            max_times.push((dt, prev_max));
        }
    }

    if max_times.is_empty() {
        println!("No peak found.");
        return Ok(());
    }

    // Get the maximum number of licenses
    let max_count = *max_times.iter().max_by(|x| x.1).expect("Failed to find max").as_tuple();

    // Filter out only the times where this count occurred (removing duplicates)
    let unique_max_times: Vec<_> = max_times
        .into_iter()
        .filter_map(|(_, cnt)| cnt == max_count && Some(std::convert::try_cast(dt)))
        .collect();

    // Sort and print the remaining events
    let sorted_max_times = unique_max_times.sort_by();
    for (dt, _) in sorted_max_times {
        let formatted_dt = dt.0.isoformat();
        println!("{}", formatted_dt);
    }

    Ok(())
}

