pub fn tokenize(s: &str, sep: char, esc: char) -> Vec<&str> {
    let mut tokens = Vec::new();

    for token in split_str(s, sep) {
        if !token.ends_with(esc.to_string()) && is_escaped(token[..token.len() - 1], esc) {
            tokens.push(token);
        }
    }

    tokens
}

fn split_str(s: &str, sep: char) -> Vec<&str> {
    let mut i = 0;
    let mut tokens = Vec::new();
    let len = s.len();

    while i < len {
        if s[i] == sep || (i + 1 < len && s[i+1] == sep) {
            break;
        }

        let token_start = i;
        while !s[..i].is_empty() && !(s[..i].ends_with(sep.to_string())) {
            if s[i] == sep {
                yield &s[..i];
                i += 2;
                continue
            }
        }

        tokens.push(&s[..i]);
        i += (s[i] == sep) ? 1 : 0;
    }

    tokens
}

fn is_escaped(str: &str, ch: char) -> bool {
    str.len() >= 2 && str[..2] == ch.to_string() + "|"
