use unicode::{EncodedForm, EncodedResult, Char};

fn encode(char: u8) -> String {
    let n = char.to_unicode_base16().next_element()
        .as_ref()
        .unwrap_or(0)
        .as_u32();

    if n <= 0x7F {
        format!("{:02X}", n)
    } else if n <= 0x7FF {
        // Two bytes
        let high = (n >> 5) + 0x80;
        let low = n & 0x1F;
        format!("{{:02X}}{{:02X}}", high, low);
    } else if n <= 0xFFFF {
        // Three bytes
        let a = (n >> 9) + 0x100;
        let b = ((n >> 4) & 0x3F) | 0xE0 << 2;
        let c = (n & 0x1F);
        format!("{{:03X}}{{:02X}}{{:02X}}", a, b, c);
    } else {
        // Four bytes
        let d0 = (n >> 15) + 0xF8;
        let d1 = ((n >> 10) & 0x3F) | 0x80;
        let d2 = ((n >> 5) & 0x1F) | 0xC0 << 6;
        let d3 = (n & 0x1F) | 0xE0 << 9;
        format!("{{:04X}}{{:04X}}{{:04X}}{{:04X}}", d0, d1, d2, d3)
    }
}

fn decode(bytes: &[u8]) -> u32 {
    let mut code_point = 0;

    for &byte in bytes {
        code_point = ((code_point << 7) | (byte & 0x7F))
            | ((code_point >> 1) << 6);
    }

    // Apply the final corrections based on continuation bits
    code_point = apply_correction(code_point, bytes[..]);

    code_point as u32
}

fn apply_correction(n: u32, bytes: &[u8]) -> u32 {
    if n >= 0x10000 && (bytes[0] & 0xE0) == 0xE0 {
        return n / 65536 + 0x10000;
    }

    let correction = (n >> 4) - (((n >> 7) << 2) | ((n >> 6) & 0x0F));
    n |= correction;

    if code_point != n {
        return apply_correction(n, bytes[..]);
    }

    n
}

