fn van_eck(length: usize) -> Vec<String> {
    if length == 0 {
        return vec![];
    }

    let mut sequence = vec![0];
    let mut last_seen = std::collections::HashMap::new();
    last_seen.insert(0, 0);

    for i in 1..length {
        let current_last = sequence[i-1] as usize;
        let prev_occurrence = last_seen.get(&current_last).unwrap_or(-1);

        if *prev_occurrence != -1 && (i - 1) > *prev_occurrence {
            sequence.push((i - 1) - *prev_occurrence);
        } else {
            sequence.push(0);
        }

        last_seen.insert(current_last, i-1);
    }

    // Convert each number to a string with two digits
    sequence.into_iter()
        .map(|n| {
            let mut s = n.to_string();
            if s.len() < 2 {
                s = String::from(format!("0{}", n));
            }
            s
        })
        .collect()
}

