fn van_der_corput(n: i64) -> f64 {
    if n == 0 {
        return 0.0;
    }

    let binary_str = bin(n)[2]; // Get the binary string without "0b" prefix
    let reversed_binary = binary_str.chars().rev().collect::<String>();
    let mut value = 0.0;

    for (i, bit) in reversed_binary.chars().enumerate() {
        let exponent = -(i as f64 + 1);
        value += bit.to_i64().unwrap() * (2.0 ** exponent);
    }

    return value;
}

fn van_der_corput_sequence_recursive(n_terms: usize) -> Vec<f64> {
    let mut sequence = Vec::with_capacity(n_terms);
    for n in 0..n_terms {
        sequence.push(van_der_corput(n));
    }
    sequence
}

fn van_der_corput_sequence(n_terms: usize) -> Vec<f64> {
    van_der_corput_sequence_recursive(n_terms)
