struct Vector {
    x: f64,
    y: f64,
    z: f64,
}

impl Vector {
    pub fn new(x: f64, y: f64) -> Self {
        Vector { x, y, z: 0.0 }
    }

    pub fn from_start_end(start_x: f64, start_y: f64, end_x: f64, end_y: f64) -> Self {
        Vector {
            x: end_x - start_x,
            y: end_y - start_y,
            z: 0.0
        }
    }

    pub fn from_mag_dir(mag: f64, angle: f64) -> Self {
        Vector {
            x: mag * angle.cos(),
            y: mag * angle.sin(),
            z: 0.0
        }
    }

    pub fn add(self, other: &Vector) -> Vector {
        Vector {
            x: self.x + other.x,
            y: self.y + other.y,
            z: self.z + other.z
        }
    }

    pub fn sub(self, other: &Vector) -> Vector {
        Vector {
            x: self.x - other.x,
            y: self.y - other.y,
            z: self.z - other.z
        }
    }

    pub fn mul_scalar(self, scalar: f64) -> Vector {
        Vector {
            x: self.x * scalar,
            y: self.y * scalar,
            z: self.z * scalar
        }
    }

    pub fn div_scalar(self, scalar: f64) -> Option<Vector> {
        if scalar == 0.0 {
            None
        } else {
            Some(Vector {
                x: self.x / scalar,
                y: self.y / scalar,
                z: self.z / scalar
            })
        }
    }

    pub fn equals(self, other: &Vector) -> bool {
        self.x == other.x && self.y == other.y && self.z == other.z
    }

    pub fn to_string(&self) -> String {
        format!("{:.2}, {:.2}, {:.2}", self.x.round(2), self.y.round(2), self.z.round(2))
    }
}

impl std::fmt::Display for Vector {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        format!("{:.2}, {:.2}, {:.2}", self.x.round(2), self.y.round(2), self.z.round(2))
    }
