/// = [ (4)(-13) - (5)(-12), -(3)(-13) - (5)(-5), (3)(-12) - (4)(-5) ]
/// = [-52 + 60, -(-39) + 25, -36 + 20]
/// = [8, 64, -16]
/// 
/// ## Dot Product A · (B × C)
/// Given A = a, B = b, C = c:
/// = [3, 4, 5] · [8, 64, -16]
/// = 3*8 + 4*64 + 5*(-16)
/// = 24 + 256 - 80
/// = 200
/// 
/// ## Cross Product a × b
/// As calculated above: [8, 64, -16]
/// 
/// ## Vector Triple Product a × (b × c)
/// First compute b × c:
/// = [-5, -12, -13] × [21, -8, -19]
/// = [( -12*(-19) ) - ( -13*-8 ), -( -5*(-19) - (-13)*21 ), ( -5*-8 ) - ( -12*21 )]
/// = [228 - 104, -(-95 + 273), 40 - (-252)]
/// = [124, -178, 292]
/// 
/// Then a × (b × c):
