fn compute_trapped_rain_water(heights: Vec<i32>) -> i32 {
    let n = heights.len();
    if n < 2 {
        return 0;
    }

    // Compute left_max array where each element is the max height from start up to current index
    let mut left_max = Vec::with_capacity(n);
    left_max.push(heights[0]);
    let mut current_left = heights[0];
    for i in 1..n {
        if heights[i] > current_left {
            current_left = heights[i];
        }
        left_max.push(current_left);
    }

    // Compute right_max array where each element is the max height from current index to end
    let mut right_max = Vec::with_capacity(n);
    right_max.push(0);
    let mut max_so_far = 0;
    for i in (0..n).rev() {
        if heights[i] > max_so_far {
            max_so_far = heights[i];
        }
        right_max.push(max_so_far);
    }
    // Reverse to get the correct order
    right_max.reverse();

    let mut total_water = 0;
    for i in 0..n {
        let water = std::cmp::min(&left_max[i], &right_max[i]) - heights[i];
        if water > 0 {
            total_water += water;
        }
    }

    total_water
}

