    let n = 3.0;
    let mut acc = accumulator_factory(n);
    acc = accumulator_factory(1.0);

    let x = accumulator_factory(1.0);
    x(5.0);
    let y = accumulator_factory(3.0);
    println!("{}", x(2.3));
}
