use std::collections::VecDeque;

fn brace_expand(input: &str) -> Vec<String> {
    let mut result: Vec<String> = Vec::new();
    expand_recursive(input, &mut VecDeque::new(), &mut result);
    result
}

fn expand_recursive(input: &str, current: &mut VecDeque<String>, result: &mut Vec<String>) {
    if input.is_empty() {
        let mut expanded = String::new();
        for s in current.iter().cloned() {
            expanded.push_str(&s);
        }
        result.push(expanded);
        return;
    }

    let mut i = 0;
    while i < input.len() {
        match input.chars().nth(i).unwrap() {
            '{' => {
                let mut j = i + 1;
                let mut balance = 1;
                while j < input.len() {
                    match input.chars().nth(j).unwrap() {
                        '{' => balance += 1,
                        '}' => balance -= 1,
                        _ => {}
                    }
                    if balance == 0 {
                        break;
                    }
                    j += 1;
                }

                if j < input.len() {
                    let brace_content = &input[i + 1..j];
                    let comma_indices: Vec<usize> = brace_content
                        .match_indices(',')
                        .map(|(index, _)| index + i + 1)
                        .collect();

                    if comma_indices.is_empty() {
                        let mut new_current = current.clone();
                        new_current.push_back(brace_content.to_string());
                        expand_recursive(&input[j + 1..], &mut new_current, result);
                    } else {
                        let mut alternatives: Vec<String> = Vec::new();
                        let mut start = 0;
                        for &index in &comma_indices {
                            let alternative = brace_content[start..index].to_string();
                            alternatives.push(alternative);
                            start = index + 1;
                        }
                        alternatives.push(brace_content[start..].to_string());

                        for alternative in alternatives {
                            let mut new_current = current.clone();
                            new_current.push_back(alternative);
                            expand_recursive(&input[j + 1..], &mut new_current, result);
                        }
                    }
                    i = j + 1;
                } else {
                   result.push(input.to_string());
                   return;
                }
            }
            '\\' => {
                i += 1;
            }
            _ => {
                let mut j = i;
                while j < input.len() {
                    match input.chars().nth(j).unwrap() {
                        '{' | '}' | ',' => {
                            break;
                        }
                        _ => {
                            j += 1;
                        }
                    }
                }
                let literal = &input[i..j];
                let mut new_current = current.clone();
                new_current.push_back(literal.to_string());
                expand_recursive(&input[j..], &mut new_current, result);
                i = j;
            }
        }
        i += 1;
    }
}
fn main() {
    let input = std::env::args().nth(1).unwrap();
    let result = brace_expand(&input);
    for s in result {
        println!("{}", s);
    }
}

