fn decompose_time(seconds: u32) -> String {
    let mut seconds = seconds;
    let mut weeks = seconds / (7 * 24 * 60 * 60);
    seconds %= (7 * 24 * 60 * 60);
    let mut days = seconds / (24 * 60 * 60);
    seconds %= (24 * 60 * 60);
    let mut hours = seconds / (60 * 60);
    seconds %= (60 * 60);
    let mut minutes = seconds / 60;
    seconds %= 60;

    let mut result = Vec::new();

    if weeks > 0 {
        result.push(format!("{} wk", weeks));
    }
    if days > 0 {
        result.push(format!("{} d", days));
    }
    if hours > 0 {
        result.push(format!("{} hr", hours));
    }
    if minutes > 0 {
        result.push(format!("{} min", minutes));
    }
    if seconds > 0 {
        result.push(format!("{} sec", seconds));
    }

    result.join(", ")
}

