fn egyptian_division(dividend: i32, divisor: i32) -> (i32, i32) {
    let mut powers_of_2: Vec<i32> = Vec::new();
    let mut doublings: Vec<i32> = Vec::new();

    let mut power = 1;
    while power * divisor <= dividend {
        powers_of_2.push(power);
        doublings.push(divisor * power);
        power *= 2;
    }

    let mut answer: i32 = 0;
    let mut accumulator: i32 = 0;

    for i in (0..powers_of_2.len()).rev() {
        if accumulator + doublings[i] <= dividend {
            accumulator += doublings[i];
            answer += powers_of_2[i];
        }
    }

    (answer, dividend - accumulator)
}

