fn mod_inverse(a: i64, m: i64) -> i64 {
    let mut m0 = m;
    let mut y = 0;
    let mut x = 1;

    if m == 1 {
        return 0;
    }

    let mut a_mut = a;
    while a_mut > 1 {
        // q is quotient
        let q = a_mut / m0;
        let mut t = m0;

        // m is remainder now, process same as
        // Euclid's algo
        m0 = a_mut % m0;
        a_mut = t;
        t = y;

        // Update y and x
        y = x - q * y;
        x = t;
