use std::collections::VecDeque;

fn encode(input: &str, symbol_table: &mut Vec<char>) -> Vec<usize> {
    let mut output = Vec::new();
    for c in input.chars() {
        let index = symbol_table.iter().position(|&x| x == c).unwrap();
        output.push(index);

        // Move to front
        let val = symbol_table.remove(index);
        symbol_table.insert(0, val);
    }
    output
}

fn decode(input: &[usize], symbol_table: &mut Vec<char>) -> String {
    let mut output = String::new();
    for &index in input {
        let symbol = symbol_table[index];
        output.push(symbol);

        // Move to front
        let val = symbol_table.remove(index);
        symbol_table.insert(0, val);
    }
    output
}

fn main() {
    let mut symbol_table: Vec<char> = "abcdefghijklmnopqrstuvwxyz".chars().collect();

    let strings = [
        "broood",
        "bananaaa",
        "hiphophiphop",
    ];

    for &input_string in &strings {
        let mut current_symbol_table = symbol_table.clone();
        let encoded = encode(input_string, &mut current_symbol_table);
        println!("{:?}", encoded);

        let mut current_symbol_table2 = symbol_table.clone();
        let decoded = decode(&encoded, &mut current_symbol_table2);

        if input_string != decoded {
            println!("Error: Decoded string does not match original!");
        }
    }
}

