fn format_range(arr: &[i32]) -> String {
    if arr.is_empty() {
        return String::new();
    }

    let mut result = String::new();
    let mut start = arr[0];
    let mut end = arr[0];

    for &num in arr.iter().skip(1) {
        if num == end + 1 {
            end = num;
        } else {
            if start == end {
                result.push_str(&format!("{}-{}", start, end));
            } else {
                result.push_str(&format!("{}-{}-", start, end));
            }
            start = num;
            end = num;
        }
    }

    if start == end {
        result.push_str(&format!("{}-{}", start, end));
    } else {
        result.push_str(&format!("{}-{}-", start, end));
    }

    result.trim_end_matches('-').to_string()
}

