        let y_next = y + (k1 + 2.0 * k2 + 2.0 * k3 + k4) / 6.0;
        let t_next = t + dt;

        let exact_y = (1.0 / 16.0) * (t_next * t_next + 4.0).powi(2);
        let error = (y_next - exact_y).abs();

        println!("{} {:.8} {:.8}", t_next, y_next, error);

        t = t_next;
        y = y_next;
    }
}

fn f(t: f64, y: f64) -> f64 {
    t * y.sqrt()
}

