fn substitution_cipher(input_file: &str, output_file: &str, key: &str) -> Result<(), Box<dyn std::error::Error>> {
    let key_chars: Vec<char> = key.chars().collect();
    let alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
    let alphabet_chars: Vec<char> = alphabet.chars().collect();

    let mut input = File::open(input_file)?;
    let mut input_content = String::new();
    input.read_to_string(&mut input_content)?;

    let mut output = File::create(output_file)?;

    for c in input_content.chars() {
        if alphabet_chars.contains(&c) {
            let index = alphabet_chars.iter().position(|&x| x == c).unwrap();
            let replacement_char = key_chars[index % key_chars.len()];
            write!(output, "{}", replacement_char)?;
        } else {
            write!(output, "{}", c)?;
        }
    }

    Ok(())
