use std::fs::File;
use std::io::{Read, Write};

fn substitution_cipher(input_file: &str, output_file: &str, key: &str) -> Result<(), Box<dyn std::error::Error>> {
    let key_chars: Vec<char> = key.chars().collect();
    let alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
    let alphabet_chars: Vec<char> = alphabet.chars().collect();

    let mut input = File::open(input_file)?;
    let mut input_content = String::new();
    input.read_to_string(&mut input_content)?;

    let mut output = File::create(output_file)?;

    for c in input_content.chars() {
        if alphabet_chars.contains(&c) {
            let index = alphabet_chars.iter().position(|&x| x == c).unwrap();
            let replacement_char = key_chars[index % key_chars.len()];
            write!(output, "{}", replacement_char)?;
        } else {
            write!(output, "{}", c)?;
        }
    }

    Ok(())
}

fn decryption_cipher(input_file: &str, output_file: &str, key: &str) -> Result<(), Box<dyn std::error::Error>> {
    let key_chars: Vec<char> = key.chars().collect();
    let alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
    let alphabet_chars: Vec<char> = alphabet.chars().collect();

    let mut input = File::open(input_file)?;
    let mut input_content = String::new();
    input.read_to_string(&mut input_content)?;

    let mut output = File::create(output_file)?;

    for c in input_content.chars() {
        if key_chars.contains(&c) {
            let index = key_chars.iter().position(|&x| x == c).unwrap();
            let original_char = alphabet_chars[index];
            write!(output, "{}", original_char)?;
        } else {
            write!(output, "{}", c)?;
        }
    }

    Ok(())
}



fn main() -> Result<(), Box<dyn std::error::Error>> {
    let input_file = "input.txt";
    let encrypted_file = "encrypted.txt";
    let decrypted_file = "decrypted.txt";
    let key = "QWERTYUIOPASDFGHJKLZXCVBNM"; //Example Key, can be any combination of uppercase and lowercase letters

    // Encryption
    match substitution_cipher(input_file, encrypted_file, key) {
        Ok(_) => println!("Encryption successful."),
        Err(e) => eprintln!("Encryption error: {}", e),
    }

    // Decryption
    match decryption_cipher(encrypted_file, decrypted_file, key) {
        Ok(_) => println!("Decryption successful."),
        Err(e) => eprintln!("Decryption error: {}", e),
    }

    Ok(())
}

