use std::collections::{HashMap, HashSet};

fn topological_sort(dependencies: &HashMap<String, Vec<String>>) -> Result<Vec<String>, String> {
    let mut graph: HashMap<String, Vec<String>> = HashMap::new();
    let mut in_degree: HashMap<String, usize> = HashMap::new();

    // Initialize graph and in-degree
    for (library, deps) in dependencies {
        graph.insert(library.clone(), deps.clone());
        in_degree.entry(library.clone()).or_insert(0);
        for dep in deps {
            in_degree.entry(dep.clone()).or_insert(0);
        }
    }

    // Calculate in-degrees
    for (library, deps) in dependencies {
        for dep in deps {
            *in_degree.entry(dep.clone()).or_insert(0) += 1;
        }
    }

    // Find starting nodes (in-degree 0)
    let mut queue: Vec<String> = in_degree
        .iter()
        .filter(|(_, &degree)| degree == 0)
        .map(|(library, _)| library.clone())
        .collect();

    let mut sorted: Vec<String> = Vec::new();
    let mut count = 0;

    while let Some(node) = queue.pop() {
        sorted.push(node.clone());
        count += 1;

        if let Some(deps) = graph.get(&node) {
            for dep in deps {
                *in_degree.get_mut(dep).unwrap() -= 1;
                if *in_degree.get(dep).unwrap() == 0 {
                    queue.push(dep.clone());
                }
            }
        }
    }

    if count != in_degree.len() {
        return Err("Cycle detected! Unorderable dependencies.".to_string());
    }

    Ok(sorted)
}

