fn cartesian_product_n<T: Copy>(lists: &[&[T]]) -> Vec<Vec<T>> {
    if lists.is_empty() {
        return Vec::new();
    }

    let mut result: Vec<Vec<T>> = Vec::new();

    if lists.len() == 1 {
        for &item in lists[0] {
            result.push(vec![item]);
        }
        return result;
