    let remaining_lists = &lists[1..];

    let sub_product = cartesian_product_n(remaining_lists);

    for &item in first_list {
        for sub_vec in &sub_product {
            let mut new_vec = vec![item];
            new_vec.extend_from_slice(sub_vec);
            result.push(new_vec);
        }
    }
    result
