struct Matrix {
    a1: i64,
    a: i64,
    b1: i64,
    b: i64,
}

impl Matrix {
    fn new(a1: i64, a: i64, b1: i64, b: i64) -> Self {
        Matrix { a1, a, b1, b }
    }

    fn transpose_input(&mut self, t: i64) {
        let temp_a1 = self.a1;
        let temp_a = self.a;
        let temp_b1 = self.b1;
        let temp_b = self.b;

        self.a1 = temp_a + temp_a1 * t;
        self.a = temp_a1;
        self.b1 = temp_b + temp_b1 * t;
        self.b = temp_b1;
    }

    fn transpose_output(&mut self, t: i64) {
        let temp_a1 = self.a1;
        let temp_a = self.a;
        let temp_b1 = self.b1;
        let temp_b = self.b;

        self.a1 = temp_b1;
        self.a = temp_b;
        self.b1 = temp_a1 - temp_b1 * t;
        self.b = temp_a - temp_b * t;
    }

    fn inject_infinity(&mut self) {
        self.a1 = self.a1;
        self.a = self.a1;
        self.b1 = self.b1;
        self.b = self.b1;
    }

    fn is_done(&self) -> bool {
