    for i in 0..rows {
        for j in 0..cols {
            let mut live_neighbors = 0;

            for x in -1..=1 {
                for y in -1..=1 {
                    if x == 0 && y == 0 {
                        continue;
                    }

                    let neighbor_row = i as i32 + x;
                    let neighbor_col = j as i32 + y;

                    if neighbor_row >= 0 && neighbor_row < rows as i32 && neighbor_col >= 0 && neighbor_col < cols as i32 {
