#[derive(Debug, PartialEq, Eq, Clone)]
struct Card {
    face: char,
    suit: char,
}

fn parse_hand(cards: &Vec<String>) -> Option<Vec<Card>> {
    let mut parsed_cards: Vec<Card> = Vec::new();
    let mut seen_cards: HashMap<(char, char), bool> = HashMap::new();

    for card_str in cards {
        if card_str.len() != 2 {
            return None;
        }

        let face = card_str.chars().next().unwrap();
        let suit = card_str.chars().last().unwrap();

        if !is_valid_face(face) && face != 'j' && face != 'J' {
            return None;
        }
        if !is_valid_suit(suit) {
            return None;
        }

        if seen_cards.contains_key(&(face, suit)) {
            return None;
        }

        seen_cards.insert((face, suit), true);
        parsed_cards.push(Card { face, suit });
    }

    Some(parsed_cards)
}

fn is_valid_face(face: char) -> bool {
    match face {
        '2'..='9' | 'a' | 'j' | 'q' | 'k' | 'A' | 't' | '1' => true,
        _ => false,
    }
}

fn is_valid_suit(suit: char) -> bool {
    match suit {
        'h' | 'd' | 'c' | 's' => true,
        _ => false,
    }
}

fn rank_hand(hand: &Vec<Card>) -> String {
    let mut face_counts: HashMap<char, usize> = HashMap::new();
    let mut suits: Vec<char> = Vec::new();

    for card in hand {
        *face_counts.entry(card.face).or_insert(0) += 1;
        suits.push(card.suit);
    }

    let mut counts: Vec<usize> = face_counts.values().cloned().collect();
    counts.sort_by(|a, b| b.cmp(a));

    let max_count = counts[0];

    let is_flush = suits.iter().all(|&s| s == suits[0]);

    let mut face_values: Vec<i32> = hand
        .iter()
        .map(|card| card_value(card.face))
        .collect();
    face_values.sort();
    let is_straight = is_straight(&face_values);

    if is_straight && is_flush {
        return "straight-flush".to_string();
    }

    if max_count == 4 {
        return "four-of-a-kind".to_string();
    }

    if max_count == 3 && counts[1] == 2 {
        return "full-house".to_string();
    }

    if is_flush {
        return "flush".to_string();
    }

    if is_straight {
        return "straight".to_string();
    }

    if max_count == 3 {
        return "three-of-a-kind".to_string();
    }

    if counts[0] == 2 && counts[1] == 2 {
        return "two-pair".to_string();
    }

    if counts[0] == 2 {
        return "one-pair".to_string();
    }

    "high-card".to_string()
}

