        println!("{}", row);
    }
}

fn is_filled(row: usize, col: usize, n: usize) -> bool {
    let x = col as f64;
    let y = row as f64;

    let mut level = 0;
    while (1 << level) < n {
        level += 1;
    }

    let size = 1.0 / (2.0f64.powi(level as i32));

    let mut temp_x = x / (2.0f64.powi(level as i32));
    let mut temp_y = y / (2.0f64.powi(level as i32));

    if temp_x >= 0.5 {
        temp_x -= 0.5;
    }
    if temp_y >= 0.5 {
        temp_y -= 0.5;
    }

    if temp_x < size && temp_y < size {
        return true;
    } else if temp_x >= size && temp_y < size {
        return false;
    } else if temp_x < size && temp_y >= size {
        return false;
    } else {
        return false;
    }
}

