fn patience_sort(arr: &mut Vec<i32>) {
    let mut piles: Vec<Vec<i32>> = Vec::new();

    for &num in arr.iter() {
        let mut pile_found = false;
        for pile in &mut piles {
            if pile.last().unwrap_or(&i32::MAX) >= &num {
                pile.push(num);
                pile_found = true;
                break;
            }
        }
        if !pile_found {
            piles.push(vec![num]);
        }
    }

    let mut sorted_arr: Vec<i32> = Vec::new();
    while !piles.is_empty() {
        let mut min_pile_index = 0;
        for i in 1..piles.len() {
