                min_pile_index = i;
            }
        }

        sorted_arr.push(piles[min_pile_index].pop().unwrap());
        if piles[min_pile_index].is_empty() {
            piles.remove(min_pile_index);
        }
    }

    sorted_arr.reverse();
    *arr = sorted_arr;
}
