use std::f64::consts::PI;

fn main() {
    // Build trig table
    let mut x_values: Vec<f64> = Vec::new();
    for i in 0..32 {
        x_values.push(0.05 * i as f64);
    }

    let sin_values: Vec<f64> = x_values.iter().map(|&x| x.sin()).collect();
    let cos_values: Vec<f64> = x_values.iter().map(|&x| x.cos()).collect();
    let tan_values: Vec<f64> = x_values.iter().map(|&x| x.tan()).collect();

    // Thiele's Interpolation
    fn thiele_interpolation(
        x: f64,
        data_x: &[f64],
        data_y: &[f64],
    ) -> f64 {
        let n = data_x.len();
        let mut b = vec![0.0; n];
        b[0] = data_y[0];

        for i in 1..n {
            let mut b_i = data_y[i];
            for j in (0..i).rev() {
                b_i *= (x - data_x[j]) / (data_x[j+1] - data_x[j]);
            }
            b[i] = b_i;
        }

        let mut result = 0.0;
        for i in 0..n {
            result += b[i];
        }

        result
    }

    // Demonstrate identities
    let sin_inv_half = thiele_interpolation(0.5, &x_values, &sin_values);
    let cos_inv_half = thiele_interpolation(0.5, &x_values, &cos_values);
    let tan_inv_one = thiele_interpolation(1.0, &x_values, &tan_values);

    let identity1 = 6.0 * sin_inv_half;
    let identity2 = 3.0 * cos_inv_half;
    let identity3 = 4.0 * tan_inv_one;

    println!("{:.5}", identity1 - PI);
    println!("{:.5}", identity2 - PI);
    println!("{:.5}", identity3 - PI);
}

