fn find_key(ciphertext: &str) -> String {
    let mut key = String::new();
    let ciphertext_chars: Vec<char> = ciphertext.chars().filter(|c| c.is_alphabetic()).collect();

    let key_length = 3;
    for i in 0..key_length {
        let mut chi_squared_values: Vec<(f64, char)> = Vec::new();
        for k in 'A'..='Z' {
            let mut chi_squared = 0.0;
            for j in (i..ciphertext_chars.len()).step_by(key_length) {
                let ciphertext_char = ciphertext_chars[j];
                let key_char = k;
                let decrypted_char = ((ciphertext_char as u32 - 'A' as u32 - (key_char as u32 - 'A' as u32)) % 26 + 'A' as u32) as u8 as char;
                let frequency = letter_frequency(decrypted_char);

                chi_squared += (frequency - expected_frequency(decrypted_char)).powi(2) / expected_frequency(decrypted_char);
            }
            chi_squared_values.push((chi_squared, k));
        }

        chi_squared_values.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap());
        key.push(chi_squared_values[0].1);
    }

    key
}

