use std::env;

const BLOCKS: &[(char, char)] = &[
    ('B', 'O'), ('X', 'K'), ('D', 'Q'), ('C', 'P'), ('N', 'A'),
    ('G', 'T'), ('R', 'E'), ('T', 'G'), ('Q', 'D'), ('F', 'S'),
    ('J', 'W'), ('H', 'U'), ('V', 'I'), ('A', 'N'), ('O', 'B'),
    ('E', 'R'), ('F', 'S'), ('L', 'Y'), ('P', 'C'), ('Z', 'M'),
];

fn can_spell(word: &str) -> bool {
    let letters: Vec<char> = word.chars().map(|c| c.to_ascii_uppercase()).collect();
    let mut used = vec![false; BLOCKS.len()];
    backtrack(0, &letters, &mut used)
}

fn backtrack(idx: usize, letters: &[char], used: &mut [bool]) -> bool {
    if idx == letters.len() {
        return true;
    }
    let target = letters[idx];
    for (i, &(a, b)) in BLOCKS.iter().enumerate() {
        if !used[i] && (a == target || b == target) {
            used[i] = true;
            if backtrack(idx + 1, letters, used) {
                return true;
            }
            used[i] = false;
        }
    }
    false
}

fn main() {
    let mut args = env::args().skip(1);
    if let Some(word) = args.next() {
        let result = can_spell(&word);
        println!("{}", if result { "True" } else { "False" });
    }
}

