use num_bigint::BigUint;
use num_traits::{One, Zero};
use std::env;
use std::str::FromStr;

fn ack(m: u32, n: &BigUint) -> BigUint {
    if m == 0 {
        n.clone() + BigUint::one()
    } else if n.is_zero() {
        ack(m - 1, &BigUint::one())
    } else {
