/// Extended Euclidean algorithm.
/// Returns (g, x, y) such that a*x + b*y = g = gcd(a,b)
fn egcd(a: i128, b: i128) -> (i128, i128, i128) {
    if b == 0 {
        (a.abs(), a.signum(), 0)
    } else {
        let (g, x1, y1) = egcd(b, a % b);
        (g, y1, x1 - (a / b) * y1)
    }
}

/// Compute modular inverse of `a` modulo `m`.
/// Returns Some(inv) with 0 <= inv < m if inverse exists, otherwise None.
fn mod_inv(a: i128, m: i128) -> Option<i128> {
    let (g, x, _) = egcd(a, m);
    if g != 1 {
        None
    } else {
        let mut inv = x % m;
        if inv < 0 {
            inv += m;
        }
        Some(inv)
    }
}

