use std::env;

/// Extended Euclidean algorithm.
/// Returns (g, x, y) such that a*x + b*y = g = gcd(a,b)
fn egcd(a: i128, b: i128) -> (i128, i128, i128) {
    if b == 0 {
        (a.abs(), a.signum(), 0)
    } else {
        let (g, x1, y1) = egcd(b, a % b);
        (g, y1, x1 - (a / b) * y1)
    }
}

/// Compute modular inverse of `a` modulo `m`.
/// Returns Some(inv) with 0 <= inv < m if inverse exists, otherwise None.
fn mod_inv(a: i128, m: i128) -> Option<i128> {
    let (g, x, _) = egcd(a, m);
    if g != 1 {
        None
    } else {
        let mut inv = x % m;
        if inv < 0 {
            inv += m;
        }
        Some(inv)
    }
}

/// Parse a comma‑separated list of integers.
fn parse_list(s: &str) -> Result<Vec<i128>, String> {
    if s.trim().is_empty() {
        return Ok(vec![]);
    }
    s.split(',')
        .map(|part| {
            part.trim()
                .parse::<i128>()
                .map_err(|e| format!("Invalid integer '{}': {}", part, e))
        })
        .collect()
}

/// Check pairwise coprimality of the moduli.
fn pairwise_coprime(mods: &[i128]) -> bool {
    for i in 0..mods.len() {
        for j in (i + 1)..mods.len() {
            if egcd(mods[i], mods[j]).0 != 1 {
                return false;
            }
        }
    }
    true
}

