use num_bigint::BigInt;
use num_integer::Integer;
use num_rational::BigRational;
use num_traits::Zero;
use std::iter;

/// Convert a finite continued fraction `terms` to a `BigRational`.
fn cf_to_rational<I>(terms: I) -> BigRational
where
    I: IntoIterator<Item = BigInt>,
    I::IntoIter: DoubleEndedIterator,
{
    let mut iter = terms.into_iter().rev();

    // Initialise with the last term (or 0/1 if empty)
    let mut result = match iter.next() {
        Some(t) => BigRational::new(t, BigInt::from(1)),
        None => return BigRational::new(BigInt::from(0), BigInt::from(1)),
    };

    // Process the remaining terms from right‑to‑left
    for term in iter {
        result = BigRational::new(term, BigInt::from(1)) + result.recip();
    }

    result
}

/// Convert a `BigRational` to a (possibly infinite) continued fraction.
/// The iterator yields at most `max_terms` terms; if the rational is not
/// exact after that many terms the sequence is truncated.
fn rational_to_cf(r: &BigRational, max_terms: usize) -> Vec<BigInt> {
    let mut terms = Vec::new();
    let mut num = r.numer().clone();
    let mut den = r.denom().clone();

    for _ in 0..max_terms {
        let (q, rem) = num.div_rem(&den);
        terms.push(q);
        if rem == BigInt::zero() {
            break;
        }
        num = den;
        den = rem;
    }

    terms
}

// ---------------------------------------------------------------------
// Generators for specific continued fractions
// ---------------------------------------------------------------------

/// Generator for √2 = [1; 2, 2, 2, …]
fn sqrt2_generator() -> impl Iterator<Item = BigInt> {
    iter::once(BigInt::from(1)).chain(iter::repeat(BigInt::from(2)))
}

/// Approximate a continued fraction generated by `gen` using `depth` terms.
fn approx_cf<I>(gen: I, depth: usize) -> BigRational
where
    I: IntoIterator<Item = BigInt>,
{
    cf_to_rational(gen.into_iter().take(depth))
}

