fn rational_to_cf(r: &BigRational, max_terms: usize) -> Vec<BigInt> {
    let mut terms = Vec::new();
    let mut num = r.numer().clone();
    let mut den = r.denom().clone();

    for _ in 0..max_terms {
        let (q, rem) = num.div_rem(&den);
        terms.push(q);
        if rem == BigInt::zero() {
            break;
        }
        num = den;
        den = rem;
    }

    terms
}

// ---------------------------------------------------------------------
// Generators for specific continued fractions
// ---------------------------------------------------------------------

/// Generator for √2 = [1; 2, 2, 2, …]
fn sqrt2_generator() -> impl Iterator<Item = BigInt> {
    iter::once(BigInt::from(1)).chain(iter::repeat(BigInt::from(2)))
}

/// Approximate a continued fraction generated by `gen` using `depth` terms.
fn approx_cf<I>(gen: I, depth: usize) -> BigRational
where
    I: IntoIterator<Item = BigInt>,
{
    cf_to_rational(gen.into_iter().take(depth))
}

// ---------------------------------------------------------------------
// Demonstrations
// ---------------------------------------------------------------------

fn main() {
    // Helper to print a continued fraction nicely
    let print_cf = |label: &str, cf: &[BigInt]| {
        let mut s = String::new();
        if let Some(first) = cf.first() {
            s.push_str(&format!("[{}", first));
            if cf.len() > 1 {
                s.push(';');
                for (i, t) in cf.iter().skip(1).enumerate() {
                    if i > 0 {
                        s.push(',');
                    }
                    s.push_str(&format!("{}", t));
                }
            }
            s.push(']');
        } else {
            s.push_str("[ ]");
        }
        println!("{} = {}", label, s);
    };

    // 1. [1;5,2] + 1/2
    let cf1 = vec![BigInt::from(1), BigInt::from(5), BigInt::from(2)];
    let r1 = cf_to_rational(cf1.clone());
    let r_half = BigRational::new(BigInt::from(1), BigInt::from(2));
    let sum1 = r1 + r_half;
    let cf_sum1 = rational_to_cf(&sum1, 20);
    print_cf("[1;5,2] + 1/2", &cf_sum1);

    // 2. [3;7] + 1/2
    let cf2 = vec![BigInt::from(3), BigInt::from(7)];
    let r2 = cf_to_rational(cf2.clone());
    let sum2 = r2 + r_half.clone();
    let cf_sum2 = rational_to_cf(&sum2, 20);
    print_cf("[3;7] + 1/2", &cf_sum2);

    // 3. [3;7] / 4
    let div4 = BigRational::new(BigInt::from(1), BigInt::from(4));
    let quot3 = r2 * div4;
    let cf_quot3 = rational_to_cf(&quot3, 20);
    print_cf("[3;7] / 4", &cf_quot3);

    // 4. 1 / √2  (using 30 terms of √2)
    let sqrt2_approx = approx_cf(sqrt2_generator(), 30);
    let inv_sqrt2 = sqrt2_approx.recip();
    let cf_inv_sqrt2 = rational_to_cf(&inv_sqrt2, 30);
    print_cf("1/√2", &cf_inv_sqrt2);

    // 5. (1 + 1/√2) / 2
    let one = BigRational::new(BigInt::from(1), BigInt::from(1));
    let avg = (one + inv_sqrt2) * BigRational::new(BigInt::from(1), BigInt::from(2));
    let cf_avg = rational_to_cf(&avg, 30);
    print_cf("(1 + 1/√2)/2", &cf_avg);
}

