    // Frequency count for each byte value
    let mut freq = [0usize; 256];
    for b in source.bytes() {
        freq[b as usize] += 1;
    }

    let total = source.len() as f64;
    let mut entropy = 0.0_f64;

    for &count in &freq {
        if count > 0 {
            let p = count as f64 / total;
            entropy -= p * p.log2();
        }
    }

    println!("Entropy of source code: {}", entropy);
}

