use std::collections::HashSet;

fn generate_permutations(chars: &mut Vec<char>, l: usize, out: &mut Vec<String>) {
    if l == chars.len() - 1 {
        out.push(chars.iter().collect());
        return;
    }
    for i in l..chars.len() {
        chars.swap(l, i);
        generate_permutations(chars, l + 1, out);
        chars.swap(l, i);
    }
}

fn main() {
    // given permutations
    let given = [
        "ABCD", "CABD", "ACDB", "DACB", "BCDA", "ACBD", "ADCB", "CDAB", "DABC", "BCAD",
        "CADB", "CDBA", "CBAD", "ABDC", "ADBC", "BDCA", "DCBA", "BACD", "BADC", "BDAC",
        "CBDA", "DBCA", "DCAB",
    ];
    let given_set: HashSet<&str> = given.iter().cloned().collect();

    // generate all 24 permutations of A,B,C,D
    let mut chars = vec!['A', 'B', 'C', 'D'];
    let mut all = Vec::new();
    generate_permutations(&mut chars, 0, &mut all);

    // find the missing one
    let missing = all
        .into_iter()
        .find(|p| !given_set.contains(p.as_str()))
        .expect("there should be exactly one missing permutation");

    println!("{}", missing);
}

