/// Generate the first `n` elements of sequences R and S.
/// Returns a tuple `(R_vec, S_vec)` where both vectors are 1‑indexed
/// (i.e. element at index `i` is the i‑th term, `i` starts from 0).
fn generate_up_to(n: usize) -> (Vec<u64>, Vec<u64>) {
    if n == 0 {
        return (Vec::new(), Vec::new());
    }

    let mut r: Vec<u64> = Vec::with_capacity(n);
    let mut s: Vec<u64> = Vec::with_capacity(n);
    let mut present: HashSet<u64> = HashSet::new();

    // R(1) = 1
    r.push(1);
    present.insert(1);

    // Find S(1) = smallest positive integer not in R
    let mut candidate: u64 = 2;
    while present.contains(&candidate) {
        candidate += 1;
    }
    s.push(candidate);
    candidate += 1; // next candidate for later missing numbers

    // Build the rest of the sequences
