        let r_i = r[i - 2] + s[i - 2];
        r.push(r_i);
        present.insert(r_i);

        // S(i) = next missing positive integer
        while present.contains(&candidate) {
            candidate += 1;
        }
        s.push(candidate);
        candidate += 1;
    }

    (r, s)
}

