use std::cmp::Reverse;
use std::collections::{BinaryHeap, HashMap};

#[derive(Eq, PartialEq, Ord, PartialOrd, Debug)]
struct Node {
    weight: usize,
    symbol: Option<char>,
    left: Option<Box<Node>>,
    right: Option<Box<Node>>,
    id: usize,
}

fn main() {
    // The fixed input string
    let text = ":::::   ''' '' this is an example for huffman encoding '' '''";

    // Count frequencies
    let mut freq: HashMap<char, usize> = HashMap::new();
    for ch in text.chars() {
        *freq.entry(ch).or_insert(0) += 1;
    }

    // Build priority queue of leaf nodes
    let mut heap: BinaryHeap<Reverse<(usize, usize, Box<Node>)>> = BinaryHeap::new();
    let mut next_id: usize = 0;
    for (ch, w) in freq.iter() {
        let node = Node {
            weight: *w,
            symbol: Some(*ch),
            left: None,
            right: None,
            id: next_id,
        };
        heap.push(Reverse((node.weight, node.id, Box::new(node))));
        next_id += 1;
    }

    // Huffman tree construction
    while heap.len() > 1 {
        let Reverse((w1, _id1, n1)) = heap.pop().unwrap();
        let Reverse((w2, _id2, n2)) = heap.pop().unwrap();

        let merged = Node {
            weight: w1 + w2,
            symbol: None,
            left: Some(n1),
            right: Some(n2),
            id: next_id,
        };
        heap.push(Reverse((merged.weight, merged.id, Box::new(merged))));
        next_id += 1;
    }

    // The remaining node is the root
    let root = heap.pop().unwrap().0 .2;

    // Traverse the tree to collect codes
    let mut codes: HashMap<char, String> = HashMap::new();
    fn dfs(node: &Node, prefix: &mut String, out: &mut HashMap<char, String>) {
        if let Some(ch) = node.symbol {
            out.insert(ch, prefix.clone());
            return;
        }
        if let Some(ref left) = node.left {
            prefix.push('0');
            dfs(left, prefix, out);
            prefix.pop();
        }
        if let Some(ref right) = node.right {
            prefix.push('1');
            dfs(right, prefix, out);
            prefix.pop();
        }
    }
    dfs(&root, &mut String::new(), &mut codes);

    // Prepare output: Symbol Weight HuffmanCode
    let mut entries: Vec<(char, usize, String)> = freq
        .into_iter()
        .map(|(ch, w)| (ch, w, codes.get(&ch).cloned().unwrap_or_default()))
        .collect();

    // Sort by symbol for deterministic output
    entries.sort_by_key(|&(ch, _, _)| ch);

    for (ch, w, code) in entries {
        println!("{} {} {}", ch, w, code);
    }
}
