        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.len() < 3 {
            continue;
        }
        // The magnitude is the last field
        if let Ok(mag) = parts[parts.len() - 1].parse::<f64>() {
            if mag > 6.0 {
                println!("{}", line);
            }
        }
    }

    Ok(())
}

