fn parse_matrix(s: &str) -> Vec<Vec<i64>> {
    let rows: Vec<&str> = s.trim().split(';').collect();
    if rows.is_empty() {
        eprintln!("Empty matrix");
        exit(1);
    }
    let mut mat: Vec<Vec<i64>> = Vec::new();
    for row in rows {
        let mut vals: Vec<i64> = Vec::new();
        for token in row.split(',') {
            let t = token.trim();
            if t.is_empty() {
                continue;
            }
