use std::env;
use std::process::exit;

fn parse_matrix(s: &str) -> Vec<Vec<i64>> {
    let rows: Vec<&str> = s.trim().split(';').collect();
    if rows.is_empty() {
        eprintln!("Empty matrix");
        exit(1);
    }
    let mut mat: Vec<Vec<i64>> = Vec::new();
    for row in rows {
        let mut vals: Vec<i64> = Vec::new();
        for token in row.split(',') {
            let t = token.trim();
            if t.is_empty() {
                continue;
            }
            match t.parse::<i64>() {
                Ok(v) => vals.push(v),
                Err(_) => {
                    eprintln!("Invalid number '{}'", t);
                    exit(1);
                }
            }
        }
        if !mat.is_empty() && vals.len() != mat[0].len() {
            eprintln!("Inconsistent row lengths");
            exit(1);
        }
        mat.push(vals);
    }
    mat
}

