// generate all derangements of 0..n-1
fn derangements(n: usize) -> Vec<Vec<usize>> {
    fn backtrack(
        pos: usize,
        n: usize,
        current: &mut Vec<usize>,
        used: &mut Vec<bool>,
        result: &mut Vec<Vec<usize>>,
    ) {
        if pos == n {
            result.push(current.clone());
            return;
        }
        for v in 0..n {
            if used[v] || v == pos {
                continue;
            }
            used[v] = true;
            current[pos] = v;
            backtrack(pos + 1, n, current, used, result);
            used[v] = false;
        }
    }

    let mut result = Vec::new();
    if n == 0 {
        result.push(Vec::new());
        return result;
    }
    let mut current = vec![0; n];
    let mut used = vec![false; n];
    backtrack(0, n, &mut current, &mut used, &mut result);
    result
