use std::collections::HashMap;

fn main() {
    const DIGITS: &str = "123456789";
    const POSITIONS: usize = DIGITS.len() - 1; // 8 positions between digits
    const COMBINATIONS: usize = 3usize.pow(POSITIONS as u32); // 3^8 = 6561

    let digits: Vec<i64> = DIGITS
        .bytes()
        .map(|b| (b - b'0') as i64)
        .collect();

    // map from sum -> list of expressions that evaluate to that sum
    let mut sum_to_exprs: HashMap<i64, Vec<String>> = HashMap::new();

    for mut mask in 0..COMBINATIONS {
        // decode mask into base‑3 choices for each position
        let mut ops = [0u8; POSITIONS];
        for i in 0..POSITIONS {
            ops[i] = (mask % 3) as u8;
            mask /= 3;
        }

        // build expression string and evaluate it
        let mut expr = String::new();
        expr.push_str(&DIGITS[0..1]); // first digit

        let mut total: i64 = 0;
        let mut current = digits[0];
        let mut sign: i64 = 1; // sign of the current number

        for (i, &op) in ops.iter().enumerate() {
            let d = digits[i + 1];
            match op {
                0 => {
                    // concatenate
                    current = current * 10 + d;
                    expr.push_str(&DIGITS[i + 1..i + 2]);
                }
                1 => {
                    // '+'
                    total += sign * current;
                    current = d;
                    sign = 1;
                    expr.push_str(" + ");
                    expr.push_str(&DIGITS[i + 1..i + 2]);
                }
                2 => {
                    // '-'
                    total += sign * current;
                    current = d;
                    sign = -1;
                    expr.push_str(" - ");
                    expr.push_str(&DIGITS[i + 1..i + 2]);
                }
                _ => unreachable!(),
            }
        }
        total += sign * current; // add the last number

        sum_to_exprs
            .entry(total)
            .or_insert_with(Vec::new)
            .push(expr);
    }

    // ---------- 1. All solutions that sum to 100 ----------
    let target = 100i64;
    let empty_vec: Vec<String> = Vec::new(); // placeholder for missing key
    let solutions = sum_to_exprs.get(&target).unwrap_or(&empty_vec);
    println!("Solutions for sum {} ({}):", target, solutions.len());
    for e in solutions {
        println!("{}", e);
    }
    println!();

    // ---------- 2. Sum with the maximum number of solutions ----------
    let mut max_sum = 0i64;
    let mut max_count = 0usize;
    for (s, exprs) in &sum_to_exprs {
        if exprs.len() > max_count {
            max_count = exprs.len();
            max_sum = *s;
        }
    }
    println!(
        "Sum with the maximum number of solutions: {} ({} solutions)",
        max_sum, max_count
    );
    println!();

    // ---------- 3. Lowest positive sum that cannot be expressed ----------
