fn split_escaped(s: &str, sep: char, esc: char) -> Vec<String> {
    let mut fields = Vec::new();
    let mut current = String::new();
    let mut escaped = false;

    for ch in s.chars() {
        if escaped {
            // this character was escaped; keep it literally
            current.push(ch);
            escaped = false;
        } else if ch == esc {
            // start an escape sequence; the escape char itself is omitted
            escaped = true;
        } else if ch == sep {
            // unescaped separator: end current field
            fields.push(current);
            current = String::new();
        } else {
            current.push(ch);
        }
    }

    // push the last field (may be empty)
    fields.push(current);
    fields
}

