use std::collections::{HashMap, HashSet, VecDeque};

/// Returns a compile order for VHDL libraries given a dependency description.
///
/// `input` is a multi‑line string where each line contains a library name followed by
/// zero or more space‑separated dependencies. Empty lines and lines starting with `#` are ignored.
///
/// The function returns `Ok(order)` where `order` is a vector of library names such that every
/// library appears after all of its dependencies. If a cycle is detected the function returns
/// `Err(msg)` describing the un‑orderable libraries.
pub fn compile_order(input: &str) -> Result<Vec<String>, String> {
    // Parse the input.
    let mut adj: HashMap<String, HashSet<String>> = HashMap::new(); // lib -> set of dependents
    let mut indeg: HashMap<String, usize> = HashMap::new(); // lib -> number of incoming edges

    for line in input.lines() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let mut parts = line.split_whitespace();
        let lib = parts.next().unwrap().to_string();

        // Ensure entry exists.
        adj.entry(lib.clone()).or_default();
        indeg.entry(lib.clone()).or_insert(0);

        for dep in parts {
            let dep = dep.to_string();
            // Ignore self‑dependencies.
            if dep == lib {
                continue;
            }

            // Edge: dep -> lib (lib depends on dep)
            adj.entry(dep.clone()).or_default().insert(lib.clone());

            // Increase indegree of lib.
            *indeg.entry(lib.clone()).or_insert(0) += 1;
            // Ensure dep is present in indeg map.
            indeg.entry(dep).or_insert(0);
        }
    }

    // Kahn's algorithm.
    let mut queue: VecDeque<String> = indeg
        .iter()
        .filter_map(|(k, &v)| if v == 0 { Some(k.clone()) } else { None })
        .collect();

    let mut order = Vec::with_capacity(indeg.len());

    while let Some(node) = queue.pop_front() {
        order.push(node.clone());

        // For each dependent, reduce indegree.
        if let Some(dependents) = adj.get(&node) {
            for dep in dependents {
                if let Some(cnt) = indeg.get_mut(dep) {
                    *cnt -= 1;
                    if *cnt == 0 {
                        queue.push_back(dep.clone());
                    }
                }
            }
        }
    }

    if order.len() == indeg.len() {
        Ok(order)
    } else {
        // Find remaining nodes (part of a cycle).
        let remaining: Vec<String> = indeg
            .into_iter()
            .filter(|(_, v)| *v > 0)
            .map(|(k, _)| k)
            .collect();
        Err(format!(
            "Un-orderable dependencies (cycle detected): {:?}",
            remaining
        ))
    }
}

