use std::io::{self, Write};

fn tpk_function(x: f64) -> f64 {
    x.abs().sqrt() + 5.0 * x.powi(3)
}

fn main() {
    const N: usize = 11;
    let mut numbers: Vec<f64> = Vec::with_capacity(N);

    // Prompt before reading the eleven inputs
    print!("Enter {} numbers (one per line):\n", N);
    io::stdout().flush().unwrap();

    let stdin = io::stdin();
    while numbers.len() < N {
        let mut line = String::new();
        if stdin.read_line(&mut line).is_err() {
            eprintln!("Failed to read input.");
            return;
        }
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }
        match trimmed.parse::<f64>() {
            Ok(val) => numbers.push(val),
            Err(_) => {
                eprintln!("Invalid number, please try again.");
            }
        }
    }

    // Process in reverse order
    for &x in numbers.iter().rev() {
        let result = tpk_function(x);
        if result > 400.0 {
            println!("Overflow for {}: result = {}", x, result);
        } else {
            println!("Result for {}: {}", x, result);
        }
    }
}

