    let n: usize = args[1].parse().expect("Invalid n");
    let base: u32 = args[2].parse().expect("Invalid base");

    // Generate Van Eck sequence
    let mut seq: Vec<usize> = Vec::with_capacity(n);
    let mut last_pos: HashMap<usize, usize> = HashMap::new(); // value -> last index

    // first term
    seq.push(0);
