use std::fmt;

/// Compute the n‑th element of the Van der Corput sequence in the given base.
/// Returns a floating‑point value in the interval [0, 1).
fn van_der_corput(mut n: u64, base: u64) -> f64 {
    if base < 2 {
        panic!("Base must be at least 2");
    }
    let mut denominator = base as f64;
    let mut result = 0.0_f64;
    while n > 0 {
        let digit = (n % base) as f64;
        result += digit / denominator;
        n /= base;
        denominator *= base as f64;
    }
    result
}

/// Helper to format a floating point number with up to 10 decimal places,
/// trimming trailing zeros.
fn fmt_float(v: f64) -> String {
    // Use 12 digits of precision to keep enough detail for bases > 2
    let s = format!("{:.12}", v);
    let s = s.trim_end_matches('0').trim_end_matches('.');
    s.to_string()
}

