use std::fmt::Write;

type Vec3 = (i64, i64, i64);

fn dot(a: Vec3, b: Vec3) -> i64 {
    a.0 * b.0 + a.1 * b.1 + a.2 * b.2
}

fn cross(a: Vec3, b: Vec3) -> Vec3 {
    (
        a.1 * b.2 - a.2 * b.1,
        a.2 * b.0 - a.0 * b.2,
        a.0 * b.1 - a.1 * b.0,
    )
}

fn scalar_triple(a: Vec3, b: Vec3, c: Vec3) -> i64 {
    dot(a, cross(b, c))
}

