use std::env;

/// Greedy word‑wrap: put as many whole words on a line as will fit.
fn wrap_greedy(text: &str, width: usize) -> String {
    if width == 0 {
        return text.to_string();
    }

    let mut lines = Vec::new();
    let mut current_line = String::new();

    for word in text.split_whitespace() {
        if current_line.is_empty() {
            // first word on the line
            current_line.push_str(word);
        } else {
            // +1 for the space that would be added
            let projected_len = current_line.len() + 1 + word.len();
            if projected_len <= width {
                current_line.push(' ');
                current_line.push_str(word);
            } else {
                lines.push(current_line);
                current_line = word.to_string();
            }
        }
    }

    if !current_line.is_empty() {
        lines.push(current_line);
    }

    lines.join("\n")
}

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() != 3 {
        eprintln!("Usage: {} <string> <wrap_at_length>", args[0]);
        std::process::exit(1);
