    let width: usize = match args[2].parse() {
        Ok(n) => n,
        Err(_) => {
            eprintln!("Error: wrap length must be a positive integer");
            std::process::exit(1);
        }
    };

    let wrapped = wrap_greedy(text, width);
    println!("{}", wrapped);
}

