        (0..5).filter(|&v| !used_col[v]).collect()
    };
    let drk_opts: Vec<usize> = if let Some(v) = drk[pos] {
        vec![v]
    } else {
        (0..5).filter(|&v| !used_drk[v]).collect()
    };
    let cig_opts: Vec<usize> = if let Some(v) = cig[pos] {
        vec![v]
    } else {
        (0..5).filter(|&v| !used_cig[v]).collect()
    };
    let pet_opts: Vec<usize> = if let Some(v) = pet[pos] {
        vec![v]
    } else {
        (0..5).filter(|&v| !used_pet[v]).collect()
    };

    for &n in &nat_opts {
        let nat_assigned = nat[pos].is_some();
        if !nat_assigned {
            nat[pos] = Some(n);
            used_nat[n] = true;
        }
        for &c in &col_opts {
            let col_assigned = col[pos].is_some();
            if !col_assigned {
                col[pos] = Some(c);
                used_col[c] = true;
            }
            for &d in &drk_opts {
                let drk_assigned = drk[pos].is_some();
                if !drk_assigned {
                    drk[pos] = Some(d);
                    used_drk[d] = true;
                }
                for &s in &cig_opts {
                    let cig_assigned = cig[pos].is_some();
                    if !cig_assigned {
                        cig[pos] = Some(s);
                        used_cig[s] = true;
                    }
                    for &p in &pet_opts {
                        let pet_assigned = pet[pos].is_some();
                        if !pet_assigned {
                            pet[pos] = Some(p);
                            used_pet[p] = true;
                        }

                        // check constraints that can be evaluated now
                        if partial_constraints_ok(pos, nat, col, drk, cig, pet) {
                            // recurse to next house
                            if solve(
                                pos + 1,
                                nat,
                                col,
                                drk,
                                cig,
                                pet,
                                used_nat,
                                used_col,
                                used_drk,
                                used_cig,
                                used_pet,
                                solution,
                                count,
                            ) {
                                return true;
                            }
                        }

                        // backtrack pet
                        if !pet_assigned {
                            pet[pos] = None;
                            used_pet[p] = false;
                        }
                    }
                    // backtrack cig
                    if !cig_assigned {
                        cig[pos] = None;
                        used_cig[s] = false;
                    }
                }
                // backtrack drk
                if !drk_assigned {
                    drk[pos] = None;
                    used_drk[d] = false;
                }
            }
            // backtrack col
            if !col_assigned {
                col[pos] = None;
                used_col[c] = false;
            }
        }
        // backtrack nat
        if !nat_assigned {
            nat[pos] = None;
            used_nat[n] = false;
        }
    }
    false
}

