fn to_array<T: Copy>(opt: &[Option<T>;5]) -> [T;5] {
    let mut arr = [opt[0].unwrap();5];
    for i in 0..5 {
        arr[i] = opt[i].unwrap();
    }
    arr
}

/* ---------------------------------------------------------------------- */

fn all_constraints_ok(
    nat: &[Option<usize>;5],
    col: &[Option<usize>;5],
    drk: &[Option<usize>;5],
    cig: &[Option<usize>;5],
    pet: &[Option<usize>;5],
) -> bool {
    // every field must be Some
    for i in 0..5 {
        if nat[i].is_none()
            || col[i].is_none()
            || drk[i].is_none()
            || cig[i].is_none()
            || pet[i].is_none()
        {
            return false;
        }
    }
    // now evaluate all constraints
    for i in 0..5 {
        let n = nat[i].unwrap();
        let c = col[i].unwrap();
        let d = drk[i].unwrap();
        let s = cig[i].unwrap();
        let p = pet[i].unwrap();

        // 1. English man lives in the red house.
        if n == ENGLISH && c != RED {
            return false;
        }
        // 2. Swede has a dog.
        if n == SWEDE && p != DOG {
            return false;
        }
        // 3. Dane drinks tea.
        if n == DANE && d != TEA {
            return false;
        }
        // 5. They drink coffee in the green house.
        if c == GREEN && d != COFFEE {
            return false;
        }
        // 6. Pall Mall smoker has a bird.
        if s == PALLMALL && p != BIRD {
            return false;
        }
        // 7. Yellow house -> Dunhill.
        if c == YELLOW && s != DUNHILL {
            return false;
        }
        // 8. Middle house drinks milk – already enforced before solving.
        // 10. Blend smoker lives next to cat.
        if s == BLEND {
            if !neighbor_has(i, |j| pet[j].unwrap() == CAT, pet) {
                return false;
            }
        }
        // 11. House next to horse smokes Dunhill.
        if p == HORSE {
            if !neighbor_has(i, |j| cig[j].unwrap() == DUNHILL, cig) {
                return false;
            }
        }
        // 12. Blue Master smoker drinks beer.
        if s == BLUE_MASTER && d != BEER {
            return false;
        }
        // 13. German smokes Prince.
        if n == GERMAN && s != PRINCE {
            return false;
        }
        // 15. Water drinker lives next to Blend smoker.
        if d == WATER {
            if !neighbor_has(i, |j| cig[j].unwrap() == BLEND, cig) {
                return false;
            }
        }
    }

    // 4. Green house immediately left of white house.
    let mut green_pos = None;
    let mut white_pos = None;
    for i in 0..5 {
        if col[i].unwrap() == GREEN {
            green_pos = Some(i);
        }
        if col[i].unwrap() == WHITE {
            white_pos = Some(i);
        }
    }
    if let (Some(g), Some(w)) = (green_pos, white_pos) {
        if g + 1 != w {
            return false;
        }
    } else {
        return false;
    }

    // 9. Norwegian lives in first house.
    if nat[0].unwrap() != NORWEGIAN {
        return false;
    }

    // 14. Norwegian lives next to the blue house.
    if !neighbor_has(0, |j| col[j].unwrap() == BLUE, col) {
        return false;
    }

    true
}

/* ---------------------------------------------------------------------- */

fn neighbor_has<F, A>(idx: usize, mut pred: F, arr: &[Option<A>;5]) -> bool
where
    F: FnMut(usize) -> bool,
{
    if idx > 0 && pred(idx - 1) {
        return true;
    }
    if idx + 1 < 5 && pred(idx + 1) {
        return true;
    }
    false
}

/* ---------------------------------------------------------------------- */

fn partial_constraints_ok(
    pos: usize,
    nat: &[Option<usize>;5],
    col: &[Option<usize>;5],
    drk: &[Option<usize>;5],
    cig: &[Option<usize>;5],
    pet: &[Option<usize>;5],
) -> bool {
    // evaluate constraints that involve only houses up to `pos`
    // If a constraint refers to a house beyond `pos` and that house is still None,
    // we cannot falsify it yet.
    for i in 0..=pos {
        let n = nat[i];
        let c = col[i];
        let d = drk[i];
        let s = cig[i];
        let p = pet[i];

        // 1. English -> red
        if let (Some(nv), Some(cv)) = (n, c) {
            if nv == ENGLISH && cv != RED {
                return false;
            }
        }
        // 2. Swede -> dog
        if let (Some(nv), Some(pv)) = (n, p) {
            if nv == SWEDE && pv != DOG {
                return false;
            }
        }
        // 3. Dane -> tea
        if let (Some(nv), Some(dv)) = (n, d) {
            if nv == DANE && dv != TEA {
                return false;
            }
        }
        // 5. green -> coffee
        if let (Some(cv), Some(dv)) = (c, d) {
            if cv == GREEN && dv != COFFEE {
                return false;
            }
        }
        // 6. Pall Mall -> bird
        if let (Some(sv), Some(pv)) = (s, p) {
            if sv == PALLMALL && pv != BIRD {
                return false;
            }
        }
        // 7. yellow -> Dunhill
        if let (Some(cv), Some(sv)) = (c, s) {
            if cv == YELLOW && sv != DUNHILL {
                return false;
            }
        }
        // 8. middle house drinks milk (house 2)
        if i == 2 {
            if let Some(dv) = d {
                if dv != MILK {
                    return false;
                }
            }
        }
        // 10. Blend smoker next to cat
        if let Some(sv) = s {
            if sv == BLEND {
                // need at least one neighbor with cat (if neighbor known)
                let left = if i > 0 { pet[i - 1] } else { None };
                let right = if i + 1 < 5 { pet[i + 1] } else { None };
                if left != Some(CAT) && right != Some(CAT) {
                    // if both neighbors are assigned and none is cat -> false
                    if i > 0 && left.is_some() && i + 1 < 5 && right.is_some() {
                        return false;
                    }
                }
            }
        }
        // 11. House next to horse smokes Dunhill
        if let Some(pv) = p {
            if pv == HORSE {
                let left = if i > 0 { cig[i - 1] } else { None };
                let right = if i + 1 < 5 { cig[i + 1] } else { None };
                if left != Some(DUNHILL) && right != Some(DUNHILL) {
                    if i > 0 && left.is_some() && i + 1 < 5 && right.is_some() {
                        return false;
                    }
                }
            }
        }
        // 12. Blue Master -> beer
        if let (Some(sv), Some(dv)) = (s, d) {
            if sv == BLUE_MASTER && dv != BEER {
                return false;
            }
        }
        // 13. German -> Prince
        if let (Some(nv), Some(sv)) = (n, s) {
            if nv == GERMAN && sv != PRINCE {
                return false;
            }
        }
        // 15. Water next to Blend
        if let Some(dv) = d {
            if dv == WATER {
                let left = if i > 0 { cig[i - 1] } else { None };
                let right = if i + 1 < 5 { cig[i + 1] } else { None };
                if left != Some(BLEND) && right != Some(BLEND) {
                    if i > 0 && left.is_some() && i + 1 < 5 && right.is_some() {
                        return false;
                    }
                }
            }
        }
    }

    // 4. green immediately left of white (can be checked when both known)
    let mut green_pos = None;
    let mut white_pos = None;
    for i in 0..=pos {
        if let Some(cv) = col[i] {
            if cv == GREEN {
                green_pos = Some(i);
            }
            if cv == WHITE {
                white_pos = Some(i);
            }
        }
    }
    if let (Some(g), Some(w)) = (green_pos, white_pos) {
        if g + 1 != w {
            return false;
        }
    }

    // 9. Norwegian first house
    if let Some(n0) = nat[0] {
        if n0 != NORWEGIAN {
            return false;
        }
    }

    // 14. Norwegian next to blue house
    if let Some(_) = nat[0] {
        // neighbor of house 0 must be blue
        if let Some(c1) = col[1] {
            if c1 != BLUE {
                return false;
            }
        } else {
            // not decided yet – ok
        }
    }

    true
}

