fn solve(
    pos: usize,
    nat: &mut [Option<usize>;5],
    col: &mut [Option<usize>;5],
    drk: &mut [Option<usize>;5],
    cig: &mut [Option<usize>;5],
    pet: &mut [Option<usize>;5],
    used_nat: &mut [bool;5],
    used_col: &mut [bool;5],
    used_drk: &mut [bool;5],
