    used_pet: &mut [bool;5],
    solution: &mut Option<( [usize;5], [usize;5], [usize;5], [usize;5], [usize;5] )>,
    count: &mut usize,
) -> bool {
    if pos == 5 {
        if all_constraints_ok(nat, col, drk, cig, pet) {
            *count += 1;
            if solution.is_none() {
                let n = to_array(nat);
                let c = to_array(col);
                let d = to_array(drk);
                let s = to_array(cig);
                let p = to_array(pet);
                *solution = Some((n, c, d, s, p));
            }
            // stop early if we only need the first solution
            return false;
        }
        return false;
    }

    // Prepare possible values for each attribute at this house
    let nat_opts: Vec<usize> = if let Some(v) = nat[pos] {
        vec![v]
    } else {
        (0..5).filter(|&v| !used_nat[v]).collect()
    };
