/// A simple bit writer that collects bits and flushes them to a vector of bytes.
struct BitWriter {
    buffer: u8,       // current byte being built
    bits_filled: u8,  // number of bits already written into buffer (0..8)
    out: Vec<u8>,     // output bytes
}

impl BitWriter {
    fn new() -> Self {
        BitWriter {
            buffer: 0,
            bits_filled: 0,
            out: Vec::new(),
        }
    }

    /// Write a single bit (0 or 1). Bits are added from MSB to LSB.
    fn write_bit(&mut self, bit: u8) {
        self.buffer <<= 1;
        self.buffer |= bit & 1;
        self.bits_filled += 1;
        if self.bits_filled == 8 {
            self.out.push(self.buffer);
            self.buffer = 0;
            self.bits_filled = 0;
        }
    }

    /// Write the lowest `count` bits of `value` (count <= 8). Bits are written from MSB to LSB of the value.
    fn write_bits(&mut self, value: u8, count: u8) {
        for i in (0..count).rev() {
            let bit = (value >> i) & 1;
            self.write_bit(bit);
        }
    }

    /// Flush remaining bits, padding with zeros on the LSB side.
    fn flush(&mut self) {
        if self.bits_filled > 0 {
            self.buffer <<= 8 - self.bits_filled; // shift to fill MSB side
            self.out.push(self.buffer);
            self.buffer = 0;
            self.bits_filled = 0;
        }
    }

    /// Return the collected bytes.
    fn into_bytes(self) -> Vec<u8> {
        self.out
    }
}

