fn expand_fragment(f: &Fragment) -> Vec<String> {
    match f {
        Fragment::Literal(s) => vec![s.clone()],
        Fragment::Alternation(branches) => {
            let mut all = Vec::new();
            for branch in branches {
                let exp = expand_fragments(branch);
                all.extend(exp);
            }
            all
