            let literal: String = chars[start..pos].iter().collect();
            current_branch.push(Fragment::Literal(literal));
        }
    }
    if branches.len() > 1 {
        // This is an alternation
        (ParseResult::Fragment(Fragment::Alternation(branches)), pos)
    } else {
        // No comma: treat braces as literals, preserving inner content
        let mut seq = Vec::new();
        seq.push(Fragment::Literal("{".to_string()));
        if branches.len() == 1 {
            seq.extend(branches[0].clone());
        }
        seq.push(Fragment::Literal("}".to_string()));
        (ParseResult::Sequence(seq), pos)
    }
}

fn expand_fragments(fragments: &[Fragment]) -> Vec<String> {
    let mut result = vec!["".to_string()];
    for f in fragments {
        let expansions = expand_fragment(f);
        let mut new_result = Vec::new();
        for prev in &result {
            for exp in &expansions {
                new_result.push(format!("{}{}", prev, exp));
            }
        }
        result = new_result;
    }
    result
}

fn expand_fragment(f: &Fragment) -> Vec<String> {
    match f {
        Fragment::Literal(s) => vec![s.clone()],
        Fragment::Alternation(branches) => {
            let mut all = Vec::new();
            for branch in branches {
                let exp = expand_fragments(branch);
                all.extend(exp);
            }
            all
        }
    }
}

