// Extended Euclidean algorithm: returns (g, x, y) such that a*x + b*y = g = gcd(a,b)
fn egcd(a: i128, b: i128) -> (i128, i128, i128) {
    if b == 0 {
        (a, 1, 0)
    } else {
        let (g, x1, y1) = egcd(b, a % b);
        (g, y1, x1 - (a / b) * y1)
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() != 3 {
        eprintln!("Usage: <program> <comma_separated_ns> <comma_separated_as>");
        process::exit(1);
    }

    let ns: Vec<i128> = args[1]
        .split(',')
        .filter_map(|s| s.trim().parse::<i128>().ok())
        .collect();
    let as_vec: Vec<i128> = args[2]
        .split(',')
        .filter_map(|s| s.trim().parse::<i128>().ok())
        .collect();

    if ns.len() != as_vec.len() || ns.is_empty() {
        eprintln!("Invalid input lengths");
        process::exit(1);
    }

    let n_prod: i128 = ns.iter().product();

    let mut sum: i128 = 0;
    for (n_i, a_i) in ns.iter().zip(as_vec.iter()) {
        let ni_prod = n_prod / *n_i;
        let (g, x, _) = egcd(ni_prod, *n_i);
        if g != 1 {
            eprintln!("NO SOLUTION");
            process::exit(1);
        }
        let s_i = ((x % *n_i) + *n_i) % *n_i;
        sum = (sum + a_i * s_i * ni_prod) % n_prod;
    }

    let result = ((sum % n_prod) + n_prod) % n_prod;
    println!("{}", result);
}
