    let minutes = secs / SECS_PER_MIN;
    if minutes > 0 {
        parts.push(format!("{} min", minutes));
        secs %= SECS_PER_MIN;
    }

    if secs > 0 {
        parts.push(format!("{} sec", secs));
    }

    println!("{}", parts.join(", "));
}

