use std::fmt;

struct Game {
    grid: [[u8; 3]; 3],
}

impl Game {
    fn new() -> Self {
        // Blinker in vertical orientation
        let mut grid = [[0u8; 3]; 3];
        grid[0][1] = 1;
        grid[1][1] = 1;
        grid[2][1] = 1;
        Self { grid }
    }

    fn next(&mut self) {
        let mut new_grid = [[0u8; 3]; 3];
        for i in 0..3 {
            for j in 0..3 {
                let mut n = 0u8;
                for di in -1i32..=1 {
                    for dj in -1i32..=1 {
                        if di == 0 && dj == 0 {
                            continue;
                        }
                        let ni = i as i32 + di;
                        let nj = j as i32 + dj;
                        if ni >= 0 && ni < 3 && nj >= 0 && nj < 3 {
                            n += self.grid[ni as usize][nj as usize];
                        }
                    }
                }
                new_grid[i][j] = match (self.grid[i][j], n) {
                    (1, 2) | (1, 3) => 1, // Lives
                    (0, 3) => 1,          // Birth
                    _ => 0,               // Dies or stays dead
                };
            }
        }
        self.grid = new_grid;
    }
}

impl fmt::Display for Game {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        for row in &self.grid {
            for &cell in row {
                write!(f, "{} ", cell)?;
            }
            writeln!(f)?;
        }
        Ok(())
    }
}

fn main() {
    let mut game = Game::new();
    println!("Generation 0:");
    println!("{}", game);
    for gen in 1..=3 {
        game.next();
        println!("Generation {}:", gen);
        println!("{}", game);
    }
}
