fn parse_vector(s: &str) -> Vec<f64> {
    s.split(',')
        .filter_map(|x| x.trim().parse::<f64>().ok())
        .collect()
}

fn build_matrix(f: &[f64], ng: usize) -> Vec<Vec<f64>> {
    let nf = f.len();
    let nh = ng - nf + 1;
    let mut a = vec![vec![0.0; nh]; ng];
    for i in 0..ng {
        for j in 0..nh {
            let idx = i as isize - j as isize;
            if idx >= 0 && (idx as usize) < nf {
                a[i][j] = f[idx as usize];
            }
        }
    }
    a
}

fn solve_least_squares(a: &[Vec<f64>], g: &[f64]) -> Vec<f64> {
