fn node_to_index(name: &str) -> Option<usize> {
    match name {
        "a" => Some(0),
        "b" => Some(1),
        "c" => Some(2),
        "d" => Some(3),
        "e" => Some(4),
        "f" => Some(5),
        _ => None,
    }
}

// Map an index back to a node name
fn index_to_node(idx: usize) -> &'static str {
    match idx {
        0 => "a",
        1 => "b",
        2 => "c",
        3 => "d",
        4 => "e",
        5 => "f",
        _ => "?",
    }
}

// Dijkstra algorithm: returns (distances, previous node)
fn dijkstra(
    graph: &Vec<Vec<(usize, i32)>>,
    source: usize,
) -> (Vec<i32>, Vec<Option<usize>>) {
    let n = graph.len();
    let mut dist = vec![i32::MAX; n];
    let mut prev = vec![None; n];
    dist[source] = 0;

    let mut heap = BinaryHeap::new();
    heap.push(Reverse((0, source)));

    while let Some(Reverse((d, u))) = heap.pop() {
        if d > dist[u] {
            continue;
        }
        for &(v, w) in &graph[u] {
            let nd = d + w;
            if nd < dist[v] {
                dist[v] = nd;
                prev[v] = Some(u);
                heap.push(Reverse((nd, v)));
            }
        }
    }
    (dist, prev)
}

// Reconstruct path from source to target using prev array
fn reconstruct_path(prev: &Vec<Option<usize>>, target: usize) -> Vec<usize> {
    let mut path = Vec::new();
    let mut cur = target;
    while let Some(p) = prev[cur] {
        path.push(cur);
        cur = p;
    }
    path.push(cur); // source
    path.reverse();
    path
}

fn main() {
    // Build the graph
    let mut graph = vec![Vec::new(); 6];
    let edges = [
        ("a", "b", 7),
        ("a", "c", 9),
        ("a", "f", 14),
        ("b", "c", 10),
        ("b", "d", 15),
        ("c", "d", 11),
        ("c", "f", 2),
        ("d", "e", 6),
        ("e", "f", 9),
    ];
    for &(s, e, w) in &edges {
        let u = node_to_index(s).unwrap();
        let v = node_to_index(e).unwrap();
        graph[u].push((v, w));
    }

    // Read command line arguments: <node1> <node2>
    let args: Vec<String> = env::args().collect();
    if args.len() != 3 {
        eprintln!("Usage: {} <node1> <node2>", args[0]);
        std::process::exit(1);
    }
    let dest1 = node_to_index(&args[1]).expect("Invalid node name");
    let dest2 = node_to_index(&args[2]).expect("Invalid node name");
    let source = node_to_index("a").unwrap();

    let (dist, prev) = dijkstra(&graph, source);

    for &dest in &[dest1, dest2] {
        if dist[dest] == i32::MAX {
            println!("{} unreachable", index_to_node(dest));
            continue;
        }
        let path = reconstruct_path(&prev, dest);
        let mut output = String::new();
        for &node_idx in &path {
            output.push_str(index_to_node(node_idx));
            output.push(' ');
        }
        output.push_str(&dist[dest].to_string());
        println!("{}", output.trim_end());
    }
}

