    // Calculate maximum number to determine column width
    let max_num = rows * (rows + 1) / 2;
    let width = max_num.to_string().len();

    let mut current = 1;
    let stdout = io::stdout();
    let mut handle = stdout.lock();

    for row in 1..=rows {
        for col in 1..=row {
            write!(handle, "{:>width$}", current, width = width).unwrap();
            current += 1;
            if col != row {
                write!(handle, " ").unwrap();
            }
        }
        writeln!(handle).unwrap();
    }
