pub mod alphabet {
    /// A static string containing all lowercase ASCII letters.
    /// This is compile‑time constant and can be used wherever a `&str` is required.
    pub const ALPHABET_STR: &str = "abcdefghijklmnopqrstuvwxyz";

    /// Compile‑time array of all lowercase ASCII letters.
    /// Generated via a const function to avoid manual enumeration.
    const fn make_array() -> [char; 26] {
        let mut arr = ['\0'; 26];
        let mut i = 0usize;
        while i < 26 {
            // 97 is the ASCII code for 'a'
            arr[i] = (97 + i as u32) as u8 as char;
            i += 1;
        }
        arr
    }

    pub const ALPHABET_ARRAY: [char; 26] = make_array();

    /// Returns an iterator over the lowercase ASCII alphabet.
    /// The iterator is the standard library range `('a'..='z')`.
    pub fn iter() -> impl Iterator<Item = char> {
        ('a'..='z')
    }
