        let start = if i >= window { i - window } else { 0 };
        let end = (i + window + 1).min(s2_len);
        for j in start..end {
            if !matched_s2[j] && s1_chars[i] == s2_chars[j] {
                matched_s1[i] = true;
                matched_s2[j] = true;
                m += 1;
                break;
            }
        }
    }

    if m == 0 {
        return 0.0;
    }

    let matched_s1_chars: Vec<char> = matched_s1
        .iter()
        .zip(s1_chars.iter())
        .filter_map(|(m, c)| if *m { Some(*c) } else { None })
        .collect();

    let matched_s2_chars: Vec<char> = matched_s2
        .iter()
        .zip(s2_chars.iter())
        .filter_map(|(m, c)| if *m { Some(*c) } else { None })
        .collect();

    let mismatches = matched_s1_chars
        .iter()
        .zip(matched_s2_chars.iter())
        .filter(|(c1, c2)| c1 != c2)
        .count();

    let t = mismatches as f64 / 2.0;

    let similarity = (
        (m as f64) / (s1_len as f64)
            + (m as f64) / (s2_len as f64)
            + (m as f64 - t) / (m as f64)
    ) / 3.0;

    similarity
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() != 3 {
        eprintln!("Usage: <program> <string1> <string2>");
        return;
    }
    let s1 = &args[1];
    let s2 = &args[2];
    let sim = jaro_similarity(s1, s2);
    println!("{:.3}", sim);
}

