    let four_of_a_kind = rank_counts.iter().any(|&c| c == 4);
    let three_of_a_kind = rank_counts.iter().any(|&c| c == 3);
    let pair_counts = rank_counts.iter().filter(|&&c| c == 2).count();
    let full_house = three_of_a_kind && pair_counts == 1;
    let two_pair = pair_counts == 2;
    let one_pair = pair_counts == 1;

    if five_of_a_kind {
        Rank::FiveOfAKind
    } else if straight && flush {
        Rank::StraightFlush
    } else if four_of_a_kind {
        Rank::FourOfAKind
    } else if full_house {
        Rank::FullHouse
    } else if flush {
        Rank::Flush
    } else if straight {
        Rank::Straight
    } else if three_of_a_kind {
        Rank::ThreeOfAKind
    } else if two_pair {
        Rank::TwoPair
    } else if one_pair {
        Rank::OnePair
    } else {
        Rank::HighCard
    }
}

fn rank_to_str(r: Rank) -> &'static str {
    match r {
        Rank::HighCard => "high-card",
        Rank::OnePair => "one-pair",
        Rank::TwoPair => "two-pair",
        Rank::ThreeOfAKind => "three-of-a-kind",
        Rank::Straight => "straight",
        Rank::Flush => "flush",
        Rank::FullHouse => "full-house",
        Rank::FourOfAKind => "four-of-a-kind",
        Rank::StraightFlush => "straight-flush",
        Rank::FiveOfAKind => "five-of-a-kind",
    }
}

fn is_valid_hand(hand: &[Card]) -> bool {
    let mut set = HashSet::new();
    for c in hand {
        if let Card::Regular(r, s) = *c {
            if !set.insert((r, s)) {
                return false;
            }
        }
    }
    true
}

fn generate_all_cards() -> Vec<Card> {
    let mut cards = Vec::with_capacity(52);
    for rank in 0u8..13u8 {
        for &suit in &[Suit::Hearts, Suit::Diamonds, Suit::Clubs, Suit::Spades] {
            cards.push(Card::Regular(rank, suit));
        }
    }
    cards
}

fn main() {
    let args: Vec<String> = env::args().skip(1).collect();
    if args.len() != 5 {
        println!("invalid");
        return;
    }

    let mut parsed_cards = Vec::with_capacity(5);
    let mut joker_indices = Vec::new();
    let mut seen = HashSet::new();

    for (i, s) in args.iter().enumerate() {
        let card = match parse_card(s) {
            Ok(c) => c,
            Err(_) => {
                println!("invalid");
                return;
            }
        };
        if let Card::Regular(r, s) = card {
            if !seen.insert((r, s)) {
                println!("invalid");
                return;
            }
        } else {
            joker_indices.push(i);
        }
        parsed_cards.push(card);
    }

    if joker_indices.len() > 2 {
        println!("invalid");
        return;
    }

    let all_cards = generate_all_cards();

    let best_rank = if joker_indices.is_empty() {
        Some(evaluate_hand(&parsed_cards))
    } else {
        let mut best: Option<Rank> = None;
        if joker_indices.len() == 1 {
            for c1 in &all_cards {
                let mut hand = parsed_cards.clone();
                hand[joker_indices[0]] = *c1;
                if !is_valid_hand(&hand) {
                    continue;
                }
                let rank = evaluate_hand(&hand);
                best = Some(best.map_or(rank, |b| b.max(rank)));
            }
        } else {
            for c1 in &all_cards {
                for c2 in &all_cards {
                    let mut hand = parsed_cards.clone();
                    hand[joker_indices[0]] = *c1;
                    hand[joker_indices[1]] = *c2;
                    if !is_valid_hand(&hand) {
                        continue;
                    }
                    let rank = evaluate_hand(&hand);
                    best = Some(best.map_or(rank, |b| b.max(rank)));
                }
            }
        }
        best
    };

    match best_rank {
        Some(r) => println!("{}", rank_to_str(r)),
        None => println!("invalid"),
    }
}

