        .iter()
        .cloned()
        .filter(|&i| i < values.len())
        .map(|i| (i, values[i]))
        .collect();

    // Sort the subset by the values
    subset.sort_by_key(|&(_, val)| val);

    // Put the sorted values back into the original positions
    for (i, val) in subset {
        values[i] = val;
    }

    // Output the result as a comma‑separated list
    let output = values
        .iter()
        .map(|v| v.to_string())
        .collect::<Vec<_>>()
        .join(",");
    println!("{}", output);
