use std::env;

fn main() {
    // Gather all command‑line arguments after the program name and join them with spaces
    let args: Vec<String> = env::args().skip(1).collect();
    if args.is_empty() {
        return;
    }
    let input = args.join(" ");

    // Strip only control codes (0–31 and 127), keep all other characters
    let stripped: String = input.chars().filter(|&c| !is_control(c)).collect();

    println!("{}", stripped);
}

// Helper to identify ASCII control characters (0–31 and 127)
fn is_control(c: char) -> bool {
    let code = c as u32;
    (code <= 31) || (code == 127)
