use std::fmt;
use std::ops::{BitAnd, BitOr, Not, BitXor};

/// Three‑valued logic (trit)
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum Trit {
    True,
    Maybe,
    False,
}

impl From<bool> for Trit {
    fn from(b: bool) -> Self {
        if b { Trit::True } else { Trit::False }
    }
}

impl fmt::Display for Trit {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let s = match *self {
            Trit::True => "T",
            Trit::Maybe => "M",
            Trit::False => "F",
        };
        write!(f, "{}", s)
    }
}

/// Logical NOT
impl Not for Trit {
    type Output = Trit;
    fn not(self) -> Trit {
        match self {
            Trit::True => Trit::False,
            Trit::False => Trit::True,
            Trit::Maybe => Trit::Maybe,
        }
    }
}

/// Logical AND
impl BitAnd for Trit {
    type Output = Trit;
    fn bitand(self, rhs: Trit) -> Trit {
        use Trit::*;
        match (self, rhs) {
            (False, _) | (_, False) => False,
            (True, True) => True,
            (True, Maybe) | (Maybe, True) => Maybe,
            (Maybe, Maybe) => Maybe,
        }
    }
}

/// Logical OR
impl BitOr for Trit {
    type Output = Trit;
    fn bitor(self, rhs: Trit) -> Trit {
        use Trit::*;
        match (self, rhs) {
            (True, _) | (_, True) => True,
            (False, False) => False,
            (False, Maybe) | (Maybe, False) => Maybe,
            (Maybe, Maybe) => Maybe,
        }
    }
}

/// Logical XOR (optional)
impl BitXor for Trit {
    type Output = Trit;
    fn bitxor(self, rhs: Trit) -> Trit {
        use Trit::*;
        match (self, rhs) {
            (True, False) | (False, True) => True,
            (True, True) | (False, False) => False,
            _ => Maybe,
        }
    }
}

/// Logical implication (a ⊃ b)
pub trait Implies {
    fn implies(self, rhs: Self) -> Self;
}

impl Implies for Trit {
    fn implies(self, rhs: Trit) -> Trit {
        use Trit::*;
        match (self, rhs) {
            (False, _) => True,
            (True, True) => True,
            (True, False) => False,
            (True, Maybe) => Maybe,
            (Maybe, True) => True,
            (Maybe, False) => Maybe,
            (Maybe, Maybe) => Maybe,
        }
    }
}

/// Logical equivalence (a ≡ b)
pub trait Equivalent {
    fn equiv(self, rhs: Self) -> Self;
}

impl Equivalent for Trit {
    fn equiv(self, rhs: Trit) -> Trit {
        use Trit::*;
        match (self, rhs) {
            (True, True) | (False, False) => True,
            (True, False) | (False, True) => False,
            (True, Maybe) | (Maybe, True) | (False, Maybe) | (Maybe, False) => Maybe,
            (Maybe, Maybe) => Maybe,
        }
    }
