use std::collections::{HashMap, HashSet, VecDeque};

/// Performs a topological sort on the given dependency graph.
///
/// `deps` is a map from a library to the list of libraries it depends on.
/// Libraries that only appear as dependencies but have no entry of their own
/// are automatically added as nodes with no outgoing edges.
///
/// The function returns:
/// * `Ok(order)` – a vector of library names in a valid compile order.
/// * `Err(msg)` – an error message if the graph contains a cycle.
fn topo_sort(deps: &HashMap<String, Vec<String>>) -> Result<Vec<String>, String> {
    // All nodes in the graph
    let mut nodes: HashSet<String> = HashSet::new();
    // Adjacency list: dep -> set of libraries that depend on it
    let mut adj: HashMap<String, HashSet<String>> = HashMap::new();
    // Indegree count: number of dependencies for each library
    let mut indeg: HashMap<String, usize> = HashMap::new();

    // Populate nodes and initial indegree values
    for (lib, deps_list) in deps.iter() {
        nodes.insert(lib.clone());
        indeg.entry(lib.clone()).or_insert(0);
        for dep in deps_list {
            if dep == lib {
                // ignore self-dependency
                continue;
            }
            nodes.insert(dep.clone());
            adj.entry(dep.clone())
                .or_insert_with(HashSet::new)
                .insert(lib.clone());
            *indeg.entry(lib.clone()).or_insert(0) += 1;
        }
    }

    // Initialize queue with nodes that have no incoming edges
    let mut queue: VecDeque<String> = nodes
        .iter()
        .filter(|n| indeg.get(*n).unwrap_or(&0) == &0)
        .cloned()
        .collect();

    let mut order: Vec<String> = Vec::new();

    while let Some(node) = queue.pop_front() {
        order.push(node.clone());
