use std::io;
use std::io::Read;

const ENGLISH_FREQ: [f64; 26] = [
    8.167, 1.492, 2.782, 4.253, 12.702, 2.228, 2.015,
    6.094, 6.966, 0.153, 0.772, 4.025, 2.406, 6.749,
    7.507, 1.929, 0.095, 5.987, 6.327, 9.056, 2.758,
    0.978, 2.360, 0.150, 1.974, 0.074,
];

fn index_of_coincidence(group: &[u8]) -> f64 {
    let n = group.len() as f64;
    if n <= 1.0 {
        return 0.0;
    }
    let mut freq = [0u32; 26];
    for &c in group {
        freq[(c - b'A') as usize] += 1;
    }
    let mut sum = 0f64;
    for &f in &freq {
        sum += (f as f64) * ((f - 1) as f64);
    }
    sum / (n * (n - 1.0))
}

fn average_ic(cipher: &[u8], key_len: usize) -> f64 {
    let mut total_ic = 0.0;
    for i in 0..key_len {
        let mut group = Vec::new();
        let mut idx = i;
        while idx < cipher.len() {
            group.push(cipher[idx]);
            idx += key_len;
        }
        total_ic += index_of_coincidence(&group);
    }
    total_ic / key_len as f64
}

fn find_key_length(cipher: &[u8]) -> usize {
    let mut best_len = 1;
    let mut best_ic = 0.0;
    for len in 1..=20 {
        let ic = average_ic(cipher, len);
        if ic > best_ic {
            best_ic = ic;
            best_len = len;
        }
    }
    best_len
}

fn chi_squared_for_shift(group: &[u8], shift: u8) -> f64 {
    let n = group.len() as f64;
    let mut freq = [0u32; 26];
    for &c in group {
        let shifted = ((c - b'A') + shift) % 26;
        freq[shifted as usize] += 1;
    }
    let mut chi = 0.0;
    for i in 0..26 {
        let observed = freq[i] as f64;
        let expected = ENGLISH_FREQ[i] / 100.0 * n;
        chi += (observed - expected).powi(2) / expected.max(1e-6);
    }
    chi
}

fn find_key(cipher: &[u8], key_len: usize) -> Vec<u8> {
    let mut key = Vec::with_capacity(key_len);
    for i in 0..key_len {
        let mut group = Vec::new();
        let mut idx = i;
        while idx < cipher.len() {
            group.push(cipher[idx]);
            idx += key_len;
        }
        let mut best_shift = 0;
        let mut best_chi = std::f64::MAX;
        for shift in 0..26u8 {
            let chi = chi_squared_for_shift(&group, shift);
            if chi < best_chi {
                best_chi = chi;
                best_shift = shift;
            }
        }
        let key_shift = (26 - best_shift) % 26;
        key.push(key_shift);
    }
    key
}

fn decrypt(cipher: &str, key: &[u8]) -> String {
    let mut result = String::new();
    let mut key_idx = 0usize;
    for ch in cipher.chars() {
        if ch.is_ascii_uppercase() {
            let c_val = ch as u8 - b'A';
            let shift = key[key_idx % key.len()];
            let p_val = (26 + c_val - shift) % 26;
            result.push((b'A' + p_val) as char);
            key_idx += 1;
        } else {
            result.push(ch);
        }
    }
    result
}

