            continue;
        }

        let mut rem = n;
        let mut bits = Vec::new();

        for &f in fibs.iter().rev() {
            if f <= rem {
                bits.push('1');
                rem -= f;
            } else {
                bits.push('0');
            }
        }

        let first_one = bits.iter().position(|&c| c == '1').unwrap();
        let representation: String = bits[first_one..].iter().collect();
        writeln!(out, "{}", representation).unwrap();
    }
}

