    fn new() -> Self {
        BalancedTernary { digits: vec![] }
    }

    fn from_str(s: &str) -> Self {
        let mut bt = BalancedTernary::new();
        for c in s.chars().rev() {
            match c {
                '+' => bt.digits.push(1),
                '-' => bt.digits.push(-1),
                '0' => bt.digits.push(0),
                _ => panic!("Invalid character"),
            }
        }
        bt
    }

    fn from_i64(n: i64) -> Self {
        let mut bt = BalancedTernary::new();
        if n == 0 {
            bt.digits.push(0);
        } else {
            let mut num = n.abs();
            while num > 0 {
                let rem = (num % 3) as i8;
                match rem {
                    1 => bt.digits.push(1),
                    2 => bt.digits.push(-1),
                    _ => bt.digits.push(0),
                }
                num /= 3;
            }
            if n < 0 {
                let mut carry = false;
                for i in (0..bt.digits.len()).rev() {
                    match bt.digits[i] {
                        -1 => bt.digits[i] = 0,
                        0 => {
                            bt.digits[i] = -1;
                            break;
                        }
                        1 => {
                            if !carry {
                                bt.digits[i] = -1;
                                carry = true;
                            } else {
                                bt.digits[i] = 0;
                            }
                        }
                        _ => panic!("Invalid digit"),
                    }
                }
            }
        }
        bt
    }

    fn to_i64(&self) -> i64 {
        let mut sum: i64 = 0;
        for (i, &digit) in self.digits.iter().enumerate() {
            sum += digit as i64 * (3_i64.pow(i as u32));
        }
        sum
    }

