        let mut s = String::new();
        for &digit in self.digits.iter().rev() {
            match digit {
                1 => s.push('+'),
                -1 => s.push('-'),
                0 => s.push('0'),
                _ => panic!("Invalid digit"),
            }
        }
        s
    }

    fn add(&self, other: &Self) -> Self {
        let mut sum = BalancedTernary::new();
        let mut carry = false;
        let max_len = std::cmp::max(self.digits.len(), other.digits.len());
        for i in 0..max_len {
            let digit1 = if i < self.digits.len() { self.digits[i] } else { 0 };
            let digit2 = if i < other.digits.len() { other.digits[i] } else { 0 };
            let mut total = digit1 + digit2;
            if carry {
