use std::collections::{BinaryHeap, HashMap};
use std::env;

#[derive(Copy, Clone, Eq, PartialEq)]
struct State {
    cost: usize,
    node: usize,
}

impl Ord for State {
    fn cmp(&self, other: &State) -> std::cmp::Ordering {
        other.cost.cmp(&self.cost)
    }
}

impl PartialOrd for State {
    fn partial_cmp(&self, other: &State) -> Option<std::cmp::Ordering> {
        Some(self.cmp(other))
    }
}

fn dijkstra(graph: &HashMap<usize, Vec<(usize, usize)>>, start: usize) -> HashMap<usize, (usize, usize)> {
    let mut distances = HashMap::new();
    for node in graph.keys() {
        distances.insert(*node, (usize::MAX, 0));
    }
    distances.insert(start, (0, start));

    let mut priority_queue = BinaryHeap::new();
    priority_queue.push(State { cost: 0, node: start });

    while let Some(State { cost, node }) = priority_queue.pop() {
        if cost > *distances.get(&node).unwrap().0 {
            continue;
        }

        for &(neighbor, edge_cost) in graph.get(&node).unwrap() {
            let new_cost = cost + edge_cost;
            if new_cost < distances.get(&neighbor).unwrap().0 {
                distances.insert(neighbor, (new_cost, node));
                priority_queue.push(State { cost: new_cost, node: neighbor });
            }
        }
    }

    distances
}

fn shortest_path(graph: &HashMap<usize, Vec<(usize, usize)>>, start: usize, end: usize) -> Option<Vec<usize>> {
    let distances = dijkstra(graph, start);
    if distances.get(&end).unwrap().0 == usize::MAX {
        return None;
    }

    let mut path = vec![end];
    let mut current_node = end;

    while current_node != start {
        current_node = distances.get(&current_node).unwrap().1;
        path.push(current_node);
    }
    path.reverse();

    Some(path)
}

