fn hailstone_sequence(n: u32, memo: &mut HashMap<u32, Vec<u32>>) -> Vec<u32> {
    if let Some(seq) = memo.get(&n) {
        return seq.clone();
    }
    let mut sequence = vec![n];
    while n != 1 {
        if n % 2 == 0 {
            n = n / 2;
        } else {
            n = 3 * n + 1;
        }
        sequence.push(n);
    }
    memo.insert(sequence[0], sequence.clone());
    for i in (1..sequence.len()).rev() {
        if !memo.contains_key(&sequence[i]) {
            let mut new_seq = sequence[i..].to_vec();
            hailstone_sequence(new_seq[0], memo);
        }
    }
    sequence
}

fn main() {
    let mut memo: HashMap<u32, Vec<u32>> = HashMap::new();
    let sequence_27 = hailstone_sequence(27, &mut memo);
    assert_eq!(sequence_27.len(), 112);
    assert_eq!(&sequence_27[..4], &[27, 82, 41, 124]);
    assert_eq!(&sequence_27[sequence_27.len() - 4..], &[8, 4, 2, 1]);

    let mut max_length = 0;
    let mut max_number = 0;
    for i in 1..100000 {
        if memo.contains_key(&i) {
            continue;
        }
        let sequence = hailstone_sequence(i, &mut memo);
        if sequence.len() > max_length {
            max_length = sequence.len();
            max_number = i;
        }
    }

    println!("{} {}", max_length, max_number);
}

