fn levenshtein_distance(s1: &str, s2: &str) -> usize {
    let m = s1.len() + 1;
    let n = s2.len() + 1;
    let mut d = vec![vec![0; n]; m];

    for i in 1..m {
        d[i][0] = i;
    }
    for j in 1..n {
        d[0][j] = j;
    }

    for i in 1..m {
        for j in 1..n {
            let cost = if s1.chars().nth(i - 1).unwrap() == s2.chars().nth(j - 1).unwrap() {
                0
            } else {
                1
            };

            d[i][j] = std::cmp::min(
                std::cmp::min(d[i - 1][j] + 1,     // Deletion
                              d[i][j - 1] + 1),    // Insertion
                d[i - 1][j - 1] + cost            // Substitution or no operation
            );
        }
    }

    d[m - 1][n - 1]
