use itertools::Itertools;

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() != 2 {
        panic!("Invalid number of arguments");
    }

    let sequence_str = &args[1];
    let sequence: Vec<i32> = sequence_str
        .split(',')
        .map(|x| x.parse::<i32>().unwrap())
        .collect();

    for r in 2..=sequence.len() {
        for combination in sequence.iter().copied().combinations(r) {
            if is_non_continuous(&combination, &sequence) {
                println!(
                    "{}",
                    combination.into_iter().map(|x| x.to_string()).collect::<Vec<_>>().join(",")
                );
            }
        }
    }

    // Also consider single elements with gaps
    for i in 0..sequence.len() {
        for j in i + 2..sequence.len() {
            let subsequence = vec![sequence[i], sequence[j]];
            println!(
                "{}",
                subsequence.into_iter().map(|x| x.to_string()).collect::<Vec<_>>().join(",")
            );
        }
    }

    // Also consider subsequences of length 3 with gaps
    for i in 0..sequence.len() {
        for j in i + 1..sequence.len() {
            for k in j + 2..sequence.len() {
                let subsequence = vec![sequence[i], sequence[j], sequence[k]];
                println!(
                    "{}",
                    subsequence.into_iter().map(|x| x.to_string()).collect::<Vec<_>>().join(",")
                );
            }
        }
    }

    // Also consider subsequences of length more than 3 with gaps
    for r in 4..=sequence.len() {
        for combination in sequence.iter().copied().combinations(r) {
            if is_non_continuous(&combination, &sequence) {
                println!(
                    "{}",
                    combination.into_iter().map(|x| x.to_string()).collect::<Vec<_>>().join(",")
                );
            }
        }
    }
}

fn is_non_continuous(combination: &[i32], sequence: &[i32]) -> bool {
    let mut indices = Vec::new();
    for &x in combination {
        if let Some(index) = sequence.iter().position(|y| *y == x) {
            indices.push(index);
        }
    }

    for i in 0..indices.len() - 1 {
        if indices[i + 1] != indices[i] + 1 {
            return true;
        }
    }

    false
}
