fn consolidate_ranges(ranges: Vec<(f64, f64)>) -> Vec<(f64, f64)> {
    let mut ranges = ranges;
    loop {
        let mut new_ranges = Vec::new();
        let mut i = 0;
        while i < ranges.len() {
            let mut merged = false;
            let range1 = ranges[i];
            for j in (i + 1)..ranges.len() {
                let range2 = ranges[j];
                if range1.0 <= range2.1 && range2.0 <= range1.1 {
                    new_ranges.push((range1.0.min(range2.0), range1.1.max(range2.1)));
                    merged = true;
                    break;
                }
            }
            if !merged {
                new_ranges.push(range1);
            }
            i += 1;
        }
        if ranges.len() == new_ranges.len() {
            ranges.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap());
            for range in &mut ranges {
                if range.0 > range.1 {
                    let temp = range.0;
                    range.0 = range.1;
                    range.1 = temp;
                }
            }
            return ranges;
        }
        ranges = new_ranges;
    }
}

fn main() {
    println!("({}, {})", 1.1, 2.2);
    println!("({}, {})", 6.1, 8.3);
    println!("({}, {})", 1.0, 4.0);
    println!("({}, {})", -2.0, 10.0);
    let ranges = vec![(-6.0, -1.0), (-6.0, 3.0), (3.0, 8.0)];
    println!("{:?}", consolidate_ranges(ranges));
}

