use std::fs;
use std::io::{Read, Write};

fn substitute_char(c: char, shift: u8) -> char {
    if c.is_ascii_uppercase() {
        (((c as u8 - b'A' + shift) % 26) + b'A') as char
    } else if c.is_ascii_lowercase() {
        (((c as u8 - b'a' + shift) % 26) + b'a') as char
    } else {
        c
    }
}

fn encrypt_file(input_filename: &str, output_filename: &str, shift: u8) -> std::io::Result<()> {
    let mut input_file = fs::File::open(input_filename)?;
    let mut output_file = fs::File::create(output_filename)?;

    let mut buffer = String::new();
    input_file.read_to_string(&mut buffer)?;

    for c in buffer.chars() {
        let encrypted_char = substitute_char(c, shift);
        write!(output_file, "{}", encrypted_char)?;
    }

    Ok(())
}

fn decrypt_file(input_filename: &str, output_filename: &str, shift: u8) -> std::io::Result<()> {
    encrypt_file(input_filename, output_filename, 26 - shift)
}

fn main() -> std::io::Result<()> {
    let input_filename = "input.txt";
    let encrypted_filename = "encrypted.txt";
    let decrypted_filename = "decrypted.txt";
    let shift: u8 = 3;

    if std::path::Path::new(input_filename).exists() {
        fs::remove_file(input_filename)?;
    }
    if std::path::Path::new(encrypted_filename).exists() {
        fs::remove_file(encrypted_filename)?;
    }
    if std::path::Path::new(decrypted_filename).exists() {
        fs::remove_file(decrypted_filename)?;
    }

    // Create the input file before trying to read from it
    let mut input_file = fs::File::create(input_filename)?;
    write!(input_file, "Hello, World!")?;

    encrypt_file(input_filename, encrypted_filename, shift)?;
    decrypt_file(encrypted_filename, decrypted_filename, shift)?;

    Ok(())
}

