fn parse_log_file() -> (u32, Vec<String>) {
    let file = File::open("mlijobs.txt").unwrap();
    let reader = BufReader::new(file);

    let mut max_licenses: u32 = 0;
    let mut current_licenses: u32 = 0;
    let mut licenses_out: HashMap<u32, String> = HashMap::new();

    let mut timestamps: Vec<String> = vec![];

    for line in reader.lines() {
        let line = line.unwrap();
        if line.contains("OUT") {
            current_licenses += 1;
            if current_licenses > max_licenses {
                max_licenses = current_licenses;
                licenses_out.clear();
                licenses_out.insert(max_licenses, line.split('@').nth(1).unwrap().trim().to_string());
            } else if current_licenses == max_licenses {
                licenses_out.insert(max_licenses, line.split('@').nth(1).unwrap().trim().to_string());
            }
        } else if line.contains("IN") {
            current_licenses -= 1;
        }
    }

    for (_, timestamp) in &licenses_out {
        timestamps.push(timestamp.clone());
    }

    (max_licenses, timestamps)
}

fn main() -> std::io::Result<()> {
    download_log_file()?;
    let (max_licenses, timestamps) = parse_log_file();
    println!("Maximum licenses: {}", max_licenses);
    println!("Timestamps: {:?}", timestamps);
    Ok(())
}
