use std::collections::{HashMap, VecDeque};

fn topological_sort(dependencies: &HashMap<String, Vec<String>>) -> Option<Vec<String>> {
    let mut graph = HashMap::new();
    let mut in_degree = HashMap::new();

    for (library, deps) in dependencies {
        for dep in deps {
            graph.entry(dep.clone()).or_insert(Vec::new()).push(library.clone());
            *in_degree.entry(library.clone()).or_insert(0) += 1;
        }
    }

    let mut queue: VecDeque<String> = dependencies
        .keys()
        .filter(|lib| !in_degree.contains_key(lib.as_str())) 
        .map(|lib| lib.clone())
        .collect();

    // Remove self-dependencies from the queue as they will cause infinite loops in topological sorting.
    for (library, deps) in dependencies {
        if deps.contains(library) {
            queue.retain(|q_lib| q_lib != library);
        }
    }

    let mut sorted = Vec::new();

    while let Some(library) = queue.pop_front() {
        sorted.push(library.clone()); // Clone the value to avoid moving it

        if let Some(deps) = graph.get(&library) {
            for dep in deps {
                *in_degree.get_mut(dep).unwrap() -= 1;
                if *in_degree.get(dep).unwrap() == 0 {
                    queue.push_back(dep.clone());
                }
            }
        }
    }

    if sorted.len() != dependencies.len() {
        None
    } else {
        Some(sorted)
    }
}

