use std::str::FromStr;
use std::num::{BigInt, ToPrimitive};
use std::fmt;

#[derive(Debug, Clone)]
struct BalancedTernary {
    digits: Vec<i32>,
}

impl BalancedTernary {
    fn from_string(s: &str) -> Self {
        let mut digits = Vec::new();
        for c in s.chars() {
            match c {
                '+' => digits.push(1),
                '0' => digits.push(0),
                '-' => digits.push(-1),
                _ => panic!("Invalid character in balanced ternary string"),
            }
        }
        BalancedTernary { digits }
    }

    fn to_string(&self) -> String {
        self.digits.iter().map(|&d| match d {
            1 => '+',
            0 => '0',
            -1 => '-',
            _ => unreachable!(),
        }).collect()
    }

    fn from_decimal(n: i64) -> Self {
        let mut num = BigInt::from(n);
        let zero = BigInt::zero();
        let three = BigInt::from(3);

        let mut digits = Vec::new();

        while !num.is_zero() {
            let remainder = &num % &three;
            let div = &num / &three;

            let rem_int: i32 = match remainder.to_i64() {
                Some(r) => r as i32,
                None if remainder < zero => -1,
                _ => 1,
            };

            digits.push(rem_int);

            num = if rem_int == 1 {
                div
            } else if rem_int == -1 {
                *div + BigInt::one()
            } else {
                div
            };
        }

        BalancedTernary { digits }
    }

    fn to_decimal(&self) -> i64 {
        let mut result = BigInt::zero();
        let three = BigInt::from(3);

        for &digit in self.digits.iter().rev() {
            result *= &three;
            result += BigInt::from(digit);
        }

        if let Some(res) = result.to_i64() {
            res
        } else {
            panic!("Resulting number is too large to fit in i64");
        }
    }

    fn add(&self, other: &BalancedTernary) -> Self {
        let mut a_digits = self.digits.clone();
        let b_digits = other.digits.clone();

        let max_len = std::cmp::max(a_digits.len(), b_digits.len());
        let mut carry = 0;

        for i in 0..max_len {
            if i >= a_digits.len() {
                a_digits.push(0);
            }
            if i >= b_digits.len() {
                b_digits.push(0);
            }

            let sum = a_digits[i] + b_digits[i] + carry;
            match sum {
                -2 => { a_digits[i] = 1; carry = -1; },
                -1 | 0 | 1 => { a_digits[i] = sum; carry = 0; },
                2 => { a_digits[i] = -1; carry = 1; },
            }
        }

        if carry != 0 {
            a_digits.push(carry);
        }

        BalancedTernary { digits: a_digits }
    }

    fn negate(&self) -> Self {
        let mut result = Vec::new();
        for &digit in self.digits.iter() {
            result.push(-digit);
        }
        BalancedTernary { digits: result }
    }

    fn multiply(&self, other: &BalancedTernary) -> Self {
        let zero = BalancedTernary { digits: vec![0] };
        if self.is_zero() || other.is_zero() {
            return zero;
        }

        let mut result = zero.clone();
        for (i, &digit) in other.digits.iter().enumerate() {
            if digit == 0 {
                continue;
            }

            let mut shifted_self = self.digits.clone();
            shifted_self.resize(shifted_self.len() + i, 0);

            let temp = BalancedTernary { digits: shifted_self };
            result = match digit {
                -1 => result.add(&temp.negate()),
                1 => result.add(&temp),
                _ => unreachable!(),
            };
        }
        result
    }

    fn is_zero(&self) -> bool {
        self.digits.iter().all(|&d| d == 0)
    }
}

impl fmt::Display for BalancedTernary {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.to_string())
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() != 5 {
        eprintln!("Usage: <program> <a> <b> <c>");
        return;
    }

    let a_str = &args[1];
    let b_int: i64 = args[2].parse().expect("Invalid integer for b");
    let c_str = &args[3];

    let a = BalancedTernary::from_string(a_str);
    let b = BalancedTernary::from_decimal(b_int);
    let c = BalancedTernary::from_string(c_str);

    println!("a (decimal): {}", a.to_decimal());
    println!("b (decimal): {}", b.to_decimal());
    println!("c (decimal): {}", c.to_decimal());

    let result = a.multiply(&b.add(&c.negate()));
    println!("Result (ternary): {}", result);
    println!("Result (decimal): {}", result.to_decimal());
}

