fn main() {
    println!("[1;5,2] + 1/2 = {:?}", calculate_continued_fraction(vec![1], vec![5, 2]) + f64::from_rational(1, 2));
    println!("[3;7] + 1/2 = {:?}", calculate_continued_fraction(vec![3], vec![7]) + f64::from_rational(1, 2));
    println!("[3;7] divided by 4 = {:?}", calculate_continued_fraction(vec![3], vec![7]) / 4.0);

