    let mut gen = sqrt_2_generator.take(10).collect::<Vec<_>>();

    let inv_sqrt_2 = calculate_inverted_gen(&gen, 1.0);
    println!("1/sqrt(2) = {:?}", inv_sqrt_2);

    let agm_start = (1.0 + inv_sqrt_2) / 2.0;
    println!("(1 + 1/√2)/2 = {:?}", agm_start);
