fn calculate_continued_fraction(a: Vec<i64>, b: Vec<i64>) -> f64 {
    if a.is_empty() || b.is_empty() {
        return 0.0;
    }

    let mut matrix = Matrix::new(1, 0, 0, 1);
    for (i, &term) in a.iter().enumerate() {
        if i > 0 {
            let term_next = *b.get(i - 1).unwrap_or(&f64::INFINITY as i64);
            matrix.next_term(term_next as f64);

            while matrix.can_output() {
                matrix.output();
            }
        }
    }

    matrix.to_fraction()
}

fn calculate_inverted_gen(gen: &Vec<f64>, value: f64) -> f64 {
    let mut state = Matrix::new(1, 0, 0, 1);

    for &term in gen.iter() {
        if !state.can_output() {
            state.next_term(term);
        }

        while state.can_output() {
            state.output();
        }
    }

    let mut result = value;
    let (mut a_1, mut b_1) = (state.a_1 as f64, state.b_1 as f64);

    for &term in gen.iter().rev() {
        if !state.can_output() {
            state.next_term(term);
        }

        while state.can_output() {
            let t = (a_1 / b_1).floor() as i64;
            result -= t * b_1;
            a_1 -= b_1 * t as f64;
            std::mem::swap(&mut a_1, &mut state.a);
            std::mem::swap(&mut b_1, &mut state.b);
        }
    }

    result / b_1
}

fn continued_fraction_sqrt(x: f64) -> impl Iterator<Item = i64> {
    let mut m = 0;
    let mut d = 1;
    let a0 = x.sqrt().floor() as i64;
    let mut a = a0;

    std::iter::from_fn(move || {
        if a == (2 * a0) {
            return None;
        }

        m = d * a - m;
        d = ((x - (m as f64).powi(2)) / d as f64).floor() as i64;
        a = ((a0 as f64 + (m as f64).sqrt()) / (d as f64).sqrt()).floor() as i64;

        Some(a)
    })
}

struct Matrix {
    a: i64,
    b: i64,
    a_1: i64,
    b_1: i64,
}

impl Matrix {
    fn new(a: i64, b: i64, a_1: i64, b_1: i64) -> Self {
        Matrix { a, b, a_1, b_1 }
    }

    fn next_term(&mut self, t: f64) {
        let t = t as i64;
        self.a = self.a + self.a_1 * t;
        self.b = self.b + self.b_1 * t;
    }

    fn output(&mut self) -> i64 {
        let t = (self.a as f64 / self.b as f64).floor() as i64;
        std::mem::swap(&mut self.a, &mut self.a_1);
        std::mem::swap(&mut self.b, &mut self.b_1);
        self.a -= self.b * t as f64;
        self.b = (self.b as f64 - t as f64 * self.a as f64).abs() as i64;
        t
    }

    fn can_output(&self) -> bool {
        self.b != 0 && ((self.a as f64 / self.b as f64).floor() as i64 == (self.a_1 as f64 / self.b_1 as f64).floor() as i64)
    }

    fn to_fraction(&self) -> f64 {
        if self.b == 0 {
            panic!("Division by zero");
        }
        self.a as f64 / self.b as f64
    }
}

