fn deconv(g: Vec<i32>, f: Vec<i32>) -> Option<Vec<i32>> {
    let g_len = g.len();
    let f_len = f.len();
    if f_len > g_len {
        return None;
    }

    // |H| will be given by |G| - |F| + 1
    let h_len = g_len - f_len + 1;

    // Construct matrix A
    let mut a = DMatrix::zeros(g_len, h_len);
    for i in 0..g_len {
