        if has_valid_extension(filename, &extensions) {
            println!("{} True", filename);
        } else {
            println!("{} False", filename);
        }
    }
}

fn has_valid_extension(filename: &str, extensions: &[String]) -> bool {
    let parts: Vec<&str> = filename.rsplitn(2, '.').collect();

    if parts.len() == 2 && !parts[1].is_empty() {
        let candidate_extension = format!("{}.{}", parts[0], parts[1]).to_lowercase();

        for ext in extensions.iter() {
            if candidate_extension == *ext {
                return true;
            }
        }
    }

    false
}

