    let mut symbol_table = (b'a'..=b'z').map(|c| c as char).collect::<Vec<char>>();
    input.chars().map(|symbol| {
        let index = symbol_table.iter().position(|&x| x == symbol).unwrap();
        symbol_table.remove(index);
        symbol_table.insert(0, symbol);
        index
    }).collect()
}

fn move_to_front_decode(indices: &[usize]) -> String {
    let mut symbol_table = (b'a'..=b'z').map(|c| c as char).collect::<Vec<char>>();
    indices.iter().map(|&index| {
        let symbol = symbol_table.remove(index);
        symbol_table.insert(0, symbol);
        symbol
    }).collect()
}

fn main() {
    let words = vec!["broood", "bananaaa", "hiphophiphop"];

    for word in words {
        let encoded: Vec<usize> = move_to_front_encode(word);

        // Show the string and its encoding
        println!("String: {}\nEncoding:", word);
        for &num in &encoded {
            print!(" {} ", num);
        }
        println!();

        // Decode to check if it matches the original
        let decoded = move_to_front_decode(&encoded);
        assert_eq!(word, &decoded);
    }
}

