fn find_pythagorean_triples(perimeter: usize) -> (usize, usize) {
    let mut total_count = 0;
    let mut primitive_count = 0;

    for m in 2.. {
        if m * m > perimeter / 2 {
            break;
        }
        for n in 1..m {
            if (m - n) % 2 == 1 && is_coprime(m, n) {
                let a = m * m - n * n;
                let b = 2 * m * n;
                let c = m * m + n * n;

                let mut k = 1;
                while k * (a + b + c) <= perimeter {
                    total_count += 1;
                    if k == 1 {
                        primitive_count += 1;
                    }
                    k += 1;
                }
            }
        }
    }

    (total_count, primitive_count)
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() != 2 {
        eprintln!("Usage: {} <perimeter>", args[0]);
        process::exit(1);
    }

    let perimeter: usize = match args[1].parse() {
        Ok(num) => num,
        Err(_) => {
            eprintln!("Error: Perimeter must be a positive integer.");
            process::exit(1);
        }
    };

    if perimeter == 0 {
        eprintln!("Error: Perimeter must be greater than zero.");
        process::exit(1);
    }

    let (total_triples, primitive_triples) = find_pythagorean_triples(perimeter);

    println!("{} {}", total_triples, primitive_triples);
}

