fn rename_items_in_directory(current_dir: &Path) -> io::Result<()> {
    // Rename file 'input.txt' to 'output.txt'
    let input_file_path = current_dir.join("input.txt");
    if input_file_path.exists() && input_file_path.is_file() {
        fs::rename(&input_file_path, current_dir.join("output.txt"))?;
    }

    // Rename directory 'docs' to 'mydocs'
    let docs_dir_path = current_dir.join("docs");
    if docs_dir_path.exists() && docs_dir_path.is_dir() {
        fs::rename(&docs_dir_path, current_dir.join("mydocs"))?;
    }

    Ok(())
}

fn main() -> io::Result<()> {
    // Rename items in the current working directory
    let cwd = std::env::current_dir()?;
    rename_items_in_directory(&cwd)?;

    // Rename items in the filesystem root (requires root permissions)
    if Path::new("/").exists() {
        rename_items_in_directory(Path::new("/"))?;
    }

    Ok(())
}

