fn calculate_checksum(sedol: &str) -> Option<char> {
    let weights = [1, 3, 1, 7, 3, 9];
    let valid_chars: Vec<char> = "0123456789BCDFGHJKLMNPQRSTVWXYZ".chars().collect();

    if sedol.len() != 6 || !sedol.chars().all(|c| valid_chars.contains(&c)) {
        return None;
