    let mut total = 0;

    for (i, c) in sedol.chars().enumerate() {
        let value = match c.to_digit(36) {
            Some(digit) => digit as u32,
            None => return None,
        };
        total += weights[i] * value;
    }

    let remainder = total % 10;
    let checksum_digit = if remainder == 0 { '0' } else { (10 - remainder).to_string().chars().next().unwrap() };

    Some(checksum_digit)
}

