fn is_self_describing(num: usize) -> bool {
    let s = format!("{num:0width$}", width = num.len());
    let mut counts = vec![0; 10];

    for digit in s.chars().map(|c| c.to_digit(10).unwrap()) {
        if digit < counts.len() as u32 {
            counts[digit as usize] += 1;
        } else {
            return false;
        }
    }

    for (i, &count) in counts.iter().enumerate() {
        let char_count: usize = s.chars()
                                  .filter(|&c| c.to_digit(10).unwrap() == i as u32)
                                  .count();

        if count != char_count {
            return false;
        }
    }

    true
}

fn generate_self_describing_numbers(limit: usize) -> Vec<usize> {
    (1..limit)
        .filter(|&num| is_self_describing(num))
        .collect()
}

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() != 2 {
        eprintln!("Usage: <program> <number>");
        return;
    }

    match args[1].parse::<usize>() {
        Ok(num) => {
            println!("{}", is_self_describing(num));
        },
        Err(_) => {
            eprintln!("Please provide a valid positive integer.");
        }
    }

    // Optional stretch goal: Generate and display self-describing numbers
    let self_describing_numbers = generate_self_describing_numbers(100_000_000);
    for num in &self_describing_numbers {
        println!("{}", num);
    }
}
