use std::env;
use std::str::FromStr;

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() != 3 {
        eprintln!("Usage: <program> <list of values> <list of indices>");
        return;
    }

    let values_str = &args[1];
    let indices_str = &args[2];

    let values: Vec<i32> = parse_comma_separated(values_str);
    let indices: Vec<usize> = parse_comma_separated(indices_str)
        .into_iter()
        .map(|i| i as usize - 1) // Adjust for zero-based indexing
        .collect();

    let sorted_values = sort_indices(&values, &indices);

    println!("{:?}", sorted_values.iter().map(|&v| v.to_string()).collect::<Vec<_>>().join(","));
}

fn parse_comma_separated(input: &str) -> Vec<i32> {
    input.split(',')
         .filter_map(|s| s.trim().parse::<i32>().ok())
         .collect()
}

fn sort_indices(values: &[i32], indices: &[usize]) -> Vec<i32> {
    let mut values_to_sort = indices
        .iter()
        .map(|&idx| values[idx])
        .collect::<Vec<_>>();

    values_to_sort.sort_unstable();

    let mut result = values.to_vec();

    for (i, &index) in indices.iter().enumerate() {
        result[index] = values_to_sort[i];
    }

    result
}

