fn patience_sort(mut nums: Vec<i32>) -> Vec<i32> {
    let mut piles = vec![];

    for &num in nums.iter() {
        // Find the first pile whose top element is greater than or equal to `num`
        if let Some(pile) = piles.iter_mut().find(|pile| pile.peek().map_or(false, |&top| top >= num)) {
            pile.push(num);
        } else {
            // Otherwise, create a new pile with `num` as the top element
            piles.push(BinaryHeap::from(vec![num]));
        }
    }

    // Reverse iterate over the piles and pop elements to form the sorted array
    let mut result = Vec::new();
    while !piles.is_empty() {
        let mut min_value: Option<i32> = None;

        for pile in &mut piles {
            if let Some(top) = pile.peek_mut() {
                if min_value.is_none() || top < *min_value.unwrap() {
                    min_value = Some(*top);
                }
            }
        }

        // Collect the minimum value from all piles
        result.push(min_value.unwrap());

        for pile in &mut piles {
            if let Some(top) = pile.peek_mut() {
                if top == min_value {
                    pile.pop();
                }
            }
        }

        // Remove empty piles
        piles.retain(|pile| !pile.is_empty());
    }

    result.reverse();  // Reverse to get ascending order
    result
}

