use std::f64::consts::PI;

fn reciprocal_difference(f: &[f64], x_vals: &[f64], indices: &[usize]) -> f64 {
    if indices.len() == 2 {
        let (i0, i1) = (indices[0], indices[1]);
        (x_vals[i0] - x_vals[i1]) / (f[i0] - f[i1])
    } else if indices.len() > 2 {
        let n_minus_1 = &indices[0..indices.len()-1];
        let n_minus_2 = &indices[1..indices.len()-1];

        let rho_n_minus_1_0 = reciprocal_difference(f, x_vals, n_minus_1);
        let rho_n_minus_1_1 = reciprocal_difference(
            f,
            x_vals,
            &n_minus_1.iter().skip(1).cloned().collect::<Vec<_>>(),
        );

        (x_vals[indices[0]] - x_vals[*indices.last().unwrap()]) / 
        (rho_n_minus_1_0 - rho_n_minus_1_1) + reciprocal_difference(f, x_vals, n_minus_2)
    } else {
        f64::INFINITY
    }
}

fn thiele_interpolation(x: f64, x_vals: &[f64], f_vals: &[f64]) -> f64 {
