use std::env;
use unicode_segmentation::UnicodeSegmentation;

fn wrap_text(text: &str, column_width: usize) -> String {
    let words: Vec<&str> = UnicodeSegmentation::graphemes(text, true).collect();
    let mut result = String::new();
    let mut current_line = String::new();

    for word in words.iter() {
        if current_line.len() + word.len() > column_width {
            result.push_str(&current_line);
            result.push('\n');
            current_line.clear();
        }

        if !current_line.is_empty() {
            current_line.push(' ');
        }

        current_line.push_str(word);

        // Remove trailing space for last word of the line
        if current_line.ends_with(' ') && !current_line.is_empty() {
            current_line.pop();
        }
    }

    if !current_line.is_empty() {
        result.push_str(&current_line);
    }

    result
}

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() != 3 {
        eprintln!("Usage: {} <string> <wrap at length>", args[0]);
        std::process::exit(1);
    }

    let text = &args[1];
    let column_width: usize = args[2].parse().expect("Expected a number for wrap width");

    let wrapped_text = wrap_text(text, column_width);
