fn fibonacci_numbers_up_to(n: u64) -> Vec<u64> {
    let mut fibs = vec![1, 2];
    while *fibs.last().unwrap() + fibs[fibs.len() - 2] <= n {
        fibs.push(fibs.last().unwrap() + fibs[fibs.len() - 2]);
    }
    fibs
}

fn zeckendorf_representation(mut n: u64) -> Vec<u8> {
    let mut fibs = fibonacci_numbers_up_to(n);
    let mut result = vec![0; fibs.len()];

    for i in (0..fibs.len()).rev() {
        if n >= fibs[i] {
            n -= fibs[i];
            result[i] = 1;

            // Skip the next Fibonacci number to ensure no two consecutive numbers are used
            if i > 0 {
                result.remove(i - 1);
            }
        }
    }

    while result.first().unwrap() == &0 {
        result.remove(0);
    }

    result
}

