fn find_min_abbreviation_length(words: &[String]) -> usize {
    if words.is_empty() {
        return 0;
    }

    let mut min_len = 1;
    let mut max_len = words[0].len();

    // Find maximum length of any word
    for word in words {
        max_len = max_len.max(word.len());
    }

    // Binary search for minimum length
    while min_len < max_len {
        let mid = (min_len + max_len) / 2;
        let mut prefixes = std::collections::HashMap::new();
        let mut is_valid = true;

        for word in words {
            let prefix = if word.len() >= mid {
                word[..mid].to_string()
            } else {
                word.clone()
            };

            if let Some(count) = prefixes.get_mut(&prefix) {
                *count += 1;
                if *count > 1 {
                    is_valid = false;
                    break;
                }
            } else {
                prefixes.insert(prefix, 1);
            }
        }

        if is_valid {
            max_len = mid;
        } else {
            min_len = mid + 1;
        }
    }

    min_len
