    for word in words {
        max_len = max_len.max(word.len());
    }

    // Binary search for minimum length
    while min_len < max_len {
        let mid = (min_len + max_len) / 2;
        let mut prefixes = std::collections::HashMap::new();
        let mut is_valid = true;

        for word in words {
            let prefix = if word.len() >= mid {
                word[..mid].to_string()
            } else {
                word.clone()
            };

            if let Some(count) = prefixes.get_mut(&prefix) {
                *count += 1;
                if *count > 1 {
                    is_valid = false;
                    break;
                }
            } else {
                prefixes.insert(prefix, 1);
            }
        }

        if is_valid {
            max_len = mid;
        } else {
            min_len = mid + 1;
        }
    }

    min_len
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() != 2 {
        eprintln!("Usage: {} <filename>", args[0]);
        std::process::exit(1);
    }

    let filename = &args[1];
    let file = File::open(filename).expect("Failed to open file");
    let reader = BufReader::new(file);

    for line in reader.lines() {
        let line = line.expect("Failed to read line");
        if line.trim().is_empty() {
            println!("0");
            continue;
        }

        let words: Vec<String> = line
            .split_whitespace()
            .map(|s| s.to_string())
            .collect();

        let min_len = find_min_abbreviation_length(&words);
        println!("{}", min_len);
    }
