use std::io::{self, Write};

struct BitWriter {
    buffer: u8,
    bits_in_buffer: u8,
}

impl BitWriter {
    fn new() -> Self {
        BitWriter {
            buffer: 0,
            bits_in_buffer: 0,
        }
    }

    fn write_bit(&mut self, bit: u8) -> io::Result<()> {
        self.buffer = (self.buffer << 1) | (bit & 1);
        self.bits_in_buffer += 1;

        if self.bits_in_buffer == 8 {
            print!("{:08b}", self.buffer);
            self.buffer = 0;
            self.bits_in_buffer = 0;
        }

        Ok(())
    }

    fn write_bits(&mut self, bits: u64, num_bits: u8) -> io::Result<()> {
        let mut bits = bits;
        let mut num_bits = num_bits;

        // Write bits from most significant to least significant
        while num_bits > 0 {
            num_bits -= 1;
            let bit = (bits >> num_bits) & 1;
            self.write_bit(bit)?;
        }

        Ok(())
    }

    fn flush(&mut self) -> io::Result<()> {
        // Pad with zeros if needed
        while self.bits_in_buffer > 0 {
            self.write_bit(0)?;
        }
        Ok(())
    }
}

struct BitReader {
    buffer: u8,
    bits_in_buffer: u8,
    input: Vec<u8>,
    pos: usize,
}

impl BitReader {
    fn new(input: Vec<u8>) -> Self {
        BitReader {
            buffer: 0,
            bits_in_buffer: 0,
            input,
            pos: 0,
        }
    }

    fn read_bit(&mut self) -> io::Result<u8> {
        if self.bits_in_buffer == 0 {
            if self.pos < self.input.len() {
                self.buffer = self.input[self.pos];
                self.pos += 1;
                self.bits_in_buffer = 8;
            } else {
                return Err(io::Error::new(io::ErrorKind::UnexpectedEof, "End of input"));
            }
        }

        self.bits_in_buffer -= 1;
        let bit = (self.buffer >> self.bits_in_buffer) & 1;
        Ok(bit)
    }

    fn read_bits(&mut self, num_bits: u8) -> io::Result<u64> {
        let mut result = 0u64;

        for _ in 0..num_bits {
            let bit = self.read_bit()?;
            result = (result << 1) | bit as u64;
        }

        Ok(result)
    }
}

fn compress(input: &str) -> Vec<u8> {
    let mut output = Vec::new();
    let mut buffer = 0u64;
    let mut bits_in_buffer = 0u8;

    for byte in input.bytes() {
        buffer = (buffer << 7) | (byte as u64 & 0x7F);
        bits_in_buffer += 7;

        while bits_in_buffer >= 8 {
            bits_in_buffer -= 8;
            let output_byte = (buffer >> bits_in_buffer) as u8;
            output.push(output_byte);
        }
    }

    // Handle remaining bits
    if bits_in_buffer > 0 {
        let output_byte = (buffer << (8 - bits_in_buffer)) as u8;
        output.push(output_byte);
    }

    output
}

fn decompress(input: &[u8], output_len: usize) -> String {
    let mut reader = BitReader::new(input.to_vec());
    let mut result = String::new();

    for _ in 0..output_len {
        let bits = reader.read_bits(7).unwrap();
        result.push((bits as u8) as char);
    }

    result
}

