fn next_generation(grid: &Vec<Vec<i32>>) -> Vec<Vec<i32>> {
    let rows = grid.len();
    let cols = grid[0].len();
    let mut new_grid = vec![vec![0; cols]; rows];

    for i in 0..rows {
        for j in 0..cols {
            let mut neighbors = 0;

            // Check all 8 neighbors
            for di in -1..=1 {
                for dj in -1..=1 {
                    if di == 0 && dj == 0 {
                        continue; // Skip the cell itself
                    }
                    let ni = i as i32 + di;
                    let nj = j as i32 + dj;

                    if ni >= 0 && ni < rows as i32 && nj >= 0 && nj < cols as i32 {
                        neighbors += grid[ni as usize][nj as usize];
                    }
                }
            }

            // Apply Conway's Game of Life rules
            if grid[i][j] == 1 {
                // Cell is alive
                if neighbors == 2 || neighbors == 3 {
                    new_grid[i][j] = 1; // Lives
                } else {
                    new_grid[i][j] = 0; // Dies
                }
            } else {
                // Cell is dead
                if neighbors == 3 {
                    new_grid[i][j] = 1; // Birth
                } else {
                    new_grid[i][j] = 0; // Stays dead
                }
            }
        }
    }

    new_grid
}

