fn binomial_coefficient(n: u64, k: u64) -> u64 {
    if k > n {
        return 0;
    }
    if k == 0 || k == n {
        return 1;
    }

    // Take advantage of symmetry: C(n,k) = C(n,n-k)
    let k = if k > n - k { n - k } else { k };

    let mut result = 1u64;
    for i in 0..k {
        result = result * (n - i) / (i + 1);
    }

    result
