fn longest_common_path(paths: &[&str], separator: char) -> String {
    if paths.is_empty() {
        return String::new();
    }

    if paths.len() == 1 {
        return paths[0].to_string();
    }

    let mut path_parts: Vec<Vec<&str>> = Vec::new();

