        if path.is_empty() {
            continue;
        }
        let parts: Vec<&str> = path.split(separator).collect();
        path_parts.push(parts);
    }

    if path_parts.is_empty() {
        return String::new();
    }

    let mut common_parts: Vec<&str> = Vec::new();
    let min_length = path_parts.iter().map(|p| p.len()).min().unwrap_or(0);

    for i in 0..min_length {
        let first_part = path_parts[0][i];
        let all_match = path_parts.iter().all(|parts| parts[i] == first_part);

        if all_match {
            common_parts.push(first_part);
        } else {
            break;
        }
    }

    if common_parts.is_empty() {
        // Handle case where paths start with separator but have no common parts
        if paths[0].starts_with(separator) {
            return separator.to_string();
        }
        return String::new();
    }

    let mut result = String::new();
    for (i, part) in common_parts.iter().enumerate() {
        if i > 0 {
            result.push(separator);
        }
        result.push_str(part);
    }

    // Handle root case properly
    if paths[0].starts_with(separator) && !result.starts_with(separator) {
        result = separator.to_string() + &result;
    }

    result
}
