    if numbers.len() <= order {
        return vec![];
    }

    let mut result = Vec::new();

    for i in 0..(numbers.len() - order) {
        let mut diff = 0;
        for k in 0..=order {
            let coefficient = binomial_coefficient(order, k);
            let sign = if (order - k) % 2 == 0 { 1 } else { -1 };
            diff += coefficient * sign * numbers[i + k];
        }
        result.push(diff);
    }

    result
}

fn binomial_coefficient(n: usize, k: usize) -> i64 {
    if k > n || k == 0 {
        return 1;
    }

    let mut result = 1i64;
    for i in 0..k {
        result = result * (n - i) / (i + 1);
    }
    result
}

