fn matrix_chain_multiplication(dimensions: &[i64]) -> (i64, Vec<usize>) {
    let n = dimensions.len() - 1;
    if n <= 1 {
        return (0, vec![]);
    }

    // dp[i][j] represents the minimum cost to multiply matrices from i to j
    let mut dp = vec![vec![0; n]; n];
    // split[i][j] represents the optimal split point for matrices from i to j
    let mut split = vec![vec![0; n]; n];

    // Length of chain to be multiplied
    for chain_len in 2..=n {
        // Starting index of chain
        for i in 0..=(n - chain_len) {
            // Ending index of chain
            let j = i + chain_len - 1;
            dp[i][j] = i64::MAX;

            // Try all possible split points
            for k in (i + 1)..j {
                let cost = dp[i][k] + dp[k][j] + dimensions[i] * dimensions[k] * dimensions[j];
                if cost < dp[i][j] {
                    dp[i][j] = cost;
                    split[i][j] = k;
                }
            }
        }
    }

    // Reconstruct the optimal solution
    let mut optimal_order = Vec::new();
    reconstruct_solution(&mut optimal_order, &split, 0, n - 1);

    (dp[0][n - 1], optimal_order)
}

fn reconstruct_solution(optimal_order: &mut Vec<usize>, split: &Vec<Vec<usize>>, i: usize, j: usize) {
    if i + 1 >= j {
        return;
    }

    let k = split[i][j];
    optimal_order.push(k);
    reconstruct_solution(optimal_order, split, i, k);
    reconstruct_solution(optimal_order, split, k, j);
}

fn main() {
    let test1 = [1, 5, 25, 30, 100, 70, 2, 1, 100, 250, 1, 1000, 2];
    let (cost1, order1) = matrix_chain_multiplication(&test1);
    println!("Test 1:");
    println!("Cost: {}", cost1);
    println!("Optimal order: {:?}", order1);

    let test2 = [1000, 1, 500, 12, 1, 700, 2500, 3, 2, 5, 14, 10];
    let (cost2, order2) = matrix_chain_multiplication(&test2);
    println!("\nTest 2:");
    println!("Cost: {}", cost2);
    println!("Optimal order: {:?}", order2);
}

