fn generate_permutations_with_signs(n: usize) -> Vec<(Vec<usize>, i32)> {
    let mut result = Vec::new();
    let mut perm = (0..n).collect::<Vec<usize>>();
    let mut sign = 1i32;

    // Generate all permutations using Heap's algorithm
    heap_permute(&mut perm, n, &mut result, &mut sign);

    result
}

fn heap_permute(perm: &mut Vec<usize>, n: usize, result: &mut Vec<(Vec<usize>, i32)>, sign: &mut i32) {
    if n == 1 {
        result.push((perm.clone(), *sign));
        return;
    }

    for i in 0..n {
        heap_permute(perm, n - 1, result, sign);

        // If n is odd, swap first and last element
        // If n is even, swap ith and last element
        if n % 2 == 1 {
            perm.swap(0, n - 1);
            *sign = -*sign;
        } else {
            perm.swap(i, n - 1);
            *sign = -*sign;
        }
