    let exact = |t: f64| -> f64 {
        0.0625 * (t * t + 4.0) * (t * t + 4.0)
    };

    // Differential equation: y' = t * sqrt(y)
    let dydt = |t: f64, y: f64| -> f64 {
        t * y.sqrt()
    };

    // Print header
    println!("t y error");

    // Print initial condition
    let error = (y - exact(t)).abs();
    println!("{:.1} {:.8} {:.8}", t, y, error);

