use std::fs::File;
use std::io::{Read, Write};
use std::collections::HashMap;

pub struct SubstitutionCipher {
    encryption_map: HashMap<char, char>,
    decryption_map: HashMap<char, char>,
}

impl SubstitutionCipher {
    pub fn new(key: &str) -> Self {
        let mut encryption_map = HashMap::new();
        let mut decryption_map = HashMap::new();

        let alphabet = "abcdefghijklmnopqrstuvwxyz";
        let key_chars: Vec<char> = key.chars().collect();

        // Create mapping for encryption
        for (i, char) in alphabet.chars().enumerate() {
            if i < key_chars.len() {
                encryption_map.insert(char, key_chars[i]);
                decryption_map.insert(key_chars[i], char);
            } else {
                encryption_map.insert(char, char);
                decryption_map.insert(char, char);
            }
        }

        // Handle uppercase letters
        for (i, char) in alphabet.chars().enumerate() {
            if i < key_chars.len() {
                let upper_char = char.to_ascii_uppercase();
                let upper_key_char = key_chars[i].to_ascii_uppercase();
                encryption_map.insert(upper_char, upper_key_char);
                decryption_map.insert(upper_key_char, upper_char);
            } else {
                let upper_char = char.to_ascii_uppercase();
                encryption_map.insert(upper_char, upper_char);
                decryption_map.insert(upper_char, upper_char);
            }
        }

        SubstitutionCipher {
            encryption_map,
            decryption_map,
        }
    }

