        input.read_to_string(&mut content)?;

        let encrypted_content: String = content
            .chars()
            .map(|c| *self.encryption_map.get(&c).unwrap_or(&c))
            .collect();

        let mut output = File::create(output_file)?;
        output.write_all(encrypted_content.as_bytes())?;

