        let decrypted_content: String = content
            .chars()
            .map(|c| *self.decryption_map.get(&c).unwrap_or(&c))
            .collect();

        let mut output = File::create(output_file)?;
        output.write_all(decrypted_content.as_bytes())?;

        Ok(())
    }
