fn van_der_corput(n: u64, base: u64) -> f64 {
    if n == 0 {
        return 0.0;
    }

    let mut result = 0.0;
    let mut power = 1.0 / base as f64;
    let mut num = n;

    while num > 0 {
        let remainder = num % base;
        result += remainder as f64 * power;
        num /= base;
        power /= base as f64;
