use std::env;

fn can_spell(word: &str, blocks: &[(char, char)], used: &mut [bool], pos: usize) -> bool {
    if pos == word.len() {
        return true;
    }

    let current_char = word.chars().nth(pos).unwrap().to_ascii_lowercase();

    for (i, &block) in blocks.iter().enumerate() {
        if used[i] {
            continue;
        }

        if block.0 == current_char || block.1 == current_char {
            used[i] = true;

            if can_spell(word, blocks, used, pos + 1) {
                return true;
            }

            used[i] = false;
        }
    }

    false
}

