struct BalancedTernary {
    digits: Vec<i8>,
}

impl BalancedTernary {
    pub fn from_str(s: &str) -> Result<Self, String> {
        let mut digits = Vec::new();
        for ch in s.chars() {
            let digit = match ch {
                '+' => 1,
                '-' => -1,
                '0' => 0,
                _ => return Err(format!("Invalid character in string: '{}'", ch)),
            };
            digits.push(digit);
        }
        digits.reverse();
        while let Some(&0) = digits.last() {
            digits.pop();
        }
        Ok(BalancedTernary { digits })
    }

    pub fn from_int(n: i32) -> Result<Self, String> {
        if n == 0 {
            return Ok(BalancedTernary { digits: vec![0] });
        }
        let mut digits = Vec::new();
        let mut num = n;
        while num != 0 {
            let remainder = num % 3;
            let digit = match remainder {
                0 => 0,
                1 => 1,
                2 => -1,
                _ => unreachable!(),
            };
            num = if digit == -1 {
                (num + 1) / 3
            } else {
                num / 3
            };
            digits.push(digit);
        }
        digits.reverse();
        Ok(BalancedTernary { digits })
    }

    pub fn to_int(&self) -> i32 {
        self.digits
            .iter()
            .enumerate()
            .map(|(i, &d)| d as i32 * 3_i32.pow(i as u32))
            .sum()
    }

    pub fn to_string(&self) -> String {
        let mut digits = self.digits.clone();
        digits.reverse();
        digits.iter()
            .map(|&d| match d {
                1 => '+',
                -1 => '-',
                0 => '0',
                _ => panic!("Invalid digit"),
            })
            .collect()
    }
}

