fn egyptian_divide(dividend: i32, divisor: i32) -> (i32, i32) {
    let mut powers = Vec::new();
    let mut doublings = Vec::new();

    let mut power = 1;
    let mut doubling = divisor;

    while doubling <= dividend {
        powers.push(power);
        doublings.push(doubling);
        power *= 2;
        doubling *= 2;
    }

    let mut answer = 0;
    let mut accumulator = 0;

    for i in (0..powers.len()).rev() {
        let current_power = powers[i];
        let current_doubling = doublings[i];

        if accumulator + current_doubling <= dividend {
            answer += current_power;
            accumulator += current_doubling;
        }
    }

    let remainder = dividend - accumulator;
    (answer, remainder)
}

