use std::env;

/// Computes the median of a slice of f64 values.
fn median(arr: &[f64]) -> f64 {
    let n = arr.len();
    let mid = n / 2;
    if n % 2 == 1 {
        arr[mid]
    } else {
        (arr[mid - 1] + arr[mid]) / 2.0
    }
}

fn main() {
    // Read the input from the command line.
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        eprintln!("Usage: {} <number_list>", args[0]);
        return;
    }

    let input = &args[1];
    let numbers: Vec<f64> = input
        .split(',')
        .map(|s| s.parse().expect("Invalid number in input"))
        .collect();

    // Sort the list.
    let mut sorted = numbers.clone();
    sorted.sort_by(|a, b| a.partial_cmp(b).unwrap());

    let n = sorted.len();
    let min = sorted[0];
    let max = sorted[n - 1];
    let med = median(&sorted);

    // Compute Q1 and Q3.
    let lower_half = &sorted[0..(n / 2)];
    let upper_half = &sorted[(n - n / 2)..];

    let q1 = if lower_half.is_empty() { med } else { median(lower_half) };
    let q3 = if upper_half.is_empty() { med } else { median(upper_half) };

    // Print the five-number summary with three decimal places.
    println!(
        "{:.3} {:.3} {:.3} {:.3} {:.3}",
        min, q1, med, q3, max
    );
}
```

