        for j in start_j..=end_j {
            if !matched_s2[j] && s1.as_bytes()[i] == s2.as_bytes()[j] {
                matched_s1[i] = true;
                matched_s2[j] = true;
                m += 1;
                break;
            }
        }
    }

    if m == 0 {
        return 0.0;
    }

    let mut matches = Vec::new();
    for i in 0..s1.len() {
        if matched_s1[i] {
            for j in 0..s2.len() {
                if matched_s2[j] && s1.as_bytes()[i] == s2.as_bytes()[j] {
                    matches.push((i, j));
                    break;
                }
            }
        }
    }

    matches.sort_by(|a, b| a.0.cmp(&b.0));
    let s2_positions: Vec<usize> = matches.iter().map(|&(_, j)| j).collect();

    let mut inversions = 0;
    for i in 0..s2_positions.len() {
        for j in i + 1..s2_positions.len() {
            if s2_positions[i] > s2_positions[j] {
                inversions += 1;
            }
        }
    }

    let t = inversions as f64 / 2.0;
    let term1 = m as f64 / s1.len() as f64;
    let term2 = m as f64 / s2.len() as f64;
    let term3 = (m as f64 - t) / m as f64;

    (term1 + term2 + term3) / 3.0
}

