fn get_middle_three(n: i64) -> Result<String, &'static str> {
    let num = n.abs();
    let s = num.to_string();
    let len = s.len();
    if len < 3 {
        return Err("ERROR");
    }
    if len % 2 == 0 {
        return Err("ERROR");
    }
    let start = (len - 3) / 2;
    Ok(s[start..start + 3].to_string())
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        println!("ERROR");
        return;
    }
    let input = &args[1];
    let n: i64 = match input.parse() {
        Ok(num) => num,
        Err(_) => {
            println!("ERROR");
            return;
        }
    };
    match get_middle_three(n) {
        Ok(result) => println!("{}", result),
        Err(_) => println!("ERROR"),
    }
}

