use reqwest::get;
use std::collections::HashSet;
use std::io;

#[tokio::main]
async fn main() -> io::Result<()> {
    let url = "http://wiki.puzzlers.org/pub/wordlists/unixdict.txt";
    let response = get(url).await?;
    let body = response.text().await?;

    let words: Vec<&str> = body.lines().collect();
    let word_set: HashSet<String> = words.iter().map(|w: &&str| w.to_string()).collect();

    let mut pairs = HashSet::new();

    for word in &words {
        let original = word.to_string();
        let reversed: String = word.chars().rev().collect();
        if reversed != original && word_set.contains(&reversed) && original < &reversed {
            pairs.insert((original, reversed));
        }
    }

    let count = pairs.len();
    let examples: Vec<String> = pairs.iter().take(5).map(|(a, b)| format!("{} {}", a, b)).collect();
    let examples_str = examples.join(" ");
    println!("{} {}", count, examples_str);

    Ok(())
}

