impl Vector {
    pub fn new(x: f64, y: f64) -> Self {
        Vector { x, y }
    }

    pub fn from_points(start: (f64, f64), end: (f64, f64)) -> Self {
        Vector::new(end.0 - start.0, end.1 - start.1)
    }

    pub fn from_magnitude_angle(magnitude: f64, angle: f64) -> Self {
