use std::ops::{Add, Sub, Mul, Div};

#[derive(Debug, Clone, Copy)]
pub struct Vector {
    pub x: f64,
    pub y: f64,
}

impl Vector {
    pub fn new(x: f64, y: f64) -> Self {
        Vector { x, y }
    }

    pub fn from_points(start: (f64, f64), end: (f64, f64)) -> Self {
        Vector::new(end.0 - start.0, end.1 - start.1)
    }

    pub fn from_magnitude_angle(magnitude: f64, angle: f64) -> Self {
        Vector::new(magnitude * angle.cos(), magnitude * angle.sin())
    }

    pub fn from_slope_magnitude(slope: f64, magnitude: f64) -> Self {
        let denominator = (1.0 + slope.powi(2)).sqrt();
        Vector::new(magnitude / denominator, slope * magnitude / denominator)
    }

    pub fn pretty_print(&self) {
        println!("Vector: ({:.2}, {:.2})", self.x, self.y);
    }
}

impl Add for Vector {
    type Output = Self;

    fn add(self, other: Self) -> Self {
        Vector::new(self.x + other.x, self.y + other.y)
    }
}

impl Sub for Vector {
    type Output = Self;

    fn sub(self, other: Self) -> Self {
        Vector::new(self.x - other.x, self.y - other.y)
    }
}

