use std::env;
use std::io;

/// A utility struct to write individual bits into a byte buffer.
struct BitWriter {
    buffer: Vec<u8>,
    current_byte: u8,
    bit_count: u8,
}

impl BitWriter {
    fn new() -> Self {
        BitWriter {
            buffer: Vec::new(),
            current_byte: 0,
            bit_count: 0,
        }
    }

    fn write_bit(&mut self, bit: u8) {
        assert!(bit == 0 || bit == 1);
        self.current_byte = (self.current_byte << 1) | (bit & 1);
        self.bit_count += 1;

        // If the current byte is full, push it to the buffer
        if self.bit_count == 8 {
            self.buffer.push(self.current_byte);
            self.current_byte = 0;
            self.bit_count = 0;
        }
    }

    fn flush(&mut self) {
        if self.bit_count > 0 {
            // Shift remaining bits to the left and push
            self.current_byte = self.current_byte << (8 - self.bit_count);
            self.buffer.push(self.current_byte);
            self.current_byte = 0;
            self.bit_count = 0;
        }
    }
}

fn main() -> io::Result<()> {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        eprintln!("Usage: {} <string>", args[0]);
        return Ok(());
    }

    let input = &args[1];
    let mut writer = BitWriter::new();

    for c in input.bytes() {
        let masked = c & 0x7F; // Keep only the lowest 7 bits
        for i in (0..7).rev() {
            let bit = (masked >> i) & 1;
            writer.write_bit(bit);
        }
    }

    writer.flush();

    // Output the resulting bytes
    for byte in writer.buffer {
        print!("{:02X} ", byte);
    }
    println!();

    Ok(())
}
