fn calculate_network_address(ip_with_prefix: &str) -> String {
    let parts: Vec<&str> = ip_with_prefix.splitn(2, '/').collect();
    if parts.len() != 2 || parts[1].is_empty() {
        panic!("Invalid input format. Expected 'IP/Prefix'.");
    }

    let ip_part = parts[0];
    let prefix_str = parts[1];

    let prefix = match prefix_str.parse::<u8>() {
        Ok(p) => p,
        Err(_) => panic!("Prefix must be an integer between 0 and 32."),
    };

    if prefix > 32 {
        panic!("Prefix must be between 0 and 32 inclusive.");
    }

    let octets: Vec<u8> = ip_part
        .split('.')
        .map(|s| {
            s.parse::<u8>()
                .unwrap_or_else(|_| panic!("Invalid IP address format."))
        })
        .collect();

    if octets.len() != 4 {
        panic!("Invalid IP address format.");
    }

    let ip_integer = ((octets[0] as u32) << 24) |
                     ((octets[1] as u32) << 16) |
                     ((octets[2] as u32) << 8) |
                      (octets[3] as u32);

    let mask = if prefix == 0 {
        0
    } else {
        let bits = (1u64 << (prefix as u32)) - 1;
        let shifted = bits << (32 - prefix as u32);
        (shifted & 0xFFFFFFFF) as u32
    };

    let network_integer = ip_integer & mask;

    let a = (network_integer >> 24) & 0xFF;
    let b = (network_integer >> 16) & 0xFF;
    let c = (network_integer >> 8) & 0xFF;
    let d = network_integer & 0xFF;

    format!("{}.{}.{}.{}", a, b, c, d)
}

