    for i in 0..n {
        let w = weights[i];
        let v = values[i];
        let mut m = max_counts[i];
        let mut k = 1;
        while k <= m {
            virtual_items.push((w * k, v * k, i as i32, k));
            m -= k;
            k *= 2;
        }
        if m > 0 {
            virtual_items.push((w * m, v * m, i as i32, m));
        }
    }

    // Step 2: 0-1 Knapsack DP
    let mut dp = vec![0; (capacity + 1) as usize];
    for &(weight, value, _, _) in &virtual_items {
