/// Computes the Levenshtein distance between two strings.
fn levenshtein(a: &str, b: &str) -> usize {
    let m = a.chars().count();
    let n = b.chars().count();

    // Initialize a 2D array for dynamic programming
    let mut dp = vec![vec![0; n + 1]; m + 1];

    // Base cases: converting empty string to a non-empty one
    for i in 0..=m {
        dp[i][0] = i;
    }
    for j in 0..=n {
        dp[0][j] = j;
    }

    // Fill the table using dynamic programming
    for (i, char_a) in a.chars().enumerate() {
        for (j, char_b) in b.chars().enumerate() {
            let i1 = i + 1;
            let j1 = j + 1;

            // Compute cost of substitution
            let cost = if char_a == char_b { 0 } else { 1 };

            // Compute minimum of the three possible operations
            dp[i1][j1] = *[
                dp[i1 - 1][j1] + 1,       // Deletion
                dp[i1][j1 - 1] + 1,       // Insertion
                dp[i1 - 1][j1 - 1] + cost, // Substitution
            ]
            .iter()
            .min()
            .unwrap();
        }
    }

    // The final result is at the bottom-right corner
    dp[m][n]
}

