    let n: u32 = match n_str.parse() {
        Ok(n) => n,
        Err(_) => {
            eprintln!("Please provide a valid integer N.");
            return;
        }
    };

    let result = count_pythagorean_triples(n);
    println!("Total Pythagorean triples with perimeter <= {}: {}", n, result);
