use std::env;

/// Finds the longest repeating prefix of a binary string.
/// If such a prefix exists, it is returned. Otherwise, returns `None`.
fn find_rep(s: &str) -> Option<&str> {
    let len = s.len();

    // A string must be at least 2 characters long to have a repeating prefix
    if len < 2 {
        return None;
    }

    // Maximum possible prefix length is half the string's length
    let max_n = len / 2;

    // Try each possible prefix length, starting from the largest
    for n in (1..=max_n).rev() {
        let prefix = &s[0..n];

        // Check if the string can be built by repeating the prefix
        let mut valid = true;
        for i in 0..len {
            let pos_in_prefix = i % n;
            if s.as_bytes()[i] != prefix.as_bytes()[pos_in_prefix] {
                valid = false;
                break;
            }
        }

        if valid {
            return Some(prefix);
        }
    }

    None
}

fn main() {
    // Read input from command line
    let args: Vec<String> = env::args().collect();
    let default = String::new();
    let input = args.get(1).unwrap_or(&default);

    // Find and print the repeating prefix, if any
    match find_rep(input) {
        Some(rep) => println!("{}", rep),
        None => println!(""),
    }
}

