struct Solution;

impl Solution {
    pub fn sort_array(nums: Vec<i32>) -> Vec<i32> {
        let mut piles: Vec<Vec<i32>> = Vec::new();
        let mut pile_tops: Vec<i32> = Vec::new();

        for &x in nums.iter() {
            match pile_tops.binary_search(&x) {
                Ok(i) => {
                    piles[i].push(x);
                    pile_tops[i] = x;
                }
                Err(_i) => {
                    piles.push(vec![x]);
                    pile_tops.push(x);
                }
            }
        }

        let mut heap = BinaryHeap::new();
        for (pile_idx, pile) in piles.iter().enumerate() {
            if let Some(&last) = pile.last() {
                heap.push(Reverse((last, pile_idx, pile.len() - 1)));
            }
