use std::collections::VecDeque;

fn expand(s: &str) -> Vec<String> {
    let mut stack = VecDeque::new();
    let mut tokens = VecDeque::new();
    let mut current = String::new();
    for c in s.chars() {
        match c {
            '{' => {
                if !current.is_empty() {
                    tokens.push_back(current.clone());
                    current = String::new();
                }
                stack.push_back(current.clone());
                current = String::new();
            }
            '}' => {
                let inner = current.clone();
                current = String::new();
                let mut inner_tokens = VecDeque::new();
                while let Some(token) = tokens.pop_front() {
                    inner_tokens.push_back(token);
                }
                tokens.push_back(inner_tokens.join(","));
            }
            _ => {
                current.push(c);
            }
        }
    }
    tokens.into_iter().map(|s| s.to_string()).collect()
}

