    let check_digit = (10 - (total % 10)) % 10;
    let last_char = s.chars().nth(8).expect("String too short");
    if last_char.is_digit(10) {
        let last_digit = last_char.to_digit(10).unwrap();
        if last_digit == check_digit {
            println!("True");
        } else {
            println!("False");
        }
    } else {
        println!("False");
    }
}
