fn main() {
    let n_line = io::stdin().lines().next().expect("No input");
    let n_list: Vec<i32> = n_line.unwrap()
        .split_whitespace()
        .map(|s| s.parse().expect("Not a number"))
        .collect();

    let a_line = io::stdin().lines().next().expect("No input");
    let a_list: Vec<i32> = a_line.unwrap()
        .split_whitespace()
        .map(|s| s.parse().expect("Not a number"))
        .collect();

    if n_list.len() != a_list.len() {
        println!("No solution");
        return;
    }

    for i in 0..n_list.len() {
        for j in i + 1..n_list.len() {
            if gcd(n_list[i], n_list[j]) != 1 {
                println!("No solution");
                return;
            }
        }
    }

    let mut N = 1;
    for n in &n_list {
        N *= *n;
    }

    let mut x = 0;
    for i in 0..n_list.len() {
        let M_i = N / n_list[i];
        let y_i = modular_inverse(M_i, n_list[i]);
        x += a_list[i] * M_i * y_i;
    }

    println!("{}", x % N);
}

fn gcd(a: i32, b: i32) -> i32 {
    if b == 0 {
        a
    } else {
        gcd(b, a % b)
    }
}

fn modular_inverse(a: i32, m: i32) -> i32 {
    let (g, x, y) = extended_gcd(a, m);
    if g != 1 {
        panic!("Modular inverse does not exist");
    }
    x % m
}

fn extended_gcd(a: i32, b: i32) -> (i32, i32, i32) {
    if b == 0 {
        (a, 1, 0)
    } else {
        let (g, x1, y1) = extended_gcd(b, a % b);
        (g, y1, x1 - (a / b) * y1)
    }
}

