struct State {
    a1: i32,
    a: i32,
    b1: i32,
    b: i32,
}

impl State {
    fn new() -> Self {
        State { a1: 0, a: 1, b1: 1, b: 0 }
    }

    fn input_term(&self, t: i32) -> State {
        State {
            a1: self.a + self.a1 * t,
            a: self.a1,
            b1: self.b + self.b1 * t,
            b: self.b1,
        }
    }

    fn output_term(&self, t: i32) -> State {
        State {
            a1: self.b1,
            a: self.b,
            b1: self.a1 - self.b1 * t,
            b: self.a - self.b * t,
        }
    }
}

