fn jaro_similarity(s1: &str, s2: &str) -> f64 {
    let len1 = s1.len();
    let len2 = s2.len();
    let max_len = len1.max(len2);
    let window = (max_len / 2) - 1;

    if len1 == 0 || len2 == 0 {
        return 0.0;
    }

    let mut vec_i = Vec::new();
    let mut vec_j = Vec::new();

    for i in 0..len1 {
        for j in 0..len2 {
            if s1.chars().nth(i) == s2.chars().nth(j) && (i as i32 - j as i32).abs() <= window as i32 {
                vec_i.push(i);
