    let mut best_path = Vec::new();
    let mut best_length = 0;

    for next in pokemons.iter() {
        let next_str = next.to_string();
        if visited.contains(&next_str) {
            continue;
        }

        if next_str.starts_with(last_char) {
            let mut new_visited = visited.clone();
            new_visited.insert(next_str.clone());
            let (length, path) = dfs(next, &mut new_visited, pokemons);
            if length > best_length {
                best_length = length;
                best_path = path;
            }
        }
    }

    if best_length == 0 {
        return (1, vec![current.to_string()]);
    }

    let mut path = vec![current.to_string()];
    path.extend(best_path);
    return (path.len(), path);
}

