#[derive(Debug, Clone, PartialEq)]
pub enum Trit {
    True,
    False,
    Maybe,
}

impl Trit {
    pub fn not(self) -> Self {
        match self {
            Trit::True => Trit::False,
            Trit::False => Trit::True,
            Trit::Maybe => Trit::Maybe,
        }
    }

    pub fn and(self, other: Self) -> Self {
        match (self, other) {
            (Trit::True, Trit::True) => Trit::False,
            (Trit::True, Trit::Maybe) => Trit::Maybe,
            (Trit::True, Trit::False) => Trit::False,
            (Trit::Maybe, Trit::True) => Trit::Maybe,
            (Trit::Maybe, Trit::Maybe) => Trit::Maybe,
            (Trit::Maybe, Trit::False) => Trit::False,
            (Trit::False, Trit::True) => Trit::False,
            (Trit::False, Trit::Maybe) => Trit::False,
            (Trit::False, Trit::False) => Trit::False,
        }
    }

    pub fn or(self, other: Self) -> Self {
        match (self, other) {
            (Trit::True, _) => Trit::True,
            (_, Trit::True) => Trit::True,
            (Trit::Maybe, Trit::Maybe) => Trit::Maybe,
            (Trit::Maybe, _) => Trit::Maybe,
            (_, Trit::Maybe) => Trit::Maybe,
            (Trit::False, Trit::False) => Trit::False,
        }
    }

    pub fn if_then(self, other: Self) -> Self {
        match self {
            Trit::False => Trit::True,
            Trit::True => match other {
                Trit::True => Trit::False,
                Trit::False => Trit::False,
                Trit::Maybe => Trit::Maybe,
            },
            Trit::Maybe => other,
        }
    }

    pub fn equiv(self, other: Self) -> Self {
        match (self, other) {
            (Trit::True, Trit::True) => Trit::False,
            (Trit::True, Trit::False) => Trit::False,
            (Trit::True, Trit::Maybe) => Trit::Maybe,
            (Trit::False, Trit::True) => Trit::False,
            (Trit::False, Trit::False) => Trit::Maybe,
            (Trit::False, Trit::Maybe) => Trit::Maybe,
            (Trit::Maybe, Trit::True) => Trit::Maybe,
            (Trit::Maybe, Trit::False) => Trit::Maybe,
            (Trit::Maybe, Trit::Maybe) => Trit::Maybe,
        }
    }
}

