        Err(e) => println!("Error: {}", e),
    }
}

fn topological_sort(dependencies: &HashMap<String, Vec<String>>) -> Result<Vec<String>, String> {
    let mut graph = HashMap::new();
    let mut in_degree = HashMap::new();
    let mut all_nodes = Vec::new();

    for (library, deps) in dependencies {
        let valid_deps = deps.into_iter().filter(|d| *d != library).collect::<Vec<_>>();
        for dep in &valid_deps {
            graph.entry(library.clone()).or_insert_with(Vec::new).push(dep.clone());
            *in_degree.entry(dep.clone()).or_insert(0) += 1;
        }
        all_nodes.push(library.clone());
    }

    let mut all_nodes_set = std::collections::HashSet::new();
    for node in all_nodes {
        all_nodes_set.insert(node.clone());
    }
    for (node, _) in graph {
        all_nodes_set.insert(node.clone());
    }

    let mut queue = VecDeque::new();
    for node in all_nodes_set {
        if in_degree.get(&node).map(|x| *x == 0).unwrap_or(false) {
            queue.push_back(node.clone());
        }
    }

    let mut order = Vec::new();
    while let Some(node) = queue.pop_front() {
        order.push(node.clone());
        if let Some(neighbors) = graph.get(&node) {
            for neighbor in neighbors {
                *in_degree.entry(neighbor.clone()).or_insert(0) -= 1;
                if in_degree.get(&neighbor).map(|x| *x == 0).unwrap_or(false) {
                    queue.push_back(neighbor.clone());
                }
            }
        }
    }

    if order.len() == all_nodes_set.len() {
        Ok(order)
    } else {
        Err("Cycle detected: un-orderable dependencies".to_string())
    }
}

