fn factorize(n: u64) -> Vec<(u64, u64)> {
    let mut temp = n;
    let mut factors = Vec::new();

    // Handle factor 2
    if temp % 2 == 0 {
        let mut count = 0;
        while temp % 2 == 0 {
            temp /= 2;
            count += 1;
        }
        factors.push((2, count));
    }

    // Handle odd factors
    let mut i = 3;
    while i * i <= temp {
        if temp % i == 0 {
            let mut count = 0;
            while temp % i == 0 {
