fn nary_product(lists: Vec<Vec<i32>>) -> Vec<Vec<i32>> {
    if lists.iter().any(|lst| lst.is_empty()) {
        return vec![];
    }

    let mut result = vec![vec![]];
    for list in lists {
        let mut new_result = Vec::new();
        for item in list {
            for mut prefix in result {
                prefix.push(item);
                new_result.push(prefix);
            }
        }
        result = new_result;
    }
