use std::env;

fn halve(n: i32) -> i32 {
    n / 2
}

fn double(n: i32) -> i32 {
    n * 2
}

fn is_even(n: i32) -> bool {
    n % 2 == 0
}

fn ethiopian_multiplication(a: i32, b: i32) -> i32 {
    if a == 0 || b == 0 {
        return 0;
    }

    let mut left = a;
    let mut right = b;
    let mut rows = Vec::new();

    // Record the first row
    rows.push((left, right));
    println!("{} {}", left, right);
    println!("{} {}", left, if is_even(left) { "STRUCK" } else { "KEPT" });

