use std::collections::HashMap;

struct DecomposedItem {
    name: String,
    weight: u32,
    value: u32,
    count: u32,
}

fn main() {
    let items = vec![
        ("map", 9, 150, 1),
        ("compass", 13, 35, 1),
        ("water", 153, 200, 2),
        ("sandwich", 50, 60, 2),
        ("glucose", 15, 60, 2),
        ("tin", 68, 45, 3),
        ("banana", 27, 60, 3),
        ("apple", 39, 40, 3),
        ("cheese", 23, 30, 1),
        ("beer", 52, 10, 3),
        ("suntan cream", 11, 70, 1),
        ("camera", 32, 30, 1),
        ("T-shirt", 24, 15, 2),
        ("trousers", 48, 10, 2),
        ("umbrella", 73, 40, 1),
        ("waterproof trousers", 42, 70, 1),
        ("waterproof overclothes", 43, 75, 1),
        ("note-case", 22, 80, 1),
        ("sunglasses", 7, 20, 1),
        ("towel", 18, 12, 2),
        ("socks", 4, 50, 1),
        ("book", 30, 10, 2),
    ];

    let mut decomposed_items = Vec::new();

    for (name, weight, value, quantity) in &items {
        let mut q = *quantity;
        let mut k = 1;
        while q > 0 {
            let take = std::cmp::min(k, q);
            decomposed_items.push(DecomposedItem {
                name: name.to_string(),
                weight: take * *weight,
                value: take * *value,
                count: take,
            });
            q -= take;
            k *= 2;
        }
    }

    let capacity = 400usize;
    let mut dp = vec![-1i32; capacity + 1];
    dp[0] = 0;

    for item in &decomposed_items {
        for w in (item.weight as usize..=capacity).rev() {
            if dp[w - item.weight as usize] != -1 {
                dp[w] = std::cmp::max(dp[w], dp[w - item.weight as usize] + item.value as i32);
            }
        }
    }

    let max_value = dp.iter().cloned().filter(|&x| x != -1).max().unwrap();

    let mut selected = HashMap::new();
    let mut current_weight = capacity;

    for item in decomposed_items.iter().rev() {
        if current_weight >= item.weight as usize && dp[current_weight] == dp[current_weight - item.weight as usize] + item.value as i32 {
            let count = item.count;
            let name = &item.name;
            selected.entry(name.to_string()).or_insert(0);
            *selected.get_mut(name).unwrap() += count;
            current_weight -= item.weight as usize;
        }
    }

    for (name, _, _, _) in &items {
        if let Some(count) = selected.get(&name.to_string()) {
            if *count > 0 {
                println!("{} {}", count, name);
            }
        }
    }
}

