fn to_negative_base(n: i64, base: i64) -> Vec<u8> {
    let mut digits = Vec::new();
    let mut num = n;
    while num != 0 {
        let mut remainder = num % base;
        if remainder < 0 {
            remainder += base.abs();
        }
        digits.push(remainder as u8);
        num = (num - remainder) / base;
    }
    digits
}

fn from_negative_base(digits: &[u8], base: i64) -> i64 {
    let mut result = 0;
    for &digit in digits {
        result = result * base + digit as i64;
    }
    result
}

