        permutations.push(next);
    }

    permutations
}

fn next_permutation(data: &mut Vec<usize>, directions: &mut Vec<bool>) -> Option<Vec<usize>> {
    // Find the largest element that can move in its current direction
    let mut largest = 0;
    let mut pos = 0;
    for i in (0..data.len()).rev() {
        if data[i] > largest {
            largest = data[i];
            pos = i;
        }
    }

    // Check if the largest can move in its current direction
    let direction = directions[pos];
    let mut new_pos = pos;
    if direction {
        // move right
        if pos + 1 < data.len() {
            new_pos = pos + 1;
        } else {
            // can't move right, reverse directions of smaller elements
            for i in 0..pos {
                directions[i] = !directions[i];
            }
            return None; // no more permutations
        }
    } else {
        // move left
        if pos > 0 {
            new_pos = pos - 1;
        } else {
            // can't move left, reverse directions of smaller elements
            for i in 0..pos {
                directions[i] = !directions[i];
            }
            return None;
        }
    }

    // Swap the largest with the adjacent element
    data.swap(pos, new_pos);

    // Reverse directions of elements smaller than the largest
    for i in 0..pos {
        directions[i] = !directions[i];
    }

    Some(data.clone())
}

