use std::collections::{HashMap, HashSet, VecDeque};

pub fn topological_sort(dependencies: HashMap<String, Vec<String>>) -> Result<Vec<String>, String> {
    // Collect all libraries
    let mut all_libraries = dependencies.keys().cloned().collect::<HashSet<_>>();
    for (lib, deps) in &dependencies {
        all_libraries.extend(deps.iter().cloned());
    }

    // Initialize in_degree for all libraries to zero
    let mut in_degree = HashMap::new();
    for lib in &all_libraries {
        in_degree.insert(lib.clone(), 0);
    }

    // Build the graph and update in_degree
    let mut graph = HashMap::new();
    for (lib, deps) in &dependencies {
        let unique_deps: HashSet<String> = deps
            .iter()
            .filter(|d| *d != lib)
            .cloned()
            .collect();
        for dep in unique_deps {
            graph.entry(dep.clone()).or_insert_with(Vec::new).push(lib.clone());
            *in_degree.get_mut(&dep).unwrap() += 1;
        }
    }

    // Kahn's algorithm
    let mut queue = VecDeque::new();
    for lib in &all_libraries {
        if in_degree[lib] == 0 {
            queue.push_back(lib.clone());
        }
    }

    let mut processed = 0;
    let mut result = Vec::new();
    while let Some(node) = queue.pop_front() {
        result.push(node.clone());
        processed += 1;
        if let Some(neighbors) = graph.get(&node) {
            for neighbor in neighbors {
                *in_degree.get_mut(neighbor).unwrap() -= 1;
                if in_degree[neighbor] == 0 {
                    queue.push_back(neighbor.clone());
                }
            }
        }
    }

    if processed != all_libraries.len() {
        return Err("Cycle detected: unorderable dependencies".to_string());
    }

    Ok(result)
}

