        return Err(());
    }

    let first_byte = bytes[0];
    let mut code_point = 0;
    let mut num_bytes = 0;

    if first_byte & 0b10000000 == 0 {
        num_bytes = 1;
        code_point = first_byte as u32;
    } else if first_byte & 0b11100000 == 0b11000000 {
        num_bytes = 2;
        code_point = ((first_byte & 0b00111111) as u32) << 6;
    } else if first_byte & 0b11110000 == 0b11100000 {
        num_bytes = 3;
        code_point = ((first_byte & 0b00001111) as u32) << 12;
    } else if first_byte & 0b11111000 == 0b11110000 {
        num_bytes = 4;
        code_point = ((first_byte & 0b00000111) as u32) << 18;
    } else {
        return Err(());
    }

    for i in 0..num_bytes {
        let byte = bytes[i];
        if i == 0 {
            continue;
        }
        if (byte & 0b11000000) != 0b10000000 {
            return Err(());
        }
        code_point |= ((byte & 0b00111111) as u32) << ((num_bytes - 1 - i) * 6);
    }

    Ok(code_point)
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        println!("Usage: <program> <special char>");
        return;
    }

    let input = &args[1];
    let c = input.chars().next().unwrap();
    let cp = c as u32;

    let encoded = encode_code_point(cp);
    for byte in encoded {
        print!("{:02X} ", byte);
    }
    println!();
}

